INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('786d613d-e0fe-5813-ad82-e63bc2dd7a27', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Membiasakan Diri (～ようにする)', 'Pelajari cara menyatakan usaha sadar dan rutinitas sehat atau target belajar dengan pola ～ようにする dalam keseharian di Jepang.', 'curriculum', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('cbfa037b-0a6f-5993-8fd1-1d87ccdd0486', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Keputusan Resmi (～ことになる)', 'Kuasai pola ～ことになる dan ～ことになっている untuk menyampaikan pengumuman kantor, penugasan, dan aturan organisasi.', 'curriculum', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('b232b58b-bc6a-5799-9aed-addf086ba391', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Berkat Dukungan (～おかげで)', 'Ungkapkan rasa syukur dan pencapaian positif berkat bantuan orang lain atau kondisi yang mendukung dengan pola ～おかげで.', 'curriculum', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('bccb108f-4ae1-5f87-a772-3a558268f645', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Akibat & Kendala (～せいで)', 'Sampaikan penyebab kendala transportasi, cuaca buruk, atau masalah teknis secara tepat dengan pola ～せいで dan ～せいか.', 'curriculum', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('0b09459e-73c2-57b2-b6e7-990e696dc333', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Sikap & Perbandingan (～に対して)', 'Gunakan ～に対して untuk menunjukkan sasaran sikap dalam layanan pelanggan, tanggapan terhadap usulan, dan perbandingan dua hal.', 'curriculum', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('3b8b30d9-1b7b-5afd-8805-cb7871188df5', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Mumpung & Selagi (～うちに)', 'Manfaatkan pola ～うちに untuk menyatakan kesempatan yang perlu diambil sebelum kondisi berubah serta perubahan yang terjadi tanpa disadari.', 'curriculum', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('233fdb02-aded-57bc-9503-e0e9087bf338', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Dugaan Logis (～はずだ)', 'Gunakan ～はずだ dan ～はずがない untuk menyampaikan perkiraan berdasarkan bukti, jadwal pengiriman, dan verifikasi di kantor.', 'curriculum', 7, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('2f556335-b5a4-5d61-b196-8532421fe1f2', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Bentuk Pasif (～られる)', 'Pahami kalimat pasif bahasa Jepang untuk berita resmi, evaluasi kerja, serta pasif penderitaan dalam pengalaman sehari-hari.', 'curriculum', 8, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('8b1590db-2b67-5793-8a24-f6c2afae1fc8', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Baru Saja (～たばかり)', 'Ceritakan adaptasi lingkungan baru, pindah rumah, dan pengalaman awal kerja di Jepang menggunakan pola ～たばかり.', 'curriculum', 9, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('586d7103-1d5f-5c15-9dcc-69e13624da71', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Ragam & Penyebab (～によって)', 'Kuasai penggunaan serbaguna ～によって untuk menyatakan perbedaan budaya, cara kerja, penyebab resmi, serta persiapan penuh menuju JLPT N3.', 'curriculum', 10, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('81c64d9f-c591-418f-ad2a-9c715a3ff1c3', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'Ujian Simulasi Kesiapan JLPT N3', 'Evaluasi menyeluruh kesiapan JLPT N3 mencakup membaca, mendengar, menyusun kalimat, dan berbicara dari Unit 1 hingga Unit 10.', 'diagnostic_exam', 99, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
