INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('205ab222-250b-5cbb-aaa1-9c3a54af84c3', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: もう十時なので、そろそろ彼が到着 ___ はずです。', '{"options":["する","して","します","しよう"],"translation":"Karena sudah jam sepuluh, sebentar lagi dia seharusnya tiba.","sentence_template":"もう十時なので、そろそろ彼が到着 [blank] はずです。"}'::jsonb, '{"selected":"する"}'::jsonb, NULL, NULL, 'Bentuk kamus 到着する langsung diikuti はずです.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bafd4667-72e2-5706-bb05-f32afc18bbdf', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Pilih bentuk penyangkalan logis: 鍵をかけたので、誰かが入れる ___ がありません。', '{"options":["はず","こと","よう","ため"],"translation":"Karena sudah dikunci, tidak mungkin ada orang yang bisa masuk.","sentence_template":"鍵をかけたので、誰かが入れる [blank] がありません。"}'::jsonb, '{"selected":"はず"}'::jsonb, NULL, NULL, '入れるはずがありません berarti tidak mungkin bisa masuk.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e1b5a376-f465-5067-9b97-b5028166c9c3', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Mengapa pembicara yakin rapat akan selesai sebelum pukul lima?', '{"options":[{"id":"opt_1","text":"Karena pesertanya hanya tiga orang"},{"id":"opt_2","text":"Karena ruang rapat harus dikosongkan pukul lima"},{"id":"opt_3","text":"Karena agendanya hanya ada dua topik"},{"id":"opt_4","text":"Karena pimpinan rapat akan pergi dinas sore ini"}],"audio_text":"議題は二つだけですから、五時までには終わるはずです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '議題は二つだけですから berarti karena agenda rapatnya hanya dua.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d113c0ec-f8f7-578f-8d47-cec7ac89c537', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Apa yang mengherankan pembicara tentang AC ruangan?', '{"options":[{"id":"opt_1","text":"AC ruangan berbunyi sangat keras"},{"id":"opt_2","text":"Tagihan listrik bulan ini naik drastis"},{"id":"opt_3","text":"Pengendali jarak jauh AC hilang dari meja"},{"id":"opt_4","text":"Padahal suhunya sudah diturunkan, ruangan tidak kunjung sejuk"}],"audio_text":"さっき温度を下げたはずなのに、部屋がぜんぜん涼しくなりません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '温度を下げたはずなのに、ぜんぜん涼しくなりません berarti padahal sudah menurunkan suhu, tidak dingin sama sekali.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b74f433-032c-5aa4-b24b-ad9e7c84b6aa', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Karena hari ini hari Minggu, kantor seharusnya libur."', '{"romaji":"Kyou wa nichiyoubi da kara, kaisha wa yasumi no hazu desu.","tokens":["今日は日曜日だから、","はずです。","休みの","はずがありません。","休みな","会社は"],"target_translation":"Karena hari ini hari Minggu, kantor seharusnya libur."}'::jsonb, '["今日は日曜日だから、","会社は","休みの","はずです。"]'::jsonb, NULL, NULL, 'Nomina 休み + の + はずです.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92fbbc15-ff71-5c8f-ae32-988b792c226c', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Paket itu seharusnya sampai besok pagi."', '{"romaji":"Sono nimotsu wa ashita no gozenchuu ni todoku hazu desu.","display_text":"その荷物は明日の午前中に届くはずです。","phonetic_breakdown":["so-no ni-mo-tsu wa","a-shi-ta no","go-zen-chuu ni","to-do-ku","ha-zu de-su"]}'::jsonb, '{"expected_transcript":"その荷物は明日の午前中に届くはずです。"}'::jsonb, NULL, NULL, '午前中 (gozenchuu) berarti sepanjang pagi hingga jam 12 siang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('041baf6a-42e3-4740-b707-3d1ca5363322', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この店は人気があるから、週末はかなり___はずです。', '{"options":["混め","混んで","混みに","混む"],"translation":"Karena toko ini populer, saat akhir pekan seharusnya cukup ramai.","sentence_template":"この店は人気があるから、週末はかなり[blank]はずです。"}'::jsonb, '{"selected":"混む"}'::jsonb, NULL, NULL, 'Kata kerja bentuk kamus (混む) langsung diikuti はずです.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be33ef53-fca8-4b0b-9192-48cf002d7f2f', '06e6d1cd-de9a-524d-bb58-c8d488e1137f', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tadi ada telepon, kepala bagian seharusnya akan segera datang."', '{"romaji":"Sakki denwa ga arimashita kara, buchou wa mou sugu kuru hazu desu.","display_text":"さっき電話がありましたから、部長はもうすぐ来るはずです。","phonetic_breakdown":["sak-ki","den-wa-ga","a-ri-ma-shi-ta-ka-ra","bu-chou-wa","mou-su-gu","ku-ru","ha-zu-de-su"]}'::jsonb, '{"expected_transcript":"さっき電話がありましたから、部長はもうすぐ来るはずです。"}'::jsonb, NULL, NULL, '来るはずです didasarkan pada bukti objektif berupa telepon tadi.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa1297ff-03e3-48ff-81ab-9a950ec51a0c', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼女は昨日熱が高かったので、今日は___はずです。', '{"options":["休んで","休む","休め","休み"],"translation":"Karena kemarin demamnya tinggi, hari ini dia seharusnya beristirahat/absen.","sentence_template":"彼女は昨日熱が高かったので、今日は[blank]はずです。"}'::jsonb, '{"selected":"休む"}'::jsonb, NULL, NULL, '休む (bentuk biasa) + はずです.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d747f4c9-0ef0-44bd-91bb-9c002fcb232e', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このレストランは駅前で___はずなのに、今日は珍しく空いていますね。', '{"options":["にぎやか","にぎやかな","にぎやかだ","にぎやかの"],"translation":"Restoran ini di depan stasiun sehingga seharusnya ramai, tapi anehnya hari ini sepi ya.","sentence_template":"このレストランは駅前で[blank]はずなのに、今日は珍しく空いていますね。"}'::jsonb, '{"selected":"にぎやかな"}'::jsonb, NULL, NULL, 'Kata sifat な (にぎやか) memerlukan な sebelum はず -> にぎやかなはず.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0af8e9d4-82b4-477d-9c4b-4ac1089514c8', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan konfirmasi di ruang rapat berikut. Apa yang sedang dipastikan pembicara?', '{"options":[{"id":"opt_1","text":"Email undangan rapat hanya dikirim kepada atasan"},{"id":"opt_2","text":"Rapat dibatalkan sehingga tidak ada email undangan"},{"id":"opt_3","text":"Pembicara lupa mengirim email undangan rapat kepada siapa pun"},{"id":"opt_4","text":"Pembicara yakin seharusnya sudah mengirim email undangan rapat ke semua orang dan mengecek apakah ada yang belum menerima"}],"audio_text":"会議の案内メールは全員に送ったはずですが、届いていない方はいらっしゃいますか。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '送ったはずです menunjukkan keyakinan berdasarkan tindakan yang telah dilakukan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fe67ae80-01ac-4974-9cd4-5960937d3f0e', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Menurut prakiraan cuaca seharusnya cerah, padahal hujan malah turun."', '{"romaji":"Tenki yohou de wa hareru hazu datta noni, ame ga futte kimashita.","tokens":["降って","雨が","はず","きました。","天気予報では","晴れる","晴れて","を","だったのに、"],"target_translation":"Menurut prakiraan cuaca seharusnya cerah, padahal hujan malah turun."}'::jsonb, '["天気予報では","晴れる","はず","だったのに、","雨が","降って","きました。"]'::jsonb, NULL, NULL, '～はずだったのに menyatakan harapan/prediksi masa lalu yang ternyata meleset.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b974146e-7eaf-4bdc-9f13-6d4f8b3b2c10', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼はまだこの計画を知らないので、反対する___。', '{"options":["おかげです","はずがありません","ばかりです","はずです"],"translation":"Karena dia belum tahu rencana ini, tidak mungkin dia menentangnya.","sentence_template":"彼はまだこの計画を知らないので、反対する[blank]。"}'::jsonb, '{"selected":"はずがありません"}'::jsonb, NULL, NULL, '反対するはずがありません menyangkal kemungkinan secara logis.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9e9422f-acc7-4fe7-be99-934ed96b3d2f', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena saya sudah menyalakan AC, seharusnya ruangan segera menjadi sejuk."', '{"romaji":"Eakon no suicchi o ireta node, sugu suzushiku naru hazu desu.","display_text":"エアコンのスイッチを入れたので、すぐ涼しくなるはずです。","phonetic_breakdown":["e-a-kon-no","su-it-chi-o","i-re-ta-no-de","su-gu","su-zu-shi-ku","na-ru","ha-zu-de-su"]}'::jsonb, '{"expected_transcript":"エアコンのスイッチを入れたので、すぐ涼しくなるはずです。"}'::jsonb, NULL, NULL, '涼しくなるはずです menyatakan hasil logis dari menyalakan AC.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8288e040-5bdf-40dd-9aab-6edf60c58216', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan keluhan berikut. Apa yang membuat pembicara heran?', '{"options":[{"id":"opt_1","text":"Padahal merasa sudah mengisi daya dengan baik kemarin, tapi pagi ini baterai tersisa 10 persen"},{"id":"opt_2","text":"Pembicara lupa mengisi daya ponsel semalam"},{"id":"opt_3","text":"Ponsel terisi penuh seratus persen pagi ini"},{"id":"opt_4","text":"Baterai ponsel baru saja diganti kemarin"}],"audio_text":"昨日しっかり充電したはずなのに、今朝見たらバッテリーが十パーセントしか残っていませんでした。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '充電したはずなのに menunjukkan kontras antara ingatan dan fakta.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53d8e9d7-d618-4e84-90e2-154c947a1d20', '080f5e31-6a61-420a-9b93-d228d4ecef7f', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Yamada-san seharusnya sudah pulang ke negaranya kemarin."', '{"romaji":"Yamada-san wa kinou kikoku shita hazu desu yo.","tokens":["山田さんは","ですよ。","帰国した","はず","昨日","を","帰国して"],"target_translation":"Yamada-san seharusnya sudah pulang ke negaranya kemarin."}'::jsonb, '["山田さんは","昨日","帰国した","はず","ですよ。"]'::jsonb, NULL, NULL, '帰国した (bentuk lampau biasa) + はずです.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('794a6393-f9f5-5d3e-ba82-ce344c6de3f1', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat lintas budaya: 国が変われば、食事の ___ も大きく異なります。', '{"options":["マナー","エラー","カラー","タイマー"],"translation":"Jika negaranya berbeda, tata krama/kebiasaan makannya pun sangat berbeda.","sentence_template":"国が変われば、食事の [blank] も大きく異なります。"}'::jsonb, '{"selected":"マナー"}'::jsonb, NULL, NULL, '食事のマナー (shokuji no manaa) berarti etika atau tata krama makan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('365a2b5c-0b8f-5e1a-adec-2a4064ad7978', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'reading', 'fill_blank', 'Pilih kata untuk cara kerja: 効率的な仕事の ___ を探しています。', '{"options":["方法","方向","訪問","放送"],"translation":"Saya sedang mencari metode kerja yang efisien.","sentence_template":"効率的な仕事の [blank] を探しています。"}'::jsonb, '{"selected":"方法"}'::jsonb, NULL, NULL, '方法 (houhou) berarti metode atau cara.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('748e36b2-20c3-57f1-b28b-4537b542f15a', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat keragaman: 日本は ___ によって方言や料理が違います。', '{"options":["地域","地球","地下","地図"],"translation":"Di Jepang, dialek dan masakannya berbeda tergantung wilayahnya.","sentence_template":"日本は [blank] によって方言や料理が違います。"}'::jsonb, '{"selected":"地域"}'::jsonb, NULL, NULL, '地域 (chiiki) berarti wilayah atau daerah.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4808ab0c-1f24-592c-ad90-c0c59d20c64d', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'reading', 'fill_blank', 'Pilih kata untuk ujian N3: 試験の ___ に合わせて、本番と同じ時間で練習します。', '{"options":["形式","景色","知識","意識"],"translation":"Menyesuaikan dengan format ujian, saya berlatih dengan durasi sama seperti ujian asli.","sentence_template":"試験の [blank] に合わせて、本番と同じ時間で練習します。"}'::jsonb, '{"selected":"形式"}'::jsonb, NULL, NULL, '試験の形式 (shiken no keishiki) berarti format/pola soal ujian.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b36bebf-2c0a-561f-bcce-de176bb82b4a', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'listening', 'listening_choice', 'Apa yang berbeda tergantung musim menurut pembicara?', '{"options":[{"id":"opt_1","text":"Hidangan khusus memakai bahan musiman yang disediakan penginapan"},{"id":"opt_2","text":"Harga tiket kereta menuju penginapan tersebut"},{"id":"opt_3","text":"Jam buka pemandian air panas di lantai dua"},{"id":"opt_4","text":"Jumlah kamar yang boleh dipesan oleh wisatawan asing"}],"audio_text":"この旅館では、季節ごとに旬の食材を使った特別な料理が用意されています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '季節ごとに旬の食材を使った特別な料理 berarti hidangan khusus berbahan musiman tiap musim.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53e5710c-223f-504a-8efe-4655f236c0e1', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', NULL, 'listening', 'listening_choice', 'Bagaimana cara belajar yang paling efektif menurut pembicara?', '{"options":[{"id":"opt_1","text":"Belajar tepat tiga jam setiap malam tanpa jeda"},{"id":"opt_2","text":"Menemukan metode belajar yang sesuai dengan ritme hidup sendiri"},{"id":"opt_3","text":"Menghafal seluruh kamus dari halaman pertama"},{"id":"opt_4","text":"Hanya belajar bersama kelompok besar setiap akhir pekan"}],"audio_text":"人それぞれ生活リズムが違うので、自分に合った勉強法を見つけることが一番大切です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '自分に合った勉強法を見つけることが一番大切です berarti menemukan cara belajar yang cocok untuk diri sendiri adalah yang terpenting.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ba317c4c-1fd2-4ac8-b1d6-e2c5faa0ec9c', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 国や地域の___によって、食事のマナーは大きく異なります。', '{"options":["文化","欠席","渋滞","故障"],"translation":"Tergantung pada budaya negara atau daerah, etika makan sangat berbeda.","sentence_template":"国や地域の[blank]によって、食事のマナーは大きく異なります。"}'::jsonb, '{"selected":"文化"}'::jsonb, NULL, NULL, '文化によって berarti ''tergantung pada budayanya''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('580d5e01-023f-4db8-b55a-d2a3ac95d457', '0d9d8fc5-ebaa-5327-9325-7da1a7513c6b', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan pengumuman resmi berikut. Apa penyebab pemadaman listrik?', '{"options":[{"id":"opt_1","text":"Pemadaman listrik dilakukan untuk perbaikan rutin"},{"id":"opt_2","text":"Akibat dampak topan, terjadi pemadaman listrik di sebagian wilayah"},{"id":"opt_3","text":"Listrik di seluruh wilayah sudah kembali menyala normal"},{"id":"opt_4","text":"Topan tidak memberikan dampak apa pun pada aliran listrik"}],"audio_text":"台風の影響によって、一部の地域で停電が発生しております。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '影響によって adalah ungkapan formal untuk menyatakan penyebab resmi.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3727adb-181c-5656-9212-873e5e67dcea', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat baru datang: 先月日本に ___ ばかりなので、まだ道がわかりません。', '{"options":["来た","来る","来て","来ます"],"translation":"Karena baru saja datang ke Jepang bulan lalu, saya belum tahu jalan.","sentence_template":"先月日本に [blank] ばかりなので、まだ道がわかりません。"}'::jsonb, '{"selected":"来た"}'::jsonb, NULL, NULL, 'Pola ～たばかり selalu memakai verba Bentuk-TA (来たばかり).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('05af24c7-1b33-51f9-83ad-0a5fe04f81d1', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Pilih penghubung sebelum nomina: これは昨日 ___ ばかりのパソコンです。', '{"options":["買った","買う","買って","買います"],"translation":"Ini adalah laptop yang baru saja dibeli kemarin.","sentence_template":"これは昨日 [blank] ばかりのパソコンです。"}'::jsonb, '{"selected":"買った"}'::jsonb, NULL, NULL, 'Verba Bentuk-TA + ばかりの + Nomina (買ったばかりのパソコン).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d288d714-4f91-54fa-8747-5a00a5684117', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Pilih bentuk penghubung alasan: 入社したばかり ___ 、わからないことが多いです。', '{"options":["なので","のので","だので","でので"],"translation":"Karena baru saja masuk kerja, banyak hal yang belum saya ketahui.","sentence_template":"入社したばかり [blank] 、わからないことが多いです。"}'::jsonb, '{"selected":"なので"}'::jsonb, NULL, NULL, 'ばかり berperilaku seperti nomina/adjektiva-NA sebelum ので -> ばかりなので.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('562dbef8-6750-56ab-ba69-ed128244fac4', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Saya baru saja selesai makan siang."', '{"romaji":"Hirugohan o tabeta bakari desu.","tokens":["食べた","食べて","食べる","昼ごはんを","ばかりです。"],"target_translation":"Saya baru saja selesai makan siang."}'::jsonb, '["昼ごはんを","食べた","ばかりです。"]'::jsonb, NULL, NULL, '食べた (Bentuk-TA) + ばかりです berarti baru saja makan.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a114fcb-c63d-5418-94b6-398c3e5cb1da', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Ini adalah toko yang baru saja dibuka bulan ini."', '{"romaji":"Kore wa kongetsu oopun shita bakari no mise desu.","tokens":["ばかりな","店です。","今月オープンした","ばかりの","オープンして","これは"],"target_translation":"Ini adalah toko yang baru saja dibuka bulan ini."}'::jsonb, '["これは","今月オープンした","ばかりの","店です。"]'::jsonb, NULL, NULL, 'Saat menerangkan nomina (店), gunakan ばかりの (bukan ばかりな).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4ee9af0-1b72-5329-866b-8dd18985361e', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Mengapa pembicara menolak ajakan minum kopi sekarang?', '{"options":[{"id":"opt_1","text":"Karena dokter melarangnya minum kafein"},{"id":"opt_2","text":"Karena ia harus segera menghadiri rapat dengan klien"},{"id":"opt_3","text":"Karena ia baru saja minum kopi di kantin tadi"},{"id":"opt_4","text":"Karena ia tidak menyukai rasa kopi di mesin kantor"}],"audio_text":"すみません、さっき食堂でコーヒーを飲んだばかりなんです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'さっき食堂でコーヒーを飲んだばかりなんです berarti baru saja minum kopi di kantin tadi.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ad51bc8b-fabb-4c7e-8086-f71b8bc2fce9', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: さっき昼ごはんを食べた___なのに、もうお腹が空きました。', '{"options":["はず","せい","おかげ","ばかり"],"translation":"Padahal baru saja makan siang tadi, saya sudah lapar lagi.","sentence_template":"さっき昼ごはんを食べた[blank]なのに、もうお腹が空きました。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, 'Kata kerja bentuk た + ばかり menyatakan suatu aksi baru saja selesai menurut perasaan pembicara.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('829498f6-97b0-4b56-972b-16b3264568d8', '0df92274-024d-5e39-8c25-fda92ab32f74', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Komputer ini padahal baru saja dibeli bulan lalu, tapi sudah rusak."', '{"romaji":"Kono pasokon wa sengetsu katta bakari nanoni kowaremashita.","tokens":["を","パソコンは","ばかり","壊れました。","この","先月","買った","なのに","買う"],"target_translation":"Komputer ini padahal baru saja dibeli bulan lalu, tapi sudah rusak."}'::jsonb, '["この","パソコンは","先月","買った","ばかり","なのに","壊れました。"]'::jsonb, NULL, NULL, '買ったばかり dapat dipakai meski sudah berlalu sebulan jika pembicara merasa itu masih sangat baru.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('65b5b57a-3ef7-4e82-92ad-9c111b972a48', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 引っ越してきた___で、近所のスーパーの場所もまだ分かりません。', '{"options":["せい","はず","ばかり","おかげ"],"translation":"Karena baru saja pindah ke sini, saya belum tahu letak supermarket terdekat pun.","sentence_template":"引っ越してきた[blank]で、近所のスーパーの場所もまだ分かりません。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '引っ越してきたばかりで menunjukkan alasan mengapa belum mengenal lingkungan sekitar.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b78c6df9-6220-42f3-93cf-6d6c3e57d736', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: これは昨日___ばかりの焼きたてのパンではなく、今朝焼いたものです。', '{"options":["作って","作った","作ろう","作る"],"translation":"Ini bukan roti yang baru dibuat kemarin, melainkan yang dipanggang pagi ini.","sentence_template":"これは昨日[blank]ばかりの焼きたてのパンではなく、今朝焼いたものです。"}'::jsonb, '{"selected":"作った"}'::jsonb, NULL, NULL, 'Kata kerja bentuk た (作った) + ばかりの menerangkan kata benda.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8483453e-cc13-4466-a455-5af098ada4cd', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan cerita berikut. Mengapa pembicara masih takut menyetir di jalan tol?', '{"options":[{"id":"opt_1","text":"Sudah sangat berpengalaman menyetir di jalan tol"},{"id":"opt_2","text":"Suka menyetir dengan kecepatan tinggi di jalan tol"},{"id":"opt_3","text":"Belum memiliki SIM sama sekali"},{"id":"opt_4","text":"Karena baru saja mendapatkan SIM, masih agak takut menyetir di jalan tol"}],"audio_text":"免許を取ったばかりなので、高速道路の運転はまだちょっと怖いです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '取ったばかり menekankan bahwa pengalamannya masih sangat baru.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('573a77a5-f9bc-40cb-a3f3-b81911d46b24', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Drama itu baru saja saya mulai tonton, tetapi sangat menarik."', '{"romaji":"Sono dorama wa mihajimeta bakari desu ga, totemo omoshiroi desu.","tokens":["見始める","ドラマは","が","面白いです。","ですが、","ばかり","とても","その","見始めた"],"target_translation":"Drama itu baru saja saya mulai tonton, tetapi sangat menarik."}'::jsonb, '["その","ドラマは","見始めた","ばかり","ですが、","とても","面白いです。"]'::jsonb, NULL, NULL, '見始めた + ばかりです.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a64b431d-1f3c-45e4-afd5-cc4199f7efbb', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 今の仕事に転職した___なので、毎日新しい発見があります。', '{"options":["に対して","はず","ばかり","うち"],"translation":"Karena baru saja pindah ke pekerjaan sekarang, setiap hari ada penemuan baru.","sentence_template":"今の仕事に転職した[blank]なので、毎日新しい発見があります。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '転職したばかり menyatakan fase awal karier baru.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5df8c778-38ec-4e2a-b4b7-4d0b98eeb5c8', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena saya baru saja pulang tadi, izinkan saya beristirahat sebentar."', '{"romaji":"Sakki kaette kita bakari na node, sukoshi yasumasete kudasai.","display_text":"さっき帰ってきたばかりなので、少し休ませてください。","phonetic_breakdown":["sak-ki","ka-et-te-ki-ta","ba-ka-ri-na-no-de","su-ko-shi","ya-su-ma-se-te","ku-da-sai"]}'::jsonb, '{"expected_transcript":"さっき帰ってきたばかりなので、少し休ませてください。"}'::jsonb, NULL, NULL, 'ばかり diikuti な sebelum ので -> ばかりなので.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d9632fa-d94b-4b70-bfec-d4a7754f2758', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan penjelasan pemandu wisata berikut. Apa keistimewaan jembatan tersebut?', '{"options":[{"id":"opt_1","text":"Jembatan ini baru saja selesai tahun ini dan terlihat indah dengan lampu hias saat malam"},{"id":"opt_2","text":"Jembatan ini sudah tua dan gelap di malam hari"},{"id":"opt_3","text":"Jembatan ini sedang dalam tahap pembongkaran"},{"id":"opt_4","text":"Jembatan ini baru akan dibangun tahun depan"}],"audio_text":"この橋は今年完成したばかりで、夜になるとライトアップされてとてもきれいですよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '完成したばかり menegaskan bahwa jembatan itu masih sangat baru.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15e0b768-a386-4bfb-9036-2b671e295f8b', '1416aa4e-cde4-4f6b-ae74-ea40d198d286', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Mereka berdua adalah pengantin baru yang baru saja menikah bulan lalu."', '{"romaji":"Futari wa sengetsu kekkon shita bakari no shinkon desu.","tokens":["結婚する","先月","ばかり","を","結婚した","二人は","の","新婚です。"],"target_translation":"Mereka berdua adalah pengantin baru yang baru saja menikah bulan lalu."}'::jsonb, '["二人は","先月","結婚した","ばかり","の","新婚です。"]'::jsonb, NULL, NULL, '結婚したばかりの menerangkan 新婚 (pengantin baru).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('48d4f408-beb4-4d2f-ba4f-a22db3b7af0a', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan arahan berikut. Apa yang diyakini pembicara?', '{"options":[{"id":"opt_1","text":"Peta ini sudah lama sehingga pasti membuat tersesat"},{"id":"opt_2","text":"Kalau berjalan sesuai peta ini, tidak mungkin tersesat"},{"id":"opt_3","text":"Sebaiknya tidak menggunakan peta saat berjalan di sini"},{"id":"opt_4","text":"Pembicara sendiri sedang tersesat di jalan ini"}],"audio_text":"この地図のとおりに歩けば、迷うはずがありませんよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '迷うはずがありません menyatakan keyakinan kuat bahwa lawan bicara tidak akan tersesat.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a431ad39-5f06-439c-a7a5-df2225676f15', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pekerjaan ini seharusnya selesai dalam hari ini."', '{"romaji":"Kono shigoto wa kyoujuu ni owaru hazu desu.","display_text":"この仕事は今日中に終わるはずです。","phonetic_breakdown":["ko-no","shi-go-to-wa","kyou-juu-ni","o-wa-ru","ha-zu-de-su"]}'::jsonb, '{"expected_transcript":"この仕事は今日中に終わるはずです。"}'::jsonb, NULL, NULL, '終わるはずです dipakai untuk melaporkan estimasi penyelesaian tugas.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b75d1ad-e0a0-4ee5-ba48-5fef71ccc4ae', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Di dalam kulkas seharusnya masih tersisa susu."', '{"romaji":"Reizouko ni gyuunyuu ga mada nokotte iru hazu desu.","tokens":["です。","まだ","残っている","牛乳が","冷蔵庫に","を","はず","残って"],"target_translation":"Di dalam kulkas seharusnya masih tersisa susu."}'::jsonb, '["冷蔵庫に","牛乳が","まだ","残っている","はず","です。"]'::jsonb, NULL, NULL, '残っている (bentuk biasa) + はずです.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0fc08a5-3764-4728-9b07-edb2088c7b87', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: あの有名な小説なら、この図書館に___はずです。', '{"options":["あれ","ある","あって","あり"],"translation":"Kalau novel terkenal itu, seharusnya ada di perpustakaan ini.","sentence_template":"あの有名な小説なら、この図書館に[blank]はずです。"}'::jsonb, '{"selected":"ある"}'::jsonb, NULL, NULL, 'ある + はずです.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4503b666-6cda-4267-b580-1ef2e8d51688', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan deduksi berikut. Mengapa pembicara yakin bukan Sato yang memakan kuenya?', '{"options":[{"id":"opt_1","text":"Sato membelikan kue manis ini untuk semua orang"},{"id":"opt_2","text":"Sato sangat menyukai kue ini dan pasti sudah memakannya"},{"id":"opt_3","text":"Karena Sato tidak suka makanan manis, tidak mungkin dia yang memakan kue ini"},{"id":"opt_4","text":"Kue ini bukan makanan manis"}],"audio_text":"佐藤さんは甘いものが苦手ですから、このケーキを食べたはずがありません。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '食べたはずがありません adalah kesimpulan logis negatif.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b1b74737-740e-4ff3-82c9-b4f0c91b7a6c', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Materinya seharusnya sudah saya simpan di folder ini."', '{"romaji":"Shiryou wa kono foruda ni hozon shita hazu desu.","display_text":"資料はこのフォルダに保存したはずです。","phonetic_breakdown":["shi-ryou-wa","ko-no","fo-ru-da-ni","ho-zon-shi-ta","ha-zu-de-su"]}'::jsonb, '{"expected_transcript":"資料はこのフォルダに保存したはずです。"}'::jsonb, NULL, NULL, '保存したはずです menyatakan keyakinan berdasarkan ingatan tindakan sendiri.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ae2b1e6-e366-434f-90d5-f323ec01b289', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Karena berangkat dua jam lalu, seharusnya sekarang sudah sampai."', '{"romaji":"Nijikan mae ni shuppatsu shita kara, mou tsuite iru hazu da.","tokens":["着いている","出発したから、","もう","二時間前に","着いて","だ。","はず","を"],"target_translation":"Karena berangkat dua jam lalu, seharusnya sekarang sudah sampai."}'::jsonb, '["二時間前に","出発したから、","もう","着いている","はず","だ。"]'::jsonb, NULL, NULL, '着いている + はずだ.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c197989c-7bf4-4af5-98ae-e37ffa6af0ef', '149bb88a-ad0c-4b28-8226-536ad1071b12', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 何度も確認したので、計算ミスは___はずです。', '{"options":["なくて","なかったな","ない","なく"],"translation":"Karena sudah dicek berkali-kali, seharusnya tidak ada kesalahan hitung.","sentence_template":"何度も確認したので、計算ミスは[blank]はずです。"}'::jsonb, '{"selected":"ない"}'::jsonb, NULL, NULL, 'ない (bentuk negatif biasa) + はずです.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ae390af-5edd-4eaf-826b-aae0c6b9d3ed', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 健康を維持するため、毎日最低三十分は___ようにしています。', '{"options":["運動する","運動して","運動しよう","運動した"],"translation":"Untuk menjaga kesehatan, saya membiasakan berolahraga minimal tiga puluh menit setiap hari.","sentence_template":"健康を維持するため、毎日最低三十分は[blank]ようにしています。"}'::jsonb, '{"selected":"運動する"}'::jsonb, NULL, NULL, 'Bentuk kamus + ようにしています menyatakan kebiasaan sadar yang terus dijalankan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1c86f974-a6de-4abc-81b4-44265aff59e0', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan kabar kerja berikut. Apa keputusan yang disampaikan?', '{"options":[{"id":"opt_1","text":"Pembicara baru saja menyelesaikan proyek lama bulan ini"},{"id":"opt_2","text":"Proyek baru tersebut dibatalkan mulai bulan depan"},{"id":"opt_3","text":"Pembicara menolak bergabung dalam proyek baru bulan depan"},{"id":"opt_4","text":"Diputuskan bahwa mulai bulan depan pembicara dipercaya menjadi penanggung jawab proyek baru"}],"audio_text":"来月から新しいプロジェクトの責任者を任されることになりました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '任されることになりました menyatakan keputusan resmi dari perusahaan.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5486650f-ec5f-42d7-8561-9cf5770a3ba4', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat bimbingan teliti dari senior, saya berhasil lulus ujian sertifikasi dengan lancar."', '{"romaji":"Senpai no teinei na shidou no okage de, buji ni shikaku shiken ni goukaku shimashita.","tokens":["先輩の","合格しました。","資格試験に","指導の","せいで、","無事に","丁寧な","おかげで、","を"],"target_translation":"Berkat bimbingan teliti dari senior, saya berhasil lulus ujian sertifikasi dengan lancar."}'::jsonb, '["先輩の","丁寧な","指導の","おかげで、","無事に","資格試験に","合格しました。"]'::jsonb, NULL, NULL, '～のおかげで menyatakan sebab positif dari suatu keberhasilan.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('25bfdaad-f7b8-4c51-9a6a-dd5fdc0b0bd2', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 昨夜の台風の影響の___、今朝は一部の路線で遅延が出ています。', '{"options":["はずで","せいで","おかげで","うちに"],"translation":"Akibat dampak topan semalam, pagi ini terjadi keterlambatan pada sebagian jalur kereta.","sentence_template":"昨夜の台風の影響の[blank]、今朝は一部の路線で遅延が出ています。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, '～のせいで digunakan untuk penyebab dari kejadian yang merugikan atau mengganggu.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('32113b56-f0d4-4735-a73b-8dcf7678336a', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhadap masukan dari pelanggan, kami akan menanggapi dengan cepat."', '{"romaji":"Okyakusama kara no go-iken ni taishite, jinsoku ni taiou itashimasu.","display_text":"お客様からのご意見に対して、迅速に対応いたします。","phonetic_breakdown":["o-kya-ku-sa-ma","ka-ra-no","go-i-ken-ni","tai-shi-te","jin-so-ku-ni","tai-ou-i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"お客様からのご意見に対して、迅速に対応いたします。"}'::jsonb, NULL, NULL, 'ご意見に対して menandai sasaran tindakan layanan secara profesional.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bedaf72e-30ae-4031-b0f3-6c13f6384011', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan harapan pembicara berikut. Apa yang ingin dilakukannya?', '{"options":[{"id":"opt_1","text":"Mumpung tinggal di Jepang, ingin mencoba mengunjungi berbagai pemandian air panas di seluruh negeri"},{"id":"opt_2","text":"Tidak menyukai pemandian air panas selama di Jepang"},{"id":"opt_3","text":"Baru akan pergi ke pemandian air panas setelah meninggalkan Jepang"},{"id":"opt_4","text":"Sudah mengunjungi seluruh pemandian air panas di Jepang"}],"audio_text":"日本に住んでいるうちに、全国のいろいろな温泉地を巡ってみたいんです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '住んでいるうちに berarti ''mumpung masih tinggal di Jepang'' sebelum keadaan berubah.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff39cd89-fba9-492a-b06c-878c45d40be5', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 田中さんはすでに会場へ出発したので、あと十分ほどで到着する___。', '{"options":["せいです","ばかりです","はずです","うちです"],"translation":"Karena Tanaka-san sudah berangkat ke lokasi, seharusnya dia tiba sekitar sepuluh menit lagi.","sentence_template":"田中さんはすでに会場へ出発したので、あと十分ほどで到着する[blank]。"}'::jsonb, '{"selected":"はずです"}'::jsonb, NULL, NULL, '到着するはずです menyatakan perkiraan logis berdasarkan bukti keberangkatan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb3a4fb0-f38b-452a-bd8e-970cdcdb3661', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Jembatan bersejarah ini dicintai oleh banyak warga kota."', '{"romaji":"Kono rekishiteki na hashi wa, ooku no shimin ni aisarete imasu.","tokens":["この","市民に","愛されて","を","います。","愛して","歴史的な","多くの","橋は、"],"target_translation":"Jembatan bersejarah ini dicintai oleh banyak warga kota."}'::jsonb, '["この","歴史的な","橋は、","多くの","市民に","愛されて","います。"]'::jsonb, NULL, NULL, '愛する -> bentuk pasif 愛されている (dicintai).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7366a47a-cf30-443c-b028-e08a60acb345', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan percakapan berikut. Mengapa pembicara belum mengenal restoran setempat?', '{"options":[{"id":"opt_1","text":"Tidak suka makan di restoran yang ada di kota ini"},{"id":"opt_2","text":"Baru saja pindah ke kota ini minggu lalu sehingga belum tahu banyak restoran enak"},{"id":"opt_3","text":"Sudah lama tinggal di kota ini dan hafal semua restoran enak"},{"id":"opt_4","text":"Berencana pindah dari kota ini minggu depan"}],"audio_text":"先週この町へ引っ越してきたばかりなので、まだ美味しいお店をよく知らないんです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '引っ越してきたばかり menyatakan sesuatu yang baru saja terjadi menurut perasaan pembicara.', 9, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15003d7d-c78d-4ee5-805f-844891829398', '16df1e52-1fbc-41fe-8ab5-11c6b1179b86', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tergantung negara dan wilayahnya, kebiasaan memberi salam bermacam-macam."', '{"romaji":"Kuni ya chiiki ni yotte, aisatsu no shuukan wa samazama desu.","display_text":"国や地域によって、挨拶の習慣はさまざまです。","phonetic_breakdown":["ku-ni-ya","chi-i-ki-ni","yot-te","ai-sa-tsu-no","shuu-kan-wa","sa-ma-za-ma-de-su"]}'::jsonb, '{"expected_transcript":"国や地域によって、挨拶の習慣はさまざまです。"}'::jsonb, NULL, NULL, '～によって menyatakan keragaman budaya dan mencerminkan penguasaan tata bahasa N3.', 10, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf290bb4-fc4a-4384-87ff-de58374267d6', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan jawaban di kantor berikut. Di mana orang yang dicari?', '{"options":[{"id":"opt_1","text":"Orang yang dicari sedang cuti panjang minggu ini"},{"id":"opt_2","text":"Orang yang dicari baru saja meninggalkan kursinya dan diperkirakan kembali sekitar lima menit"},{"id":"opt_3","text":"Orang yang dicari sedang duduk di kursinya sekarang"},{"id":"opt_4","text":"Orang yang dicari sudah pulang ke rumah sejak siang"}],"audio_text":"あっ、すみません、今席を外したばかりなんです。五分ほどで戻ると思います。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '席を外したばかり berarti baru saja beranjak dari tempat duduk.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('16d38a41-7097-4893-8695-4dd6d7d77264', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Padahal sepatu ini baru saja dibeli kemarin, tapi sudah kotor karena hujan."', '{"romaji":"Kono kutsu wa kinou katta bakari nanoni, ame de yogorete shimaimashita.","display_text":"この靴は昨日買ったばかりなのに、雨で汚れてしまいました。","phonetic_breakdown":["ko-no","ku-tsu-wa","ki-nou","kat-ta","ba-ka-ri-na-no-ni","a-me-de","yo-go-re-te-shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"この靴は昨日買ったばかりなのに、雨で汚れてしまいました。"}'::jsonb, NULL, NULL, '買ったばかりなのに mengekspresikan rasa sayang atau kecewa.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55345814-e78f-47c4-bd11-018879c4da85', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Saya baru saja memulai belajar bahasa Jepang, tetapi saya akan berusaha keras."', '{"romaji":"Nihongo no benkyou o hajimeta bakari desu ga, ganbarimasu.","tokens":["始める","ですが、","頑張ります。","勉強を","ばかり","始めた","が","日本語の"],"target_translation":"Saya baru saja memulai belajar bahasa Jepang, tetapi saya akan berusaha keras."}'::jsonb, '["日本語の","勉強を","始めた","ばかり","ですが、","頑張ります。"]'::jsonb, NULL, NULL, '始めた + ばかりです.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ec05f22b-0d57-4442-b4d7-00eaf722ac37', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 先ほど薬を___ばかりなので、もう少し様子を見てください。', '{"options":["飲んだ","飲む","飲んで","飲み"],"translation":"Karena baru saja minum obat tadi, silakan pantau kondisinya sebentar lagi.","sentence_template":"先ほど薬を[blank]ばかりなので、もう少し様子を見てください。"}'::jsonb, '{"selected":"飲んだ"}'::jsonb, NULL, NULL, '飲む -> 飲んだ + ばかり.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('84773ee7-8f65-42e4-b2e0-40e6883fe511', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan laporan singkat berikut. Bagaimana status proposalnya?', '{"options":[{"id":"opt_1","text":"Revisi proposal belum dimulai sama sekali"},{"id":"opt_2","text":"Pembicara meminta rekan kerja merevisi proposalnya"},{"id":"opt_3","text":"Revisi proposal baru saja selesai saat ini juga dan akan segera dikirim lewat email"},{"id":"opt_4","text":"Proposal sudah dikirim lewat email kemarin"}],"audio_text":"ちょうど今、企画書の修正が終わったばかりです。これからメールで送りますね。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '終わったばかりです menandakan pekerjaan baru tepat selesai.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c947a538-1968-4c8e-9074-0eb3425b02cf', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di sini adalah kafe tempat Anda bisa melihat anak kucing yang baru saja lahir."', '{"romaji":"Koko wa umareta bakari no koneko ga mirareru kafe desu.","display_text":"ここは生まれたばかりの子猫が見られるカフェです。","phonetic_breakdown":["ko-ko-wa","u-ma-re-ta","ba-ka-ri-no","ko-ne-ko-ga","mi-ra-re-ru","ka-fe-de-su"]}'::jsonb, '{"expected_transcript":"ここは生まれたばかりの子猫が見られるカフェです。"}'::jsonb, NULL, NULL, '生まれたばかりの menerangkan 子猫.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('72e8894a-1df1-47bd-92da-3c43507c6f7c', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Karena baru saja ditugaskan ke Jepang bulan lalu, setiap hari saya sibuk."', '{"romaji":"Sengetsu Nihon ni funin shita bakari de mainichi isogashii desu.","tokens":["ばかりで","忙しいです。","日本に","赴任した","赴任する","先月","を","毎日"],"target_translation":"Karena baru saja ditugaskan ke Jepang bulan lalu, setiap hari saya sibuk."}'::jsonb, '["先月","日本に","赴任した","ばかりで","毎日","忙しいです。"]'::jsonb, NULL, NULL, '赴任したばかりで menjelaskan kondisi adaptasi awal.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7defc258-d444-4592-8f13-47a50559a5ee', '1ca7228d-f285-48b1-bd34-c2876c710957', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 会議が___ばかりなので、まだ結論は出ていません。', '{"options":["始まって","始まり","始まった","始まる"],"translation":"Karena rapat baru saja dimulai, kesimpulannya belum keluar.","sentence_template":"会議が[blank]ばかりなので、まだ結論は出ていません。"}'::jsonb, '{"selected":"始まった"}'::jsonb, NULL, NULL, '始まる -> 始まったばかり.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a13a567-57cb-5951-a328-f07ce2434824', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat Anda, saya lulus ujian."', '{"romaji":"Okagesama de, shiken ni goukaku shimashita.","display_text":"おかげさまで、試験に合格しました。","phonetic_breakdown":["o-ka-ge-sa-ma de","shi-ken ni","gou-ka-ku","shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"おかげさまで、試験に合格しました。"}'::jsonb, NULL, NULL, 'おかげさまで sangat tepat diucapkan ketika melaporkan keberhasilan kepada guru, senior, atau rekan kerja.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2be43d74-e610-571b-85c8-cd5d0b78617b', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat bantuan Tanaka, tugasnya selesai tepat waktu."', '{"romaji":"Tanaka-san ga tetsudatte kureta okage de, maniai mashita.","display_text":"田中さんが手伝ってくれたおかげで、間に合いました。","phonetic_breakdown":["ta-na-ka-san ga","te-tsu-dat-te ku-re-ta","o-ka-ge de","ma-ni-a-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"田中さんが手伝ってくれたおかげで、間に合いました。"}'::jsonb, NULL, NULL, 'Kombinasi ～てくれた + おかげで menonjolkan rasa terima kasih atas kebaikan orang lain.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2babbf70-73a8-5618-becf-b5405ec6102d', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat tinggal dekat stasiun, berangkat kerja jadi sangat mudah."', '{"romaji":"Eki kara chikai okage de, tsuukin ga totemo raku desu.","display_text":"駅から近いおかげで、通勤がとても楽です。","phonetic_breakdown":["e-ki ka-ra","chi-ka-i","o-ka-ge de","tsuu-kin ga","to-te-mo","ra-ku de-su"]}'::jsonb, '{"expected_transcript":"駅から近いおかげで、通勤がとても楽です。"}'::jsonb, NULL, NULL, 'Kata sifat-I (近い) langsung disambungkan dengan おかげで.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a7d4b71d-4533-52fd-b9a1-6f3df227d917', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat mengulang materi setiap hari, saya mengerti tata bahasanya."', '{"romaji":"Mainichi fukushuu shita okage de, bunpou ga wakarimashita.","tokens":["わかりました。","おかげで、","文法が","毎日","復習して","せいで、","復習した"],"target_translation":"Berkat mengulang materi setiap hari, saya mengerti tata bahasanya."}'::jsonb, '["毎日","復習した","おかげで、","文法が","わかりました。"]'::jsonb, NULL, NULL, '復習した (bentuk biasa lampau) + おかげで menyatakan sebab dari hasil positif.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3308ecec-ba70-57dc-abe5-8071b522289e', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat dukungan teman-teman, saya tidak menyerah."', '{"romaji":"Tomodachi no ouen no okage de, akiramezu ni sumimashita.","tokens":["友達の応援の","せいで、","応援な","おかげで、","すみました。","あきらめずに"],"target_translation":"Berkat dukungan teman-teman, saya tidak menyerah."}'::jsonb, '["友達の応援の","おかげで、","あきらめずに","すみました。"]'::jsonb, NULL, NULL, 'Nomina 応援 diikuti の lalu おかげで.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93d714c9-c668-516f-abec-55531cb18103', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Saya bisa sehat kembali berkat saran dokter."', '{"romaji":"Isha no adobaisu no okage de, genki ni narimashita.","tokens":["せいで、","元気に","なりました。","アドバイスな","おかげで、","医者のアドバイスの"],"target_translation":"Saya bisa sehat kembali berkat saran dokter."}'::jsonb, '["医者のアドバイスの","おかげで、","元気に","なりました。"]'::jsonb, NULL, NULL, '医者のアドバイス (nasihat dokter) + の + おかげで.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db6d5f4f-ff90-4ceb-b549-661898d85c68', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat doa dan perhatian Anda, flu saya sudah sembuh total."', '{"romaji":"Okagesama de, kaze wa sukkari yoku narimashita.","display_text":"おかげさまで、風邪はすっかり良くなりました。","phonetic_breakdown":["o-ka-ge-sa-ma-de","ka-ze-wa","suk-ka-ri","yo-ku","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"おかげさまで、風邪はすっかり良くなりました。"}'::jsonb, NULL, NULL, 'おかげさまで adalah ungkapan sopan yang sangat sering dipakai untuk menjawab pertanyaan kabar.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d33d016-1ebe-4b6e-84e2-4e721825601c', '1e67fa06-5de4-580f-b23f-ada0a0de41a5', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat teman yang membantu, pindahan selesai lebih cepat."', '{"romaji":"Tomodachi ga tetsudatte kureta okage de, hikkoshi ga hayaku owarimashita.","tokens":["せいで、","引っ越しが","友達が","おかげで、","早く","を","終わりました。","手伝ってくれた"],"target_translation":"Berkat teman yang membantu, pindahan selesai lebih cepat."}'::jsonb, '["友達が","手伝ってくれた","おかげで、","引っ越しが","早く","終わりました。"]'::jsonb, NULL, NULL, '手伝ってくれた + おかげで menyatakan syukur atas bantuan teman.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('978a5dfa-3a46-5996-b468-4b0e00949ad2', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Cara berpikir berbeda tergantung orangnya."', '{"romaji":"Hito ni yotte kangaekata ga chigaimasu.","display_text":"人によって考え方が違います。","phonetic_breakdown":["hi-to ni","yot-te","kan-ga-e-ka-ta ga","chi-ga-i-ma-su"]}'::jsonb, '{"expected_transcript":"人によって考え方が違います。"}'::jsonb, NULL, NULL, 'Kalimat inti N3 yang sangat sering dipakai dalam diskusi lintas budaya.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a98607f-778b-5130-a238-d37225adedae', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat diskusi, masalahnya berhasil diselesaikan."', '{"romaji":"Hanashiai ni yotte mondai ga kaiketsu shimashita.","display_text":"話し合いによって問題が解決しました。","phonetic_breakdown":["ha-na-shi-a-i ni","yot-te","mon-da-i ga","ka-i-ke-tsu","shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"話し合いによって問題が解決しました。"}'::jsonb, NULL, NULL, '話し合いによって menunjukkan cara/sarana penyelesaian masalah secara formal.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d96493cb-aa94-5cf5-8229-4c901368eb63', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tergantung keadaannya, jadwal bisa saja berubah."', '{"romaji":"Baai ni yotte wa yotei ga kawaru koto mo arimasu.","display_text":"場合によっては予定が変わることもあります。","phonetic_breakdown":["ba-a-i ni","yot-te wa","yo-te-i ga","ka-wa-ru","ko-to mo","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"場合によっては予定が変わることもあります。"}'::jsonb, NULL, NULL, '場合によっては + ～こともあります adalah kombinasi alami untuk menjelaskan kemungkinan fleksibel.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea13b5e9-1a42-5971-b98e-916427c41c6f', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung musimnya, pemandangan di sini berubah."', '{"romaji":"Kisetsu ni yotte koko no keshiki ga kawarimasu.","tokens":["対して","よる","季節に","変わります。","よって","ここの景色が"],"target_translation":"Tergantung musimnya, pemandangan di sini berubah."}'::jsonb, '["季節に","よって","ここの景色が","変わります。"]'::jsonb, NULL, NULL, '季節によって + 変わります menyatakan variasi berdasarkan musim.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('678d2b71-4f2f-58ec-863b-fd506d894773', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Ada jadwal pengiriman akibat badai salju yang tertunda."', '{"romaji":"Ooyuki ni yoru haisou no okure ga arimasu.","tokens":["よって","対する","配送の遅れが","あります。","よる","大雪に"],"target_translation":"Pengiriman tertunda akibat badai salju."}'::jsonb, '["大雪に","よる","配送の遅れが","あります。"]'::jsonb, NULL, NULL, '配送の遅れ adalah nomina sehingga menggunakan による.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ea711b3-a9e8-5c1e-a832-036fd964a15d', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Saya belajar bahasa Jepang melalui pertukaran budaya."', '{"romaji":"Bunka kouryuu ni yotte nihongo o manabimashita.","tokens":["せいで","よって","日本語を","学びました。","よる","文化交流に"],"target_translation":"Saya belajar bahasa Jepang melalui pertukaran budaya."}'::jsonb, '["文化交流に","よって","日本語を","学びました。"]'::jsonb, NULL, NULL, '文化交流によって menyatakan sarana/metode pembelajaran.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00582520-8219-4495-a763-4cd5c39cba6e', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Cara berpikir bermacam-macam tergantung orangnya."', '{"romaji":"Hito ni yotte kangaekata wa samazama desu.","display_text":"人によって考え方はさまざまです。","phonetic_breakdown":["hi-to-ni","yot-te","kan-ga-e-ka-ta-wa","sa-ma-za-ma-de-su"]}'::jsonb, '{"expected_transcript":"人によって考え方はさまざまです。"}'::jsonb, NULL, NULL, '人によって adalah frasa paling sering dipakai untuk menyatakan perbedaan individu.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a955e43-6c27-4f8d-86df-a5177c334c73', '202f4a77-338c-5986-b953-bd733c212f61', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Melalui kerja keras setiap hari, lahir pencapaian yang besar."', '{"romaji":"Mainichi no doryoku ni yotte, ookina seika ga umaremashita.","tokens":["を","成果が","生まれました。","努力に","よって、","対して、","毎日の","大きな"],"target_translation":"Melalui kerja keras setiap hari, lahir pencapaian yang besar."}'::jsonb, '["毎日の","努力に","よって、","大きな","成果が","生まれました。"]'::jsonb, NULL, NULL, '努力によって menyatakan cara/sebab formal yang melahirkan hasil.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0788eb68-8e48-47a6-8d5c-82ccd41939e9', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: システムエラーの___、オンライン決済が一時的に使えなくなりました。', '{"options":["おかげで","ばかりで","せいで","によって"],"translation":"Akibat error sistem, pembayaran daring sementara tidak bisa digunakan.","sentence_template":"システムエラーの[blank]、オンライン決済が一時的に使えなくなりました。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, 'エラーのせいで menjelaskan penyebab gangguan layanan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae1efa09-3610-45f6-9390-743b31d6f706', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 緊張しすぎた___、面接で用意した言葉を忘れてしまいました。', '{"options":["うちに","はずで","せいで","おかげで"],"translation":"Gara-gara terlalu gugup, saya lupa kata-kata yang sudah disiapkan untuk wawancara.","sentence_template":"緊張しすぎた[blank]、面接で用意した言葉を忘れてしまいました。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, '緊張しすぎた + せいで.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20943e11-9a43-4f6e-b60c-48a990b1cb76', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan keluhan berikut. Apa yang diduga menjadi penyebab mata cepat lelah?', '{"options":[{"id":"opt_1","text":"Pembicara tidak pernah membaca buku berhuruf kecil"},{"id":"opt_2","text":"Mungkin karena faktor usia, belakangan mata cepat lelah saat membaca huruf kecil"},{"id":"opt_3","text":"Huruf di buku terlalu besar sehingga sulit dibaca"},{"id":"opt_4","text":"Penglihatan pembicara semakin tajam seiring bertambahnya usia"}],"audio_text":"年齢のせいか、最近は細かい文字を読むとすぐ目が疲れるようになりました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '年齢のせいか berarti ''mungkin karena faktor usia''.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9dbd6294-bd83-416a-8e1a-832c68db9d6e', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara suara bising proyek konstruksi, siang hari sama sekali tidak bisa tidur."', '{"romaji":"Kouji no souon no sei de, hiruma wa mattaku nemuremasen.","tokens":["昼間は","せいで、","眠れません。","を","工事の","おかげで、","騒音の","全く"],"target_translation":"Gara-gara suara bising proyek konstruksi, siang hari sama sekali tidak bisa tidur."}'::jsonb, '["工事の","騒音の","せいで、","昼間は","全く","眠れません。"]'::jsonb, NULL, NULL, '騒音 (souon, kebisingan) + のせいで.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53764704-0862-4432-a171-98925a5c8def', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 道が___せいで、タクシーもなかなか捕まりませんでした。', '{"options":["混んでいた","混んでいたな","混んでいて","混んでいたの"],"translation":"Gara-gara jalanan macet, taksi pun sulit sekali didapatkan.","sentence_template":"道が[blank]せいで、タクシーもなかなか捕まりませんでした。"}'::jsonb, '{"selected":"混んでいた"}'::jsonb, NULL, NULL, '混んでいた (bentuk lampau biasa) langsung diikuti せいで.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('63da8bae-d79d-4eed-8ba0-64e6182ba679', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara tidak melihat prakiraan cuaca, saya lupa membawa payung saat keluar."', '{"romaji":"Tenki yohou o minakatta sei de, kasa o motte deru no o wasuremashita.","display_text":"天気予報を見なかったせいで、傘を持って出るのを忘れました。","phonetic_breakdown":["ten-ki-yo-hou-o","mi-na-kat-ta","sei-de","ka-sa-o","mot-te-de-ru-no-o","wa-su-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"天気予報を見なかったせいで、傘を持って出るのを忘れました。"}'::jsonb, NULL, NULL, '見なかった (bentuk lampau negatif biasa) + せいで.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a8491a7-98a2-4948-9b04-add7b69d1450', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan nasihat manajer berikut. Apa pesan utamanya?', '{"options":[{"id":"opt_1","text":"Kegagalan di kantor selalu disebabkan oleh rekan kerja lain"},{"id":"opt_2","text":"Jika gagal, lebih baik segera mencari siapa yang bisa disalahkan"},{"id":"opt_3","text":"Tidak boleh menyalahkan orang lain atas kegagalan sendiri; harus cek penyebabnya dengan tenang"},{"id":"opt_4","text":"Tidak perlu mencari penyebab jika terjadi kegagalan"}],"audio_text":"自分の失敗を他人のせいにしてはいけません。まず原因を冷静に確認しましょう。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '他人のせいにする berarti menyalahkan orang lain.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73290d9d-5dad-4975-8c4c-06c23851c022', '23b76202-b6be-4b1e-bd35-c82e5acc7cec', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat gempa kuat, semua buku di rak berjatuhan."', '{"romaji":"Tsuyoi jishin no sei de, tana no hon ga zenbu ochimashita.","tokens":["全部","棚の","地震の","強い","おかげで、","を","落ちました。","せいで、","本が"],"target_translation":"Akibat gempa kuat, semua buku di rak berjatuhan."}'::jsonb, '["強い","地震の","せいで、","棚の","本が","全部","落ちました。"]'::jsonb, NULL, NULL, '地震のせいで menyatakan sebab bencana terhadap kerusakan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e0c170f-7a5e-597b-83d2-0c26735594fd', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'listening', 'listening_choice', 'Apa yang pembicara usahakan saat membeli makanan di minimarket?', '{"options":[{"id":"opt_1","text":"Memilih kotak bekal yang sedang diskon malam hari"},{"id":"opt_2","text":"Meminta staf memanaskan makanan lebih lama"},{"id":"opt_3","text":"Membeli minuman hangat sebagai pendamping"},{"id":"opt_4","text":"Memeriksa kalori dan kadar garam terlebih dahulu"}],"audio_text":"コンビニでお弁当を買うときは、必ずカロリーと塩分を確認するようにしています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'カロリーと塩分を確認する berarti memeriksa kalori dan kadar garam.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbfbe9bb-925b-5c1d-a667-64e9023c1225', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'listening', 'listening_choice', 'Mengapa pembicara mulai membawa botol minum sendiri ke kantor?', '{"options":[{"id":"opt_1","text":"Untuk mengurangi sampah"},{"id":"opt_2","text":"Karena air di kantor rasanya aneh"},{"id":"opt_3","text":"Karena mesin penjual otomatis sering rusak"},{"id":"opt_4","text":"Agar bisa minum kopi panas saat rapat"}],"audio_text":"ゴミを減らすために、毎日家からお茶を入れてマイボトルを持っていくようにしています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ゴミを減らすために berarti ''demi mengurangi sampah''.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2fda6838-c71a-5b52-8367-27d3a77daf83', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'listening', 'listening_choice', 'Apa saran senior kepada pegawai baru dalam audio ini?', '{"options":[{"id":"opt_1","text":"Mencatat semua tugas di buku agenda pribadi"},{"id":"opt_2","text":"Segera bertanya jika ada hal yang tidak dipahami"},{"id":"opt_3","text":"Menyelesaikan pekerjaan sebelum jam makan siang"},{"id":"opt_4","text":"Memeriksa email dari klien setiap satu jam"}],"audio_text":"わからないことがあったら、そのままにしないで早めに質問するようにしてください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '早めに質問するようにしてください berarti ''usahakanlah untuk bertanya lebih awal''.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f8cedb34-e623-59a8-a601-f1334191e936', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'reading', 'fill_blank', 'Pilih kata penghubung yang tepat: 疲れていても、歯を磨いてから寝る ___ しています。', '{"options":["ように","ことに","ために","そうに"],"translation":"Meskipun lelah, saya membiasakan diri menyikat gigi dulu sebelum tidur.","sentence_template":"疲れていても、歯を磨いてから寝る [blank] しています。"}'::jsonb, '{"selected":"ように"}'::jsonb, NULL, NULL, '～ようにしています menekankan usaha rutin yang dijaga secara sadar.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b1f21553-732a-5e18-a6f3-1b960e023e77', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'reading', 'fill_blank', 'Lengkapi nasihat kesehatan: 目の疲れを防ぐため、一時間ごとに休憩を ___ ようにしてください。', '{"options":["とる","とった","とって","とります"],"translation":"Untuk mencegah kelelahan mata, usahakanlah mengambil istirahat setiap satu jam.","sentence_template":"目の疲れを防ぐため、一時間ごとに休憩を [blank] ようにしてください。"}'::jsonb, '{"selected":"とる"}'::jsonb, NULL, NULL, 'Sebelum ようにしてください digunakan bentuk kamus (休憩をとる).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eaee3f85-e538-5c81-9c99-b3f429238923', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', NULL, 'reading', 'fill_blank', 'Pilih opsi paling alami: 書類のミスをなくすため、提出前に二回 ___ ようにしています。', '{"options":["見直す","見直した","見直して","見直そう"],"translation":"Demi menghilangkan kesalahan dokumen, saya membiasakan diri memeriksa ulang dua kali sebelum mengumpulkan.","sentence_template":"書類のミスをなくすため、提出前に二回 [blank] ようにしています。"}'::jsonb, '{"selected":"見直す"}'::jsonb, NULL, NULL, '見直す (minaosu) berarti memeriksa kembali; dipakai dalam bentuk kamus sebelum ようにしています.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eca56725-f4c2-474b-ab3c-e8d9856a4fde', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan kebiasaan kerja berikut. Bagaimana cara pembicara berhemat?', '{"options":[{"id":"opt_1","text":"Demi berhemat, berusaha mengurangi makan di luar pada hari kerja dan membuat bekal sendiri"},{"id":"opt_2","text":"Selalu makan di restoran mahal pada hari kerja"},{"id":"opt_3","text":"Tidak bisa memasak sehingga membeli makanan siap saji"},{"id":"opt_4","text":"Membuat bekal hanya saat akhir pekan"}],"audio_text":"節約のため、平日は外食を控えて自分で弁当を作るようにしています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '作るようにしています menunjukkan kebiasaan rutin yang sengaja diterapkan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f214052d-abeb-461d-ad38-264a09e53169', '24f07484-3d5f-5c0b-a7ce-d42e9f6ef6e2', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 大切な約束は忘れないように、すぐ手帳に___ようにしてください。', '{"options":["メモしよう","メモする","メモして","メモした"],"translation":"Agar tidak lupa janji penting, biasakanlah langsung mencatatnya di buku agenda.","sentence_template":"大切な約束は忘れないように、すぐ手帳に[blank]ようにしてください。"}'::jsonb, '{"selected":"メモする"}'::jsonb, NULL, NULL, 'Bentuk kamus + ようにしてください dipakai untuk meminta atau menasihati agar membiasakan diri.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eb564c6e-9f82-5e3d-b313-505a9676df54', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mari makan selagi masih hangat."', '{"romaji":"Atatakai uchi ni tabemashou.","display_text":"温かいうちに食べましょう。","phonetic_breakdown":["a-ta-ta-ka-i","u-chi ni","ta-be-ma-shou"]}'::jsonb, '{"expected_transcript":"温かいうちに食べましょう。"}'::jsonb, NULL, NULL, 'Ungkapan sangat akrab dan alami saat mengajak makan hidangan yang baru disajikan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('caabf047-af98-5d5d-a3b9-49eea92046be', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebaiknya pulang selagi belum turun salju."', '{"romaji":"Yuki ga furanai uchi ni kaetta hou ga ii desu.","display_text":"雪が降らないうちに帰ったほうがいいです。","phonetic_breakdown":["yu-ki ga","fu-ra-na-i","u-chi ni","ka-et-ta","hou ga i-i de-su"]}'::jsonb, '{"expected_transcript":"雪が降らないうちに帰ったほうがいいです。"}'::jsonb, NULL, NULL, '降らないうちに (selagi belum turun) sering dipasangkan dengan ～たほうがいいです.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6dadc8a-1f11-5669-89d9-5793c322f3a2', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Selagi berbicara, rasa gugup saya menghilang."', '{"romaji":"Hanashite iru uchi ni kinchou ga hoguremashita.","display_text":"話しているうちに緊張がほぐれました。","phonetic_breakdown":["ha-na-shi-te i-ru","u-chi ni","kin-chou ga","ho-gu-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"話しているうちに緊張がほぐれました。"}'::jsonb, NULL, NULL, '緊張がほぐれる (kinchou ga hogureru) berarti ketegangan/rasa gugup mencair.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3919a681-aada-5fc0-9ed9-0980244f2fd6', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mari memeriksa jadwal selagi ada waktu."', '{"romaji":"Jikan ga aru uchi ni sukejuuru o kakunin shimashou.","tokens":["せいで","うちに","時間があった","スケジュールを","時間がある","確認しましょう。"],"target_translation":"Mari memeriksa jadwal selagi ada waktu."}'::jsonb, '["時間がある","うちに","スケジュールを","確認しましょう。"]'::jsonb, NULL, NULL, '時間がある + うちに berarti mumpung ada waktu.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6f1d9fc9-b6fb-5794-8022-c28ccfd011ec', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Selagi anak-anak tidur, saya menyelesaikan pekerjaan rumah."', '{"romaji":"Kodomo ga nete iru uchi ni kaji o owarasemasu.","tokens":["うちに","子どもが","寝た","ように","寝ている","終わらせます。","家事を"],"target_translation":"Selagi anak-anak tidur, saya menyelesaikan pekerjaan rumah."}'::jsonb, '["子どもが","寝ている","うちに","家事を","終わらせます。"]'::jsonb, NULL, NULL, '寝ているうちに menyatakan tindakan yang diselesaikan sebelum anak terbangun.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('297b30ac-5603-5b20-aa47-a22925fdb1bd', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Selagi masih mahasiswa, saya ingin belajar banyak bahasa asing."', '{"romaji":"Gakusei no uchi ni gaikokugo o takusan benkyou shitai desu.","tokens":["たくさん","学生な","外国語を","はずで","学生の","勉強したいです。","うちに"],"target_translation":"Selagi masih mahasiswa, saya ingin belajar banyak bahasa asing."}'::jsonb, '["学生の","うちに","外国語を","たくさん","勉強したいです。"]'::jsonb, NULL, NULL, 'Nomina 学生 + の + うちに.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('178aef82-af6f-4756-bd4a-71bcfd7653a4', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mumpung masih muda, saya ingin mencoba berbagai macam tantangan."', '{"romaji":"Wakai uchi ni iroiro na koto ni chousen shitai desu.","display_text":"若いうちにいろいろなことに挑戦したいです。","phonetic_breakdown":["wa-kai","u-chi-ni","i-ro-i-ro-na","ko-to-ni","chou-sen-shi-tai-de-su"]}'::jsonb, '{"expected_transcript":"若いうちにいろいろなことに挑戦したいです。"}'::jsonb, NULL, NULL, '若い (kata sifat い) langsung diikuti うちに.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1c0df44b-1ce3-4e83-ba73-760c42460b88', '24f08bc2-3479-57e6-a002-e5714e517ea7', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mumpung belum turun hujan, mari kita angkat jemuran."', '{"romaji":"Ame ga furanai uchi ni, sentakumono o torikomimashou.","tokens":["うちに、","が","降らない","取り込みましょう。","降るせいで、","洗濯物を","雨が"],"target_translation":"Mumpung belum turun hujan, mari kita angkat jemuran."}'::jsonb, '["雨が","降らない","うちに、","洗濯物を","取り込みましょう。"]'::jsonb, NULL, NULL, '降らないうちに menyatakan aksi cepat sebelum hujan turun.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4de204c1-f772-5183-a78b-7fc9e16bbda2', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 早めに ___ おかげで、安いホテルに泊まれました。', '{"options":["予約した","予約する","予約して","予約します"],"translation":"Berkat memesan lebih awal, saya bisa menginap di hotel murah.","sentence_template":"早めに [blank] おかげで、安いホテルに泊まれました。"}'::jsonb, '{"selected":"予約した"}'::jsonb, NULL, NULL, 'Tindakan memesan sudah selesai dilakukan sehingga memakai 予約したおかげで.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('79ae27a7-f325-5f42-82cd-f79a672b9645', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Pilih penghubung yang benar: この地域の治安が ___ おかげで、夜でも安心して歩けます。', '{"options":["いい","いいな","よくて","いいの"],"translation":"Berkat keamanan wilayah ini yang baik, malam hari pun bisa berjalan dengan tenang.","sentence_template":"この地域の治安が [blank] おかげで、夜でも安心して歩けます。"}'::jsonb, '{"selected":"いい"}'::jsonb, NULL, NULL, 'Kata sifat-I いい langsung diikuti おかげで tanpa partikel tambahan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a5b6e1b-77eb-5f6e-9f58-63a40274b05b', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Apa yang membuat pembicara cepat akrab dengan lingkungan kantor baru?', '{"options":[{"id":"opt_1","text":"Karena kantornya dekat dengan apartemen"},{"id":"opt_2","text":"Karena semua pekerjaan sebelumnya sudah ia kuasai"},{"id":"opt_3","text":"Karena rekan-rekan divisi menyambutnya dengan hangat"},{"id":"opt_4","text":"Karena ia sudah mengenal manajernya sejak kuliah"}],"audio_text":"部署の皆さんが温かく迎えてくださったおかげで、すぐに職場に馴染むことができました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '部署の皆さんが温かく迎えてくださったおかげで berarti berkat rekan-rekan divisi menyambut dengan hangat.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f55d99c3-aadf-5e6d-b2aa-8096e4354d06', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Mengapa pembicara tidak kehujanan saat pulang kerja?', '{"options":[{"id":"opt_1","text":"Karena hujan berhenti sebelum ia keluar kantor"},{"id":"opt_2","text":"Karena ia diantar pulang oleh rekan kerja"},{"id":"opt_3","text":"Karena ia membeli payung baru di minimarket"},{"id":"opt_4","text":"Karena ia sudah memasukkan payung lipat ke tas sejak pagi"}],"audio_text":"朝、折りたたみ傘をかばんに入れておいたおかげで、濡れずに帰れました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '折りたたみ傘をかばんに入れておいたおかげで berarti berkat sudah menaruh payung lipat di tas.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3cc11f3-3a67-5c00-ae11-c0c916e71c67', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat bimbingan guru, saya lulus wawancara kerja."', '{"romaji":"Sensei no shidou no okage de, mensetsu ni goukaku shimashita.","tokens":["先生の指導の","面接に","指導な","合格しました。","おかげで、","失敗しました。"],"target_translation":"Berkat bimbingan guru, saya lulus wawancara kerja."}'::jsonb, '["先生の指導の","おかげで、","面接に","合格しました。"]'::jsonb, NULL, NULL, '先生の指導 (nomina) + の + おかげで menyatakan sebab dari keberhasilan wawancara.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4c6de7f-bf78-53e9-aa22-ddccfb3b4efc', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat kerja sama semua pihak, acara berjalan sukses."', '{"romaji":"Minasan no okage de, ibento ga daiseikou shimashita.","display_text":"皆さんのおかげで、イベントが大成功しました。","phonetic_breakdown":["mi-na-san no","o-ka-ge de","i-ben-to ga","da-i-se-i-kou","shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"皆さんのおかげで、イベントが大成功しました。"}'::jsonb, NULL, NULL, '大成功 (daiseikou) berarti sukses besar. Kalimat penutup yang sangat bagus untuk pidato atau rapat evaluasi.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a667c920-dc51-4682-961a-3e0f87874099', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この町は交通が___おかげで、とても住みやすいです。', '{"options":["便利だ","便利の","便利","便利な"],"translation":"Berkat transportasi yang praktis, kota ini sangat nyaman ditinggali.","sentence_template":"この町は交通が[blank]おかげで、とても住みやすいです。"}'::jsonb, '{"selected":"便利な"}'::jsonb, NULL, NULL, 'Kata sifat な memerlukan な sebelum おかげで (便利な + おかげで).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b11e3325-5d3c-488f-80e4-1d5b29150a7f', '2a6a4cfa-2ec1-50c0-8139-e4a438839d32', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat dukungan keluarga, saya bisa berjuang sampai akhir."', '{"romaji":"Kazoku no ouen no okage de, saigo made ganbaremashita.","display_text":"家族の応援のおかげで、最後まで頑張れました。","phonetic_breakdown":["ka-zo-ku-no","o-u-en-no","o-ka-ge-de","sai-go-ma-de","gan-ba-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"家族の応援のおかげで、最後まで頑張れました。"}'::jsonb, NULL, NULL, '応援のおかげで menyatakan penghargaan mendalam kepada keluarga.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a012c098-def5-5e8c-b5c5-cb6f4aa1ff46', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kelulusan: 半年間の努力が実り、無事に試験に ___ しました。', '{"options":["合格","失敗","欠席","中止"],"translation":"Usaha selama setengah tahun membuahkan hasil dan saya lulus ujian dengan baik.","sentence_template":"半年間の努力が実り、無事に試験に [blank] しました。"}'::jsonb, '{"selected":"合格"}'::jsonb, NULL, NULL, '合格する (goukaku suru) berarti lulus ujian.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('75a5ea64-c5e8-5fe7-a4ba-afdddf79d548', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk dukungan tim: 先輩の丁寧な ___ がとても役に立ちました。', '{"options":["指導","反対","不満","誤解"],"translation":"Bimbingan yang telaten dari senior sangat bermanfaat.","sentence_template":"先輩の丁寧な [blank] がとても役に立ちました。"}'::jsonb, '{"selected":"指導"}'::jsonb, NULL, NULL, '指導 (shidou) berarti bimbingan atau arahan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('490e9684-d1aa-55d6-9fdf-6768f8d754c9', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pemulihan: しっかり休んだので、体調がすっかり ___ しました。', '{"options":["回復","悪化","減少","延長"],"translation":"Karena beristirahat dengan baik, kondisi tubuh saya pulih sepenuhnya.","sentence_template":"しっかり休んだので、体調がすっかり [blank] しました。"}'::jsonb, '{"selected":"回復"}'::jsonb, NULL, NULL, '回復する (kaifuku suru) berarti pulih/membaik. 悪化 (memburuk) adalah lawannya.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('63a2904b-dde0-5352-8b69-6c29e41fd148', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'reading', 'fill_blank', 'Pilih kata untuk kerja sama: チーム全員の ___ があってプロジェクトが成功しました。', '{"options":["協力","競争","負担","請求"],"translation":"Dengan adanya kerja sama seluruh tim, proyeknya berhasil.","sentence_template":"チーム全員の [blank] があってプロジェクトが成功しました。"}'::jsonb, '{"selected":"協力"}'::jsonb, NULL, NULL, '協力 (kyouryoku) berarti kerja sama.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('19394f69-9f45-5825-92a3-79c9af6b841f', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'listening', 'listening_choice', 'Apa yang berhasil dicapai pembicara bulan ini?', '{"options":[{"id":"opt_1","text":"Menyelesaikan materi dua hari lebih cepat dari tenggat"},{"id":"opt_2","text":"Mendapatkan promosi jabatan di kantor cabang"},{"id":"opt_3","text":"Menghadiri seminar internasional di Kyoto"},{"id":"opt_4","text":"Memperpanjang tenggat proyek selama dua hari"}],"audio_text":"同僚に手伝ってもらった結果、期限より二日早く資料を完成させることができました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '期限より二日早く資料を完成させることができました berarti menyelesaikan dokumen dua hari lebih awal dari tenggat.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4fe0f273-afe7-5cb3-8c92-ce3834be3287', '2bbc5a39-c69f-54c8-8164-3f542be0027b', NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa berterima kasih kepada tetangganya?', '{"options":[{"id":"opt_1","text":"Karena tetangganya membantu mengangkat perabot berat"},{"id":"opt_2","text":"Karena diberi tahu cara memilah sampah dan tempat belanja"},{"id":"opt_3","text":"Karena diundang makan malam setiap akhir pekan"},{"id":"opt_4","text":"Karena dipinjami sepeda untuk pergi ke stasiun"}],"audio_text":"引っ越してきたばかりの頃、隣の方にゴミの分別や買い物の場所を親切に教えていただきました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'ゴミの分別や買い物の場所を親切に教えていただきました berarti diberi tahu dengan ramah tentang pemilahan sampah dan tempat belanja.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e296e3d0-d367-4549-82e4-53e14a188f17', '2bbc5a39-c69f-54c8-8164-3f542be0027b', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 先輩の丁寧な___のおかげで、新しい業務にもすぐ慣れました。', '{"options":["誤解","故障","指導","渋滞"],"translation":"Berkat bimbingan teliti dari senior, saya cepat terbiasa dengan tugas baru.","sentence_template":"先輩の丁寧な[blank]のおかげで、新しい業務にもすぐ慣れました。"}'::jsonb, '{"selected":"指導"}'::jsonb, NULL, NULL, '指導 (shidou) berarti bimbingan atau arahan, selaras dengan nuansa positif おかげで.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b7c8b5b7-62be-425a-92dc-fc5542421573', '2bbc5a39-c69f-54c8-8164-3f542be0027b', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan pidato penutup berikut. Apa yang disyukuri pembicara?', '{"options":[{"id":"opt_1","text":"Acara ditunda karena cuaca buruk"},{"id":"opt_2","text":"Pembicara mengerjakan seluruh acara sendirian"},{"id":"opt_3","text":"Acara gagal terlaksana karena kurangnya kerja sama"},{"id":"opt_4","text":"Berkat kerja sama semua pihak, acara berhasil diselenggarakan dengan lancar"}],"audio_text":"皆さんのご協力のおかげで、イベントを無事に成功させることができました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'ご協力のおかげで adalah ungkapan terima kasih resmi atas dukungan banyak orang.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('192794e7-051a-54f1-a616-3d047354cc32', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 台風 ___ せいで、出張が中止になりました。', '{"options":["の","な","に","で"],"translation":"Gara-gara topan, perjalanan dinas dibatalkan.","sentence_template":"台風 [blank] せいで、出張が中止になりました。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Nomina + の + せいで (台風のせいで) menyatakan penyebab akibat negatif.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bdde92a3-5642-510b-8bae-2a11a05b257a', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat: 昨夜遅くまで ___ せいで、今朝起きられませんでした。', '{"options":["起きていた","起きていて","起きています","起きよう"],"translation":"Gara-gara terjaga sampai larut malam tadi, pagi ini saya tidak bisa bangun.","sentence_template":"昨夜遅くまで [blank] せいで、今朝起きられませんでした。"}'::jsonb, '{"selected":"起きていた"}'::jsonb, NULL, NULL, 'Sebelum せいで digunakan bentuk biasa (起きていた).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fe099d04-f3ed-573a-9b81-4dc5e8d59585', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Pilih nuansa dugaan penyebab: 季節の変わり目の ___ 、最近少しだるいです。', '{"options":["せいか","おかげで","はずで","ように"],"translation":"Entah mungkin karena pergantian musim, belakangan ini badan saya agak lemas.","sentence_template":"季節の変わり目の [blank] 、最近少しだるいです。"}'::jsonb, '{"selected":"せいか"}'::jsonb, NULL, NULL, '～せいか berarti ''mungkin karena / entah karena'' saat pembicara tidak 100% yakin atas penyebab kondisi negatif.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a15f92e-64f4-5b47-b98d-1519bcbd1c42', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara kurang tidur, kepala saya sakit."', '{"romaji":"Nebusoku no sei de, atama ga itai desu.","tokens":["頭が","寝不足な","おかげで、","せいで、","寝不足の","痛いです。"],"target_translation":"Gara-gara kurang tidur, kepala saya sakit."}'::jsonb, '["寝不足の","せいで、","頭が","痛いです。"]'::jsonb, NULL, NULL, 'Akibat negatif (sakit kepala) memakai ～のせいで, bukan ～のおかげで.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('654e4dd0-1ec6-5cce-8f65-06d21dc25812', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara kemacetan, saya terlambat rapat."', '{"romaji":"Juutai no sei de, kaigi ni okuremashita.","tokens":["遅れました。","おかげで、","せいで、","会議に","間に合いました。","渋滞の"],"target_translation":"Gara-gara kemacetan, saya terlambat rapat."}'::jsonb, '["渋滞の","せいで、","会議に","遅れました。"]'::jsonb, NULL, NULL, '渋滞のせいで (gara-gara macet) + 会議に遅れました (terlambat rapat).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e45fe223-fe5f-56f1-8bf4-9cc90dd5cb0d', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Apa penyebab utama kegagalan pengiriman file menurut pembicara?', '{"options":[{"id":"opt_1","text":"Ukuran dokumen melebihi batas sistem"},{"id":"opt_2","text":"Alamat email penerima salah ketik"},{"id":"opt_3","text":"Koneksi internet tidak stabil"},{"id":"opt_4","text":"Komputer pembicara tiba-tiba kehabisan baterai"}],"audio_text":"通信が不安定だったせいで、添付ファイルが途中で止まってしまいました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '通信が不安定だったせいで berarti gara-gara koneksi tidak stabil.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7d6f011-b73e-4915-9e77-0ff2abfd0f44', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 夜遅くまでゲームをした___、今朝は寝坊してしまいました。', '{"options":["おかげで","ように","せいで","はずで"],"translation":"Gara-gara bermain gim sampai larut malam, pagi ini saya kesiangan.","sentence_template":"夜遅くまでゲームをした[blank]、今朝は寝坊してしまいました。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, '～せいで dipakai untuk penyebab dari hasil yang buruk atau tidak diinginkan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('24d0b9d1-9b29-4d14-98d6-965bee8fee31', '32c92f6c-c296-59fe-ac70-97a32a865304', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara komputer rusak, data penting jadi hilang."', '{"romaji":"Pasokon no koshou no sei de, daiji na deeta ga kiete shimaimashita.","tokens":["消えて","おかげで、","しまいました。","データが","故障の","を","パソコンの","せいで、","大事な"],"target_translation":"Gara-gara komputer rusak, data penting jadi hilang."}'::jsonb, '["パソコンの","故障の","せいで、","大事な","データが","消えて","しまいました。"]'::jsonb, NULL, NULL, 'Kata benda (故障) + のせいで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ce4c5a9-a599-5aa0-8842-39306e03500b', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'listening', 'listening_choice', 'Bagaimana sikap atasan terhadap kesalahan pegawai baru?', '{"options":[{"id":"opt_1","text":"Memarahi pegawai baru di depan seluruh tim"},{"id":"opt_2","text":"Langsung memindahkan tugas ke pegawai lain"},{"id":"opt_3","text":"Meminta laporan tertulis sepanjang lima halaman"},{"id":"opt_4","text":"Tidak memarahi dengan keras, melainkan memikirkan penyebabnya bersama"}],"audio_text":"部長は新人のミスに対して厳しく叱るのではなく、原因を一緒に考えてくれます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '厳しく叱るのではなく、原因を一緒に考えてくれます berarti tidak memarahi keras, tetapi memikirkan penyebabnya bersama.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0789019-ca88-53d3-850b-bc207cdb58fd', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'listening', 'listening_choice', 'Apa perbedaan cara kerja dua tim dalam audio ini?', '{"options":[{"id":"opt_1","text":"Tim penjualan banyak keluar kantor, sedangkan tim pengembang bekerja di kantor"},{"id":"opt_2","text":"Tim pengembang lebih sering dinas ke luar kota"},{"id":"opt_3","text":"Kedua tim sama-sama bekerja dari rumah setiap hari"},{"id":"opt_4","text":"Tim penjualan jarang menggunakan komputer"}],"audio_text":"営業部は外出が多いのに対して、開発部はほとんど社内でパソコン作業をしています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '営業部は外出が多い (banyak keluar) dikontraskan dengan 開発部はほとんど社内で作業 (hampir selalu kerja di kantor).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bba387e8-5481-529d-9b44-48bf18340ff5', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'listening', 'listening_choice', 'Apa yang dibahas terkait keluhan pelanggan?', '{"options":[{"id":"opt_1","text":"Perusahaan memutuskan mengabaikan keluhan kecil"},{"id":"opt_2","text":"Perusahaan berencana membahas langkah perbaikan secara internal"},{"id":"opt_3","text":"Pelanggan akan diberikan kupon belanja gratis"},{"id":"opt_4","text":"Layanan pelanggan akan dialihkan ke pihak luar"}],"audio_text":"お客様からのご意見に対して、社内で改善策を話し合う予定です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '社内で改善策を話し合う予定です berarti berencana mendiskusikan langkah perbaikan di internal.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eb6d514c-25de-5e30-9011-8abc4c8a3360', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 彼の意見 ___ 反対する人はいませんでした。', '{"options":["に対して","に対する","において","にとって"],"translation":"Tidak ada seorang pun yang menentang pendapatnya.","sentence_template":"彼の意見 [blank] 反対する人はいませんでした。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, '意見に対して反対する berarti menentang (terhadap) pendapat.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c9720f53-f7a2-55b7-98b2-035797668789', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'reading', 'fill_blank', 'Lengkapi frasa nomina: 日本の文化 ___ 理解を深めたいです。', '{"options":["に対する","に対して","にとって","について"],"translation":"Saya ingin memperdalam pemahaman terhadap budaya Jepang.","sentence_template":"日本の文化 [blank] 理解を深めたいです。"}'::jsonb, '{"selected":"に対する"}'::jsonb, NULL, NULL, 'Sebelum kata benda 理解 (pemahaman), gunakan に対する.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9e4b5335-46b1-5871-819b-b2065dad62c9', '33bf8196-60e5-5a29-abc3-7659791536fd', NULL, 'reading', 'fill_blank', 'Lengkapi kontras musim: 日本の夏が蒸し暑いの ___ 、冬は乾燥しています。', '{"options":["に対して","おかげで","せいで","うちに"],"translation":"Berbeda dengan musim panas Jepang yang lembap panas, musim dinginnya kering.","sentence_template":"日本の夏が蒸し暑いの [blank] 、冬は乾燥しています。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, 'のに対して menghubungkan dua sifat musim yang berlawanan.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85b37097-d484-4196-a0c0-cc59d379e55c', '33bf8196-60e5-5a29-abc3-7659791536fd', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan evaluasi presentasi berikut. Bagaimana pembicara menangani pertanyaan?', '{"options":[{"id":"opt_1","text":"Menjawab pertanyaan audiens dengan jelas menggunakan data saat presentasi kemarin"},{"id":"opt_2","text":"Lupa membawa data saat presentasi kemarin"},{"id":"opt_3","text":"Menolak menjawab pertanyaan audiens saat presentasi"},{"id":"opt_4","text":"Audiens tidak mengajukan pertanyaan sama sekali"}],"audio_text":"昨日の発表では、聴衆の質問に対してデータを使いながら分かりやすく答えました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '質問に対して答える berarti menjawab terhadap pertanyaan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('86fc32c7-802f-4245-8766-e1389dd519b3', '33bf8196-60e5-5a29-abc3-7659791536fd', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 日本の夏は湿度が高いの___、冬は乾燥しています。', '{"options":["うちに","おかげで","に対して","せいで"],"translation":"Berbeda dengan musim panas Jepang yang lembap, musim dinginnya kering.","sentence_template":"日本の夏は湿度が高いの[blank]、冬は乾燥しています。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, 'Untuk mengontraskan dua klausa, gunakan bentuk biasa + のに対して.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9ace02d3-d3e2-48bc-bee4-eef489e9948a', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan pengingat perjalanan berikut. Mengapa pembicara memberi saran itu?', '{"options":[{"id":"opt_1","text":"Rest area berikutnya hanya berjarak lima menit"},{"id":"opt_2","text":"Perjalanan bus sudah selesai di tempat ini"},{"id":"opt_3","text":"Toilet di rest area ini sedang tidak bisa digunakan"},{"id":"opt_4","text":"Menyarankan pergi ke toilet sekarang mumpung ada kesempatan karena rest area berikutnya masih satu jam lagi"}],"audio_text":"今のうちにトイレに行っておいたほうがいいですよ。次のサービスエリアまで一時間ありますから。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '今のうちに berarti ''mumpung sekarang / selagi ada kesempatan''.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ad674e6-2744-446e-93ff-30c1e9de7eb1', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mumpung masih terang, mari kita selesaikan memasang tenda."', '{"romaji":"Akarui uchi ni tento o hatte shimaimashou.","display_text":"明るいうちにテントを張ってしまいましょう。","phonetic_breakdown":["a-ka-ru-i","u-chi-ni","ten-to-o","hat-te","shi-ma-i-ma-shou"]}'::jsonb, '{"expected_transcript":"明るいうちにテントを張ってしまいましょう。"}'::jsonb, NULL, NULL, '明るい (kata sifat い) + うちに.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6cdf06c-d5b6-46cb-b16f-dcd51464c29e', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Selagi berbincang dengannya, rasa gugup saya benar-benar mencair."', '{"romaji":"Kare to hanashite iru uchi ni, sukkari kinchou ga hoguremashita.","tokens":["を","話したせいで、","話している","ほぐれました。","彼と","緊張が","すっかり","うちに、"],"target_translation":"Selagi berbincang dengannya, rasa gugup saya benar-benar mencair."}'::jsonb, '["彼と","話している","うちに、","すっかり","緊張が","ほぐれました。"]'::jsonb, NULL, NULL, '話しているうちに menyatakan perubahan perasaan yang alami.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e00c2fc8-2ea6-4d77-99cd-3709cedbcc6d', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 学生___うちに、いろいろな本を読んでおくことをおすすめします。', '{"options":["の","に","な","だ"],"translation":"Mumpung masih mahasiswa, saya menyarankan banyak membaca berbagai buku.","sentence_template":"学生[blank]うちに、いろいろな本を読んでおくことをおすすめします。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, '学生 (kata benda) + のうちに.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1292ef23-380c-4fdf-8c8e-5272458ff691', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan rencana keberangkatan berikut. Mengapa mereka berangkat pukul 6 pagi?', '{"options":[{"id":"opt_1","text":"Berencana berangkat pukul 6 pagi mumpung jalanan belum macet"},{"id":"opt_2","text":"Menunda keberangkatan sampai siang agar tidak macet"},{"id":"opt_3","text":"Tidak jadi berangkat karena jalanan ditutup"},{"id":"opt_4","text":"Berangkat pukul 6 pagi karena jalanan sedang sangat macet"}],"audio_text":"道が混まないうちに、朝六時には出発する予定です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '混まないうちに berarti ''selagi belum macet''.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1c1bddeb-711f-4952-8d79-3b66c8815c48', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Selagi terus berlatih, lama-kelamaan jadi semakin menyenangkan."', '{"romaji":"Renshuu o tsuzukete iru uchi ni, dandan tanoshiku natte kimashita.","display_text":"練習を続けているうちに、だんだん楽しくなってきました。","phonetic_breakdown":["ren-shuu-o","tsu-zu-ke-te-i-ru","u-chi-ni","dan-dan","ta-no-shi-ku","nat-te-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"練習を続けているうちに、だんだん楽しくなってきました。"}'::jsonb, NULL, NULL, '続けているうちに + だんだん menggambarkan proses bertahap.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d91032c3-260d-4c4e-8801-5359116e59f6', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mumpung liburan musim semi, saya ingin mengambil SIM."', '{"romaji":"Haruyasumi no uchi ni, unten menkyo o toritai desu.","tokens":["取りたいです。","運転免許を","春休みな","春休みの","が","うちに、"],"target_translation":"Mumpung liburan musim semi, saya ingin mengambil SIM."}'::jsonb, '["春休みの","うちに、","運転免許を","取りたいです。"]'::jsonb, NULL, NULL, '春休み (kata benda) + のうちに.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e604ec80-f868-40da-966f-e9e9fe7d6adf', '33ceaa51-e4e1-467c-acad-7770916afdc1', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 桜が散らない___、今週末にお花見に行きましょう。', '{"options":["ばかりに","うちに","せいで","おかげで"],"translation":"Mumpung bunga sakura belum berguguran, mari pergi hanami akhir pekan ini.","sentence_template":"桜が散らない[blank]、今週末にお花見に行きましょう。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '散らない (bentuk ない) + うちに.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('34cc4084-53c7-5de3-aef1-30c539b98679', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya diminta tolong oleh senior."', '{"romaji":"Senpai ni shigoto o tanomaremashita.","display_text":"先輩に仕事を頼まれました。","phonetic_breakdown":["sen-pa-i ni","shi-go-to o","ta-no-ma-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先輩に仕事を頼まれました。"}'::jsonb, NULL, NULL, '頼まれました adalah bentuk pasif lampau sopan dari 頼む (meminta).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('455777bf-28c3-5b87-8943-96f8e6ffbc63', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya kehujanan dalam perjalanan pulang."', '{"romaji":"Kaeru tochuu de ame ni furaremashita.","display_text":"帰る途中で雨に降られました。","phonetic_breakdown":["ka-e-ru","to-chuu de","a-me ni","fu-ra-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"帰る途中で雨に降られました。"}'::jsonb, NULL, NULL, '雨に降られる adalah bentuk pasif khas Jepang untuk menyatakan kerugian/ketidaknyamanan karena hujan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73d7d2bc-ff44-52c0-a611-00f9c5d67bf5', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapat tahunan diselenggarakan setiap bulan Maret."', '{"romaji":"Nenji kaigi wa maitoshi sangatsu ni kaisai saremasu.","display_text":"年次会議は毎年三月に開催されます。","phonetic_breakdown":["nen-ji ka-i-gi wa","ma-i-to-shi","san-ga-tsu ni","ka-i-sa-i","sa-re-ma-su"]}'::jsonb, '{"expected_transcript":"年次会議は毎年三月に開催されます。"}'::jsonb, NULL, NULL, 'Verba する berubah menjadi される pada bentuk pasif (開催する -> 開催される).', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('29cec591-b036-56ab-8dee-33969a91d759', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Saya diundang ke pesta pernikahan teman."', '{"romaji":"Tomodachi no kekkonshiki ni shoutai saremashita.","tokens":["されました。","しました。","友達の結婚式に","させました。","招待"],"target_translation":"Saya diundang ke pesta pernikahan teman."}'::jsonb, '["友達の結婚式に","招待","されました。"]'::jsonb, NULL, NULL, '招待する (mengundang) -> 招待されました (diundang).', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c4db2aa-b3a6-52fd-9ef3-2b5fb2ecc9c6', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Kue yang saya simpan dimakan oleh kakak."', '{"romaji":"Tottte oita keeki o ani ni taberaremashita.","tokens":["食べられました。","兄に","食べました。","とっておいたケーキを","兄が"],"target_translation":"Kue yang saya simpan dimakan oleh kakak."}'::jsonb, '["とっておいたケーキを","兄に","食べられました。"]'::jsonb, NULL, NULL, '食べられました menyatakan pengalaman dirugikan karena kue dimakan kakak.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57955355-fd20-56ed-b173-50104262f71a', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Produk ini dijual di seluruh Jepang."', '{"romaji":"Kono shouhin wa nihonjuu de hanbai sarete imasu.","tokens":["この商品は","日本中で","販売して","販売させて","います。","販売されて"],"target_translation":"Produk ini dijual di seluruh Jepang."}'::jsonb, '["この商品は","日本中で","販売されて","います。"]'::jsonb, NULL, NULL, '販売する (menjual) -> 販売されています (dijual).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f813f7e0-0755-4598-ba99-a0a232261b12', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pelafalan bahasa Jepang saya dipuji oleh guru."', '{"romaji":"Sensei ni Nihongo no hatsuon o homeraremashita.","display_text":"先生に日本語の発音を褒められました。","phonetic_breakdown":["sen-sei-ni","ni-hon-go-no","ha-tsu-on-o","ho-me-ra-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先生に日本語の発音を褒められました。"}'::jsonb, NULL, NULL, '先生に (oleh guru) + 褒められました (dipuji).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a9c4540-d41f-4332-8b26-1850d03684b8', '348683d9-8f16-52e1-80bd-086768e2398c', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Puding saya dimakan oleh adik laki-laki (dan saya kesal)."', '{"romaji":"Otouto ni watashi no purin o taberarete shimaimashita.","tokens":["食べて","プリンを","弟に","しまいました。","が","私の","食べられて"],"target_translation":"Puding saya dimakan oleh adik laki-laki (dan saya kesal)."}'::jsonb, '["弟に","私の","プリンを","食べられて","しまいました。"]'::jsonb, NULL, NULL, '食べられてしまいました menggabungkan pasif penderitaan dengan ～てしまう.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1950b039-1243-5123-a5a8-dd2767d7b2f7', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat penugasan kerja: 来月から大阪支社へ ___ します。', '{"options":["転勤","欠勤","出勤","残業"],"translation":"Mulai bulan depan saya dipindahtugaskan ke cabang Osaka.","sentence_template":"来月から大阪支社へ [blank] します。"}'::jsonb, '{"selected":"転勤"}'::jsonb, NULL, NULL, '転勤 (tenkin) berarti mutasi/pindah tugas ke cabang lain. 出勤 (masuk kerja), 欠勤 (absen kerja), 残業 (lembur).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('89f5eee1-5d55-5e1a-8942-51e8ec932cf9', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk rapat kantor: 今日の午後は大切な ___ があります。', '{"options":["打ち合わせ","問い合わせ","待ち合わせ","組み合わせ"],"translation":"Siang ini ada rapat koordinasi yang penting.","sentence_template":"今日の午後は大切な [blank] があります。"}'::jsonb, '{"selected":"打ち合わせ"}'::jsonb, NULL, NULL, '打ち合わせ (uchiawase) berarti rapat koordinasi/persiapan kerja.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f10bab5d-b29b-5915-85b5-186e3489893a', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi: 会議の開始時間が変更になったので、全員に ___ してください。', '{"options":["連絡","延期","中止","参加"],"translation":"Karena jam mulai rapat berubah, tolong beri tahu semua orang.","sentence_template":"会議の開始時間が変更になったので、全員に [blank] してください。"}'::jsonb, '{"selected":"連絡"}'::jsonb, NULL, NULL, '連絡する (renraku suru) berarti menghubungi atau memberi tahu.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('79df3b4d-7dd1-5ecb-bbcb-fe327b8e9f3d', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang sesuai: 大雨のため、屋外イベントは来週へ ___ されました。', '{"options":["延期","開始","決定","担当"],"translation":"Karena hujan deras, acara luar ruang ditunda ke minggu depan.","sentence_template":"大雨のため、屋外イベントは来週へ [blank] されました。"}'::jsonb, '{"selected":"延期"}'::jsonb, NULL, NULL, '延期 (enki) berarti penundaan jadwal ke waktu lain.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('894c6f26-1844-51d2-a711-674a5d932464', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'listening', 'listening_choice', 'Di mana tempat kerja baru pembicara mulai bulan April?', '{"options":[{"id":"opt_1","text":"Di kantor pusat Tokyo"},{"id":"opt_2","text":"Di kantor cabang Nagoya"},{"id":"opt_3","text":"Di pabrik dekat bandara"},{"id":"opt_4","text":"Bekerja penuh dari rumah"}],"audio_text":"四月から東京の本社で新しいプロジェクトを担当します。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '東京の本社 berarti kantor pusat Tokyo, dan 担当します berarti menjadi penanggung jawab.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d4cd5a2-82cd-558d-8720-3ac2c1011b6b', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', NULL, 'listening', 'listening_choice', 'Apa isi pengumuman mengenai jam kerja hari Jumat?', '{"options":[{"id":"opt_1","text":"Hari Jumat kantor libur penuh"},{"id":"opt_2","text":"Pekerjaan berakhir satu jam lebih awal karena pelatihan internal"},{"id":"opt_3","text":"Seluruh staf harus lembur satu jam untuk pelatihan"},{"id":"opt_4","text":"Pelatihan internal dipindahkan ke hari Senin pagi"}],"audio_text":"今週の金曜日は社内研修があるため、通常より一時間早く業務を終了します。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '社内研修があるため、通常より一時間早く業務を終了します berarti berakhir satu jam lebih awal karena pelatihan internal.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9037c6fe-15db-4da0-bd61-475fde3692c2', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 来月から大阪支社へ___することになりました。', '{"options":["散歩","充電","見学","転勤"],"translation":"Diputuskan bahwa mulai bulan depan saya akan dipindahtugaskan ke cabang Osaka.","sentence_template":"来月から大阪支社へ[blank]することになりました。"}'::jsonb, '{"selected":"転勤"}'::jsonb, NULL, NULL, '転勤する (tenkin suru) berarti mutasi/pindah lokasi kerja dalam perusahaan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('278f206e-1e01-4394-afe9-a0b181dcff40', '39d94c02-bb2c-5c68-a2e8-14f26bf6f132', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan pengumuman kantor berikut. Apa keputusan terkait rapat mendatang?', '{"options":[{"id":"opt_1","text":"Tautan rapat daring tidak jadi digunakan"},{"id":"opt_2","text":"Rapat mendatang diputuskan akan diselenggarakan secara daring"},{"id":"opt_3","text":"Rapat mendatang dibatalkan sepenuhnya"},{"id":"opt_4","text":"Rapat mendatang wajib dihadiri langsung di gedung utama"}],"audio_text":"今度の会議はオンラインで開催されることになりましたので、URLをご確認ください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '開催されることになりました menyampaikan keputusan resmi organisasi secara objektif.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbc7904d-8b7c-5040-a909-589fc33f389f', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi dugaan logis: 彼は十年も日本に住んでいたので、日本語が上手 ___ はずです。', '{"options":["な","の","だ","に"],"translation":"Karena dia tinggal di Jepang selama sepuluh tahun, bahasa Jepangnya seharusnya mahir.","sentence_template":"彼は十年も日本に住んでいたので、日本語が上手 [blank] はずです。"}'::jsonb, '{"selected":"な"}'::jsonb, NULL, NULL, 'Kata sifat-NA (上手) memakai な sebelum はずです.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5c53da2-bc8d-5732-8b86-81f642a1d16d', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Pilih bentuk penyangkalan kuat: 昨日送ったばかりだから、まだ届いている ___ 。', '{"options":["はずがありません","はずです","ようです","そうです"],"translation":"Karena baru saja dikirim kemarin, tidak mungkin sudah sampai.","sentence_template":"昨日送ったばかりだから、まだ届いている [blank] 。"}'::jsonb, '{"selected":"はずがありません"}'::jsonb, NULL, NULL, '～はずがありません berarti ''tidak mungkin secara logis''.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44bbf2eb-e81b-559e-9218-9ce453dcb9b4', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 今日は祝日なので、銀行は休み ___ はずです。', '{"options":["の","な","だ","で"],"translation":"Karena hari ini hari libur nasional, bank seharusnya tutup.","sentence_template":"今日は祝日なので、銀行は休み [blank] はずです。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Nomina (休み) dihubungkan dengan の sebelum はずです.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21eb8eb0-7c0d-5674-8b54-5f1006860892', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah mengirim email, dia seharusnya tahu."', '{"romaji":"Meeru o okutta node, kare wa shitte iru hazu desu.","tokens":["彼は","メールを送ったので、","はずがありません。","知っている","知って","はずです。"],"target_translation":"Karena sudah mengirim email, dia seharusnya tahu."}'::jsonb, '["メールを送ったので、","彼は","知っている","はずです。"]'::jsonb, NULL, NULL, '知っている (bentuk kamus) + はずです menyatakan keyakinan logis.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b77f4ab-65aa-5b25-a111-650bcbc853b2', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Orang yang begitu teliti tidak mungkin membuat kesalahan."', '{"romaji":"Majimena ano hito ga machigaeru hazu ga arimasen.","tokens":["はずが","間違えて","まじめなあの人が","はずでした。","間違える","ありません。"],"target_translation":"Orang yang begitu teliti tidak mungkin membuat kesalahan."}'::jsonb, '["まじめなあの人が","間違える","はずが","ありません。"]'::jsonb, NULL, NULL, '間違える + はずがありません menyatakan ketidakmungkinan berdasarkan sifat orang tersebut.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70c22de6-57ca-5f43-9ec0-da5bff76254a', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Apa yang membuat pembicara yakin barang tersebut masih ada di toko?', '{"options":[{"id":"opt_1","text":"Karena produk itu baru saja dirilis hari ini"},{"id":"opt_2","text":"Karena pembicara baru saja menanyakannya lewat telepon"},{"id":"opt_3","text":"Karena toko tersebut jarang dikunjungi pembeli"},{"id":"opt_4","text":"Karena ia melihatnya di situs web kemarin malam"}],"audio_text":"さっき電話で問い合わせたばかりなので、まだ在庫があるはずです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'さっき電話で問い合わせたばかりなので berarti karena baru saja menanyakan lewat telepon tadi.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ab86cca8-805f-42ad-8c38-57afd42cc758', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 田中さんは十年もフランスに住んでいたので、フランス語が話せる___。', '{"options":["せいです","ばかりです","はずです","うちです"],"translation":"Karena Tanaka-san pernah tinggal di Prancis 10 tahun, seharusnya dia bisa berbahasa Prancis.","sentence_template":"田中さんは十年もフランスに住んでいたので、フランス語が話せる[blank]。"}'::jsonb, '{"selected":"はずです"}'::jsonb, NULL, NULL, 'Bentuk biasa (話せる) + はずです menyatakan dugaan kuat yang masuk akal.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1f85c6bf-1959-4d0d-afb8-6283f9099fc3', '48470705-b669-5414-a39e-ecdd7c9f9eda', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Karena dia orang yang sungguh-sungguh, tidak mungkin dia mengingkari janji."', '{"romaji":"Kare wa majime dakara, yakusoku o yaburu hazu ga arimasen.","tokens":["はずが","彼は","破る","を","真面目だから、","はずが","約束を","ありません。"],"target_translation":"Karena dia orang yang sungguh-sungguh, tidak mungkin dia mengingkari janji."}'::jsonb, '["彼は","真面目だから、","約束を","破る","はずが","ありません。"]'::jsonb, NULL, NULL, '～はずがありません menyatakan penyangkalan kuat (''mustahil / tidak mungkin'').', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d2a8379-b678-5eae-bf19-4896ff38b8be', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat awal karier: 今年の四月にこの会社へ ___ しました。', '{"options":["入社","退社","出張","見学"],"translation":"Pada bulan April tahun ini saya masuk bergabung di perusahaan ini.","sentence_template":"今年の四月にこの会社へ [blank] しました。"}'::jsonb, '{"selected":"入社"}'::jsonb, NULL, NULL, '入社 (nyuusha) berarti masuk menjadi karyawan suatu perusahaan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dc4b607c-f22c-5887-8089-8530eb619b9a', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk pindahan: 先週末に新しいアパートへ ___ しました。', '{"options":["引っ越し","旅行","散歩","帰国"],"translation":"Akhir pekan lalu saya pindah ke apartemen baru.","sentence_template":"先週末に新しいアパートへ [blank] しました。"}'::jsonb, '{"selected":"引っ越し"}'::jsonb, NULL, NULL, '引っ越し (hikkoshi) berarti pindahan tempat tinggal.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c4dd356b-6213-5709-8127-b734d946227e', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat adaptasi: 新しい生活にまだ十分 ___ ていません。', '{"options":["慣れ","忘れ","晴れ","壊れ"],"translation":"Saya belum cukup terbiasa dengan kehidupan baru.","sentence_template":"新しい生活にまだ十分 [blank] ていません。"}'::jsonb, '{"selected":"慣れ"}'::jsonb, NULL, NULL, '慣れる (nareru) berarti terbiasa. 慣れていません = belum terbiasa.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('309550ca-c175-56ac-92ac-a7de1209b4eb', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'reading', 'fill_blank', 'Pilih kata untuk kelulusan: 先月大学を ___ して、今は研修を受けています。', '{"options":["卒業","入学","休学","留学"],"translation":"Bulan lalu saya lulus universitas, dan sekarang sedang mengikuti pelatihan.","sentence_template":"先月大学を [blank] して、今は研修を受けています。"}'::jsonb, '{"selected":"卒業"}'::jsonb, NULL, NULL, '卒業する (sotsugyou suru) berarti lulus dari sekolah/universitas.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7c1100b-6f97-5838-b2e0-e36ce831b7d6', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'listening', 'listening_choice', 'Bagaimana kondisi apartemen baru pembicara saat ini?', '{"options":[{"id":"opt_1","text":"Masih banyak kardus pindahan yang belum dibuka di kamar"},{"id":"opt_2","text":"Semua perabot sudah tertata rapi sejak hari pertama"},{"id":"opt_3","text":"Ia sedang mencari teman sekamar untuk berbagi sewa"},{"id":"opt_4","text":"Listrik dan internetnya belum tersambung"}],"audio_text":"先週引っ越してきたので、部屋にはまだ開けていない段ボールがたくさん残っています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'まだ開けていない段ボールがたくさん残っています berarti masih banyak kardus yang belum dibuka.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8b691b4e-c593-510e-9227-52e6fb9fb7ab', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', NULL, 'listening', 'listening_choice', 'Apa kesulitan awal yang dialami pembicara di divisi baru?', '{"options":[{"id":"opt_1","text":"Jarak tempuh ke kantor terlalu jauh dari rumah"},{"id":"opt_2","text":"Kesulitan menghafal istilah khusus dan alur prosedur internal"},{"id":"opt_3","text":"Jadwal makan siang terlalu singkat"},{"id":"opt_4","text":"Komputer kantornya belum terpasang perangkat lunak"}],"audio_text":"配属されて間もないので、社内の専門用語や手続きの流れを覚えるのに苦労しています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '社内の専門用語や手続きの流れを覚えるのに苦労しています berarti kesulitan menghafal istilah khusus dan alur prosedur kantor.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ba9a4d57-1399-421f-956a-beb7a0ec730d', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 先月この部署に___されたばかりなので、まだ覚えることが多いです。', '{"options":["配属","予約","卒業","散歩"],"translation":"Karena baru saja ditempatkan di divisi ini bulan lalu, masih banyak hal yang perlu saya pelajari.","sentence_template":"先月この部署に[blank]されたばかりなので、まだ覚えることが多いです。"}'::jsonb, '{"selected":"配属"}'::jsonb, NULL, NULL, '配属される (haizoku sareru) berarti ditempatkan di divisi kerja; ～たばかり menekankan perasaan ''masih baru''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a92a8eb-3e08-4e53-bc7e-ae4d3e99a4c4', '4e85310c-bc2b-56a4-b9f5-f2599ecc9c99', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan perkenalan berikut. Mengapa pembicara belum terbiasa naik kereta?', '{"options":[{"id":"opt_1","text":"Sudah tinggal di Jepang selama bertahun-tahun dan hafal semua jalur"},{"id":"opt_2","text":"Akan berangkat ke Jepang minggu depan"},{"id":"opt_3","text":"Sudah sangat mahir berpindah kereta di Tokyo"},{"id":"opt_4","text":"Baru saja datang ke Jepang minggu lalu sehingga belum terbiasa berpindah kereta"}],"audio_text":"先週日本へ来たばかりなので、電車の乗り換えにまだ慣れていません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '来たばかり menunjukkan perasaan pembicara bahwa kedatangannya masih sangat baru.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74756b5e-882a-4ee6-b042-20a02aa4d879', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客様に___、いつも笑顔で接することを心がけています。', '{"options":["かわりに","よって","対して","ついて"],"translation":"Saya selalu berusaha bersikap ramah dengan senyuman terhadap pelanggan.","sentence_template":"お客様に[blank]、いつも笑顔で接することを心がけています。"}'::jsonb, '{"selected":"対して"}'::jsonb, NULL, NULL, 'お客様に対して menyatakan sasaran layanan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cd7243a7-99d0-4176-b2cc-2629ea2c86f5', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 都心部の人口が増えているの___、地方では減少が続いています。', '{"options":["おかげで","に対して","はずで","せいで"],"translation":"Berbeda dengan populasi pusat kota yang meningkat, di daerah terus mengalami penurunan.","sentence_template":"都心部の人口が増えているの[blank]、地方では減少が続いています。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, '増えているのに対して mengontraskan dua tren data yang berlawanan.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e53e0415-4199-4690-a499-71d14fa12cc6', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan informasi fasilitas kerja berikut. Bagaimana rasio pembagian laptop?', '{"options":[{"id":"opt_1","text":"Karyawan harus membeli laptop sendiri"},{"id":"opt_2","text":"Satu laptop dipakai bergantian oleh seluruh divisi"},{"id":"opt_3","text":"Hanya manajer yang mendapatkan laptop kantor"},{"id":"opt_4","text":"Untuk setiap satu karyawan, diberikan satu unit laptop"}],"audio_text":"社員一人に対して一台ずつノートパソコンが支給されます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '～に対して juga dipakai untuk menyatakan perbandingan rasio (per satu orang).', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90212a7e-50b4-4afb-8e09-44e721662348', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Ada pengumuman resmi perusahaan terkait rumor tersebut."', '{"romaji":"Sono uwasa ni taisuru kaisha no koushiki happyou ga arimashita.","tokens":["ありました。","噂に","公式発表が","対する","を","会社の","その","対して"],"target_translation":"Ada pengumuman resmi perusahaan terkait rumor tersebut."}'::jsonb, '["その","噂に","対する","会社の","公式発表が","ありました。"]'::jsonb, NULL, NULL, 'Saat menerangkan kata benda di belakangnya, に対して berubah menjadi に対する.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9fe39cdd-77fd-4773-a125-6339721ff212', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 店員は誰に___も親切に対応してくれました。', '{"options":["おいて","よって","対して","つれて"],"translation":"Pegawai toko melayani siapa pun dengan ramah.","sentence_template":"店員は誰に[blank]も親切に対応してくれました。"}'::jsonb, '{"selected":"対して"}'::jsonb, NULL, NULL, '誰に対しても berarti ''terhadap siapa pun''.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4da20fe1-b61a-4c77-bc72-c0766b202380', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tingkat kepuasan pelanggan terhadap produk baru sangat tinggi."', '{"romaji":"Shinseihin ni taisuru okyakusama no manzokudo wa hijou ni takai desu.","display_text":"新製品に対するお客様の満足度は非常に高いです。","phonetic_breakdown":["shin-sei-hin-ni","tai-su-ru","o-kya-ku-sa-ma-no","man-zo-ku-do-wa","hi-jou-ni","ta-ka-i-de-su"]}'::jsonb, '{"expected_transcript":"新製品に対するお客様の満足度は非常に高いです。"}'::jsonb, NULL, NULL, '新製品に対する menerangkan 満足度 (tingkat kepuasan).', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff91c924-0f85-42bb-a25a-d4dc3c26296d', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan ringkasan bisnis berikut. Bagaimana perbandingan penjualan dua tahun ini?', '{"options":[{"id":"opt_1","text":"Berbeda dengan tahun lalu saat penjualan turun, tahun ini tumbuh besar berkat produk baru"},{"id":"opt_2","text":"Produk baru tidak memberikan pengaruh pada penjualan"},{"id":"opt_3","text":"Penjualan tahun lalu dan tahun ini sama persis"},{"id":"opt_4","text":"Penjualan tahun ini turun lebih tajam daripada tahun lalu"}],"audio_text":"昨年は売上が減少したのに対して、今年は新商品の効果で大きく伸びました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '減少したのに対して membandingkan kondisi tahun lalu dan tahun ini.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d0c60f3-eafa-4c2f-a3ad-e01b956e102a', '500b9cc3-0a01-40a0-a5cf-b05a02e4cd9c', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Kepedulian masyarakat terhadap masalah lingkungan semakin meningkat."', '{"romaji":"Kankyou mondai ni taisuru hitobito no kanshin ga takamatte imasu.","tokens":["対する","環境問題に","関心が","対して","を","人々の","高まっています。"],"target_translation":"Kepedulian masyarakat terhadap masalah lingkungan semakin meningkat."}'::jsonb, '["環境問題に","対する","人々の","関心が","高まっています。"]'::jsonb, NULL, NULL, '問題に対する関心 = kepedulian terhadap masalah.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0dcc68e0-cb55-5fec-961a-ea765bfbbe38', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Pilih pola yang tepat: 来期から新しい評価制度が導入 ___ ことになりました。', '{"options":["される","された","されて","します"],"translation":"Diputuskan bahwa mulai periode depan sistem penilaian baru akan diterapkan.","sentence_template":"来期から新しい評価制度が導入 [blank] ことになりました。"}'::jsonb, '{"selected":"される"}'::jsonb, NULL, NULL, '導入される (diterapkan, pasif bentuk kamus) diikuti ことになりました.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ead5b1bf-605d-5d89-a740-938751dc7f92', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi aturan apartemen: 燃えるゴミは火曜日と金曜日に ___ ことになっています。', '{"options":["出す","出した","出して","出します"],"translation":"Aturannya sampah yang bisa dibakar dibuang pada hari Selasa dan Jumat.","sentence_template":"燃えるゴミは火曜日と金曜日に [blank] ことになっています。"}'::jsonb, '{"selected":"出す"}'::jsonb, NULL, NULL, 'ゴミを出す (membuang sampah) dalam bentuk kamus sebelum ことになっています.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('478647c7-a79d-5ad1-ad10-63018afefa97', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Apa aturan kantor terkait jam istirahat makan siang?', '{"options":[{"id":"opt_1","text":"Jam istirahat selalu dimulai pukul sebelas"},{"id":"opt_2","text":"Pegawai dilarang keluar gedung saat jam istirahat"},{"id":"opt_3","text":"Pada hari sibuk pegawai beristirahat secara bergantian"},{"id":"opt_4","text":"Jika sibuk jam istirahat ditiadakan dan diganti uang lembur"}],"audio_text":"昼休みは十二時から一時までですが、忙しい日は交代で休むことになっています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '交代で休むことになっています berarti aturannya beristirahat secara bergantian.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e39c3ada-6106-5e19-86c6-6521702ebe12', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Mengapa jadwal pengiriman barang berubah?', '{"options":[{"id":"opt_1","text":"Karena pesanan dari pelanggan dibatalkan"},{"id":"opt_2","text":"Karena alamat pengiriman belum lengkap"},{"id":"opt_3","text":"Karena gudang sedang pindah lokasi"},{"id":"opt_4","text":"Karena ada jadwal inspeksi pabrik"}],"audio_text":"工場の点検が入ったため、商品の発送は来週の月曜日に行うことになりました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '工場の点検が入ったため berarti karena ada inspeksi/pengecekan pabrik.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4af0c137-3d5e-5d91-ba4b-5895eceb25b7', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Aturannya laporan dikumpulkan setiap hari Jumat."', '{"romaji":"Maishuu kinyoubi ni houkokusho o dasu koto ni natte imasu.","tokens":["しています。","報告書を","ことに","毎週金曜日に","なっています。","出す","出した"],"target_translation":"Aturannya laporan dikumpulkan setiap hari Jumat."}'::jsonb, '["毎週金曜日に","報告書を","出す","ことに","なっています。"]'::jsonb, NULL, NULL, '報告書を出す + ことになっています menyatakan kewajiban rutin sesuai prosedur.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7bd002d0-88b9-5cdb-93bb-e2dde6ea7473', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan belajar di universitas di Jepang."', '{"romaji":"Nihon no daigaku ni ryuugaku suru koto ni narimashita.","display_text":"日本の大学に留学することになりました。","phonetic_breakdown":["ni-hon no","da-i-ga-ku ni","ryuu-ga-ku su-ru","ko-to ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"日本の大学に留学することになりました。"}'::jsonb, NULL, NULL, '留学する (ryuugaku suru) berarti studi ke luar negeri. Cocok dipakai saat hasil seleksi beasiswa/kampus sudah resmi.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('520478bd-d1f4-4f6c-8375-4a086c6e79b6', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この寮では、夜十一時以降は洗濯機を使わない___。', '{"options":["せいにしています","ことにしています","ようにしています","ことになっています"],"translation":"Di asrama ini aturannya tidak menggunakan mesin cuci setelah pukul 11 malam.","sentence_template":"この寮では、夜十一時以降は洗濯機を使わない[blank]。"}'::jsonb, '{"selected":"ことになっています"}'::jsonb, NULL, NULL, 'Bentuk ない + ことになっています menyatakan larangan atau tata tertib resmi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('12c7030e-b493-4200-b52e-032f1f0913a1', '561c2619-0aa5-55d6-ac2d-b46ba2d51e23', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebentar lagi saya dan Sato-san akan menikah."', '{"romaji":"Kondo, Satou-san to kekkon suru koto ni narimashita.","display_text":"今度、佐藤さんと結婚することになりました。","phonetic_breakdown":["kon-do","sa-tou-san-to","kek-kon-su-ru","ko-to-ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"今度、佐藤さんと結婚することになりました。"}'::jsonb, NULL, NULL, 'Dalam bahasa Jepang, mengumumkan pernikahan memakai ～ことになりました agar terdengar sopan dan tidak memaksa.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b685eb7-f82e-5276-9791-173a0fe02243', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: さっき帰国 ___ ばかりなので、まだ時差ぼけがあります。', '{"options":["した","する","して","します"],"translation":"Karena baru saja pulang ke tanah air tadi, saya masih mengalami jet lag.","sentence_template":"さっき帰国 [blank] ばかりなので、まだ時差ぼけがあります。"}'::jsonb, '{"selected":"した"}'::jsonb, NULL, NULL, '帰国した (Bentuk-TA) + ばかりなので.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7bc0afba-eec6-53c6-92af-5759fce32e64', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi frasa nomina: 先週届いた ___ の家具を組み立てています。', '{"options":["ばかり","はず","うち","せい"],"translation":"Saya sedang merakit perabot yang baru saja tiba minggu lalu.","sentence_template":"先週届いた [blank] の家具を組み立てています。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '届いたばかりの家具 berarti perabot yang baru saja sampai.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb3e3756-db59-5467-a557-c0b03b381568', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa langsung menerima tugas tambahan tersebut?', '{"options":[{"id":"opt_1","text":"Karena ia akan mengambil cuti panjang minggu depan"},{"id":"opt_2","text":"Karena ia sedang dinas di luar kota"},{"id":"opt_3","text":"Karena baru pindah divisi dan masih berjuang menguasai tugas saat ini"},{"id":"opt_4","text":"Karena komputernya sedang dalam perbaikan"}],"audio_text":"新しい部署に異動したばかりで、今の業務を覚えるので精一杯なんです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '新しい部署に異動したばかりで berarti baru saja mutasi ke divisi baru.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dfde6e51-f1d1-5bbf-9745-600c14cd1ca8', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Apa yang terjadi pada baju kemeja pembicara?', '{"options":[{"id":"opt_1","text":"Kancing kemejanya lepas saat naik kereta"},{"id":"opt_2","text":"Kemejanya tertukar di tempat binatu"},{"id":"opt_3","text":"Ia lupa menyetrika kemejanya pagi ini"},{"id":"opt_4","text":"Kemeja yang baru disetrika pagi ini ketumpahan kopi"}],"audio_text":"今朝アイロンをかけたばかりのシャツに、コーヒーをこぼしてしまいました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '今朝アイロンをかけたばかりのシャツに、コーヒーをこぼしてしまいました berarti menumpahkan kopi ke kemeja yang baru disetrika.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e47fa12-ebaf-5625-8d41-ea3691fcf184', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Karena baru datang ke kota ini, saya belum punya banyak teman."', '{"romaji":"Kono machi ni kita bakari na node, mada tomodachi ga sukunai desu.","tokens":["まだ友達が","少ないです。","ばかりなので、","この町に","多いです。","来て","来た"],"target_translation":"Karena baru datang ke kota ini, saya belum punya banyak teman."}'::jsonb, '["この町に","来た","ばかりなので、","まだ友達が","少ないです。"]'::jsonb, NULL, NULL, '来たばかりなので menyatakan kondisi baru tiba di kota tersebut.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d145534-d3ea-565c-85a5-16c3f996d3ed', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru saja masuk perusahaan ini bulan lalu."', '{"romaji":"Sengetsu kono kaisha ni nyuusha shita bakari desu.","display_text":"先月この会社に入社したばかりです。","phonetic_breakdown":["sen-ge-tsu","ko-no ka-i-sha ni","nyuu-sha shi-ta","ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript":"先月この会社に入社したばかりです。"}'::jsonb, NULL, NULL, 'Kalimat perkenalan standar yang sopan bagi karyawan baru di Jepang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4bf8fe27-fda4-40eb-9d6c-0c16375e0631', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼は日本に留学して半年前に卒業した___の新入社員です。', '{"options":["はず","ばかり","うち","せい"],"translation":"Dia adalah karyawan baru yang baru saja lulus setengah tahun lalu setelah belajar di Jepang.","sentence_template":"彼は日本に留学して半年前に卒業した[blank]の新入社員です。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '卒業したばかりの menerangkan 新入社員 (karyawan baru).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f41f2405-2cf0-4cfb-9a50-8affcbf5a875', '59d92772-1879-5646-ba88-c5a41ab5c4e6', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru saja menyalakan mesin cuci sekarang."', '{"romaji":"Ima, sentakuki o mawashita bakari desu.","display_text":"今、洗濯機を回したばかりです。","phonetic_breakdown":["i-ma","sen-ta-ku-ki-o","ma-wa-shi-ta","ba-ka-ri-de-su"]}'::jsonb, '{"expected_transcript":"今、洗濯機を回したばかりです。"}'::jsonb, NULL, NULL, '回したばかり menyatakan tindakan yang baru beberapa saat lalu dilakukan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('50c0b274-10d1-5fe1-837b-d5402700f3f7', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 急いで ___ せいで、大切な書類を家に忘れてしまいました。', '{"options":["出た","出て","出ます","出よう"],"translation":"Gara-gara berangkat terburu-buru, saya kelupaan dokumen penting di rumah.","sentence_template":"急いで [blank] せいで、大切な書類を家に忘れてしまいました。"}'::jsonb, '{"selected":"出た"}'::jsonb, NULL, NULL, 'Bentuk biasa lampau 出た + せいで.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('beb8bffc-0333-5c2d-b451-01f00f7c92ad', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi dengan adjektiva-NA: 道が ___ せいで、目的地に着くまで時間がかかりました。', '{"options":["複雑な","複雑の","複雑だ","複雑で"],"translation":"Gara-gara jalannya rumit, butuh waktu lama untuk sampai ke tujuan.","sentence_template":"道が [blank] せいで、目的地に着くまで時間がかかりました。"}'::jsonb, '{"selected":"複雑な"}'::jsonb, NULL, NULL, 'Kata sifat-NA memakai な sebelum せいで (複雑なせいで).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7507e08d-7609-5549-a921-4064116335e0', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Apa penyebab penjualan toko menurun minggu ini?', '{"options":[{"id":"opt_1","text":"Karena toko sedang melakukan renovasi"},{"id":"opt_2","text":"Karena produk baru belum tiba dari pabrik"},{"id":"opt_3","text":"Karena hujan turun terus-menerus selama seminggu"},{"id":"opt_4","text":"Karena banyak pegawai sedang cuti tahunan"}],"audio_text":"一週間ずっと雨が降り続いたせいで、今週は来店客が大きく減りました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '一週間ずっと雨が降り続いたせいで berarti gara-gara hujan turun terus-menerus seminggu.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('94962e7f-517b-547d-8210-f079f72b7215', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa fokus bekerja siang ini?', '{"options":[{"id":"opt_1","text":"Karena ruang kerjanya terlalu dingin"},{"id":"opt_2","text":"Karena ia belum sempat makan siang"},{"id":"opt_3","text":"Karena komputernya berjalan sangat lambat"},{"id":"opt_4","text":"Karena rasa kantuk kuat yang mungkin akibat minum obat flu"}],"audio_text":"風邪薬を飲んだせいか、午後から急に強い眠気が出てきました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '風邪薬を飲んだせいか、強い眠気が出てきました berarti muncul rasa kantuk kuat yang mungkin karena obat flu.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e100505f-8646-555d-bd63-bfb274ab4cc6', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara salah lihat jam, saya ketinggalan kereta terakhir."', '{"romaji":"Jikan o mimachigaeta sei de, shuuden ni noriokuremashita.","tokens":["時間を","せいで、","終電に","見間違えて","乗り遅れました。","おかげで、","見間違えた"],"target_translation":"Gara-gara salah lihat jam, saya ketinggalan kereta terakhir."}'::jsonb, '["時間を","見間違えた","せいで、","終電に","乗り遅れました。"]'::jsonb, NULL, NULL, '終電に乗り遅れる berarti ketinggalan kereta terakhir.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a348cde-4cb5-5477-89b1-b440fc4f0b0c', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara topan, semua penerbangan dibatalkan."', '{"romaji":"Taifuu no sei de, subete no bin ga kekkou ni narimashita.","display_text":"台風のせいで、すべての便が欠航になりました。","phonetic_breakdown":["ta-i-fuu no","se-i de","su-be-te no bin ga","kek-kou ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"台風のせいで、すべての便が欠航になりました。"}'::jsonb, NULL, NULL, '便 (bin) berarti jadwal penerbangan. Kalimat ini sering terdengar di pengumuman bandara Jepang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a5bf0144-fde0-4a16-8fbf-362abfcc2365', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 花粉症の___、春になると毎日くしゃみが止まりません。', '{"options":["おかげで","せいで","に対して","うちに"],"translation":"Gara-gara alergi serbuk sari, begitu musim semi tiba bersin saya tidak berhenti setiap hari.","sentence_template":"花粉症の[blank]、春になると毎日くしゃみが止まりません。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, '花粉症 (kata benda) + のせいで.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('844a701c-7e9d-4220-b5ea-cf35270a9d5e', '5d57954e-ba71-59ea-99c5-be51c3364adc', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara membiarkan AC menyala terus, tagihan listrik jadi mahal."', '{"romaji":"Eakon o tsukeppanashi ni shita sei de, denkidai ga takaku narimashita.","display_text":"エアコンをつけっぱなしにしたせいで、電気代が高くなりました。","phonetic_breakdown":["e-a-kon-o","tsu-kep-pa-na-shi-ni","shi-ta","sei-de","den-ki-dai-ga","ta-ka-ku","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"エアコンをつけっぱなしにしたせいで、電気代が高くなりました。"}'::jsonb, NULL, NULL, 'したせいで menghubungkan kelalaian dengan dampak buruk.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4bcfc46f-d4d0-4cee-a1c9-7023b8902e80', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan ulasan restoran berikut. Apa keunggulan restoran ini?', '{"options":[{"id":"opt_1","text":"Pembicara kecewa dengan kualitas makanan di toko ini"},{"id":"opt_2","text":"Meski harganya terjangkau, porsi makanan di toko ini sangat banyak sehingga sangat memuaskan"},{"id":"opt_3","text":"Toko ini hanya menjual minuman dengan harga mahal"},{"id":"opt_4","text":"Harga makanan di toko ini sangat mahal dan porsinya sedikit"}],"audio_text":"この店の料理は値段が手頃なのに対して、量がとても多くて大満足です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '手頃なのに対して menunjukkan kontras positif antara harga murah dan porsi besar.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae9df411-db12-4935-b1a5-85c2dd912e49', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhadap pertanyaan apa pun, tolong jawablah dengan tenang."', '{"romaji":"Donna shitsumon ni taishite mo reisei ni kotaete kudasai.","display_text":"どんな質問に対しても冷静に答えてください。","phonetic_breakdown":["don-na","shi-tsu-mon-ni","tai-shi-te-mo","rei-sei-ni","ko-ta-e-te","ku-da-sai"]}'::jsonb, '{"expected_transcript":"どんな質問に対しても冷静に答えてください。"}'::jsonb, NULL, NULL, 'どんな～に対しても berarti ''terhadap ... apa pun''.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('529551e5-b9bf-4f51-a06b-064d561b67d6', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Berbeda dengan sikapnya yang keras pada diri sendiri, dia sangat baik kepada orang lain."', '{"romaji":"Kare wa jibun ni kibishii no ni taishite, tanin ni wa totemo yasashii desu.","tokens":["自分に","厳しいのに","他人には","優しいです。","対して、","おかげで、","とても","を","彼は"],"target_translation":"Berbeda dengan sikapnya yang keras pada diri sendiri, dia sangat baik kepada orang lain."}'::jsonb, '["彼は","自分に","厳しいのに","対して、","他人には","とても","優しいです。"]'::jsonb, NULL, NULL, '厳しいのに対して mengontraskan dua sisi kepribadian.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d327e18-e62a-42d0-b153-d4a67bec87b7', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: ボランティア活動に___関心が年々広がっています。', '{"options":["対する","よって","対して","ついて"],"translation":"Minat terhadap kegiatan sukarela semakin meluas dari tahun ke tahun.","sentence_template":"ボランティア活動に[blank]関心が年々広がっています。"}'::jsonb, '{"selected":"対する"}'::jsonb, NULL, NULL, 'Sebelum kata benda 関心, gunakan bentuk 対する.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1f4a197f-9dce-43dd-ad8b-084ea100bdea', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan komentar budaya berikut. Hal apa yang membuat wisatawan terkesan?', '{"options":[{"id":"opt_1","text":"Kereta di Jepang jarang datang tepat waktu"},{"id":"opt_2","text":"Wisatawan tidak diperbolehkan naik kereta di Jepang"},{"id":"opt_3","text":"Wisatawan mancanegara sering kagum terhadap ketepatan waktu kereta di Jepang"},{"id":"opt_4","text":"Wisatawan mancanegara sering mengeluhkan kereta Jepang yang lambat"}],"audio_text":"日本の電車は時間に正確なことに対して、海外からの観光客もよく驚きます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '正確なことに対して menunjukkan objek dari rasa takjub.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('88e64d06-9144-4158-beb2-fdd5e8e50ef9', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhadap pelanggaran aturan terdapat sanksi yang tegas."', '{"romaji":"Kisoku ihan ni taishite wa kibishii bassoku ga arimasu.","display_text":"規則違反に対しては厳しい罰則があります。","phonetic_breakdown":["ki-so-ku","i-han-ni","tai-shi-te-wa","ki-bi-shii","bas-so-ku-ga","a-ri-ma-su"]}'::jsonb, '{"expected_transcript":"規則違反に対しては厳しい罰則があります。"}'::jsonb, NULL, NULL, '違反に対しては menyoroti sasaran penerapan sanksi.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('069bfb38-ac3f-4dee-97ef-61bb71041f5c', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Berbeda dengan siang hari yang panas, pagi dan malam cukup sejuk."', '{"romaji":"Hiruma wa atsui no ni taishite, asaban wa kanari suzushii desu.","tokens":["暑いおかげで、","を","かなり","涼しいです。","朝晩は","暑いのに対して、","昼間は"],"target_translation":"Berbeda dengan siang hari yang panas, pagi dan malam cukup sejuk."}'::jsonb, '["昼間は","暑いのに対して、","朝晩は","かなり","涼しいです。"]'::jsonb, NULL, NULL, '暑いのに対して membandingkan suhu siang dan pagi/malam.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('48247d94-2f28-4d6d-9126-9d77c7f42511', '6033a5e5-a6a5-4458-929d-2e6354c4a8e0', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: これまでのご支援に___、心より感謝申し上げます。', '{"options":["うちに","ばかり","対して","せいで"],"translation":"Terhadap dukungan Anda selama ini, kami mengucapkan terima kasih setulus hati.","sentence_template":"これまでのご支援に[blank]、心より感謝申し上げます。"}'::jsonb, '{"selected":"対して"}'::jsonb, NULL, NULL, 'ご支援に対して adalah ungkapan formal yang sangat sopan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a59d99e2-4547-5fe7-a4d1-82e7003ffa95', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas dukungan Anda terhadap proyek kami."', '{"romaji":"Heisha no kikaku ni taisuru goshien, arigatou gozaimasu.","display_text":"弊社の企画に対するご支援、ありがとうございます。","phonetic_breakdown":["he-i-sha no","ki-ka-ku ni","ta-i-su-ru","go-shi-en","a-ri-ga-tou","go-za-i-ma-su"]}'::jsonb, '{"expected_transcript":"弊社の企画に対するご支援、ありがとうございます。"}'::jsonb, NULL, NULL, '弊社 (heisha) adalah sebutan rendah hati untuk perusahaan sendiri dalam bisnis Jepang.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b1fbf6e-5286-5998-9e88-85ee560acd5d', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berbeda dengan kota yang ramai, desa itu tenang."', '{"romaji":"Tokai ga nigiyakana no ni taishite, sono mura wa shizuka desu.","display_text":"都会がにぎやかなのに対して、その村は静かです。","phonetic_breakdown":["to-ka-i ga","ni-gi-ya-ka-na no ni","ta-i-shi-te","so-no mu-ra wa","shi-zu-ka de-su"]}'::jsonb, '{"expected_transcript":"都会がにぎやかなのに対して、その村は静かです。"}'::jsonb, NULL, NULL, 'Perhatikan adjektiva-NA にぎやか memakai な sebelum のに対して.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a7b18fc-8453-511e-bbef-f6af126af708', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya bertanggung jawab terhadap pekerjaan saya."', '{"romaji":"Jibun no shigoto ni taishite sekinin o motte imasu.","display_text":"自分の仕事に対して責任を持っています。","phonetic_breakdown":["ji-bun no","shi-go-to ni","ta-i-shi-te","se-ki-nin o","mot-te i-ma-su"]}'::jsonb, '{"expected_transcript":"自分の仕事に対して責任を持っています。"}'::jsonb, NULL, NULL, '責任を持つ (sekinin o motsu) berarti memiliki rasa tanggung jawab.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('06781cd1-877a-59e9-b86b-df9a08818bcc', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Beliau selalu bersikap ramah kepada siapa pun."', '{"romaji":"Ano hito wa dare ni taishite mo shinsetsu desu.","tokens":["対する","親切です。","よって","対しても","誰に","あの人は"],"target_translation":"Beliau selalu bersikap ramah kepada siapa pun."}'::jsonb, '["あの人は","誰に","対しても","親切です。"]'::jsonb, NULL, NULL, '誰に対しても berarti ''terhadap siapa pun''.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00628a27-4d4a-507d-915a-4a45de56f201', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Berbeda dengan tahun lalu yang sedikit hujan, tahun ini banyak hujan."', '{"romaji":"Kyonen wa ame ga sukunakatta no ni taishite, kotoshi wa ooi desu.","tokens":["去年は","今年は","対して、","多いです。","少なくて","おかげで、","雨が少なかったのに"],"target_translation":"Berbeda dengan tahun lalu yang sedikit hujan, tahun ini banyak hujan."}'::jsonb, '["去年は","雨が少なかったのに","対して、","今年は","多いです。"]'::jsonb, NULL, NULL, '少なかったのに + 対して mengontraskan kondisi curah hujan dua tahun.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce226a32-2a09-51c8-bf30-c44a3de5e5c8', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Saya memiliki minat terhadap teknologi terbaru."', '{"romaji":"Saishin no gijutsu ni taisuru kyoumi ga arimasu.","tokens":["興味が","対して","最新の技術に","対する","あります。","せいで"],"target_translation":"Saya memiliki minat terhadap teknologi terbaru."}'::jsonb, '["最新の技術に","対する","興味が","あります。"]'::jsonb, NULL, NULL, 'Karena menerangkan nomina 興味 (minat), gunakan に対する.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ab0d92bf-0aab-4d2d-9064-815ac0ddbfc9', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhadap orang yang lebih tua/atasan, seharusnya menggunakan bahasa yang sopan."', '{"romaji":"Meue no hito ni taishite wa, teinei na kotoba o tsukau beki desu.","display_text":"目上の人に対しては、丁寧な言葉を使うべきです。","phonetic_breakdown":["me-u-e-no","hi-to-ni","tai-shi-te-wa","tei-nei-na","ko-to-ba-o","tsu-ka-u-be-ki-de-su"]}'::jsonb, '{"expected_transcript":"目上の人に対しては、丁寧な言葉を使うべきです。"}'::jsonb, NULL, NULL, '目上の人に対しては menekankan sasaran sikap kesopanan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('298dbe4a-0cc7-4f5c-afef-64336d0ff1d3', '6209c5ba-aa6b-5c1c-9ce4-4280ee1d02e2', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Terhadap pendapat kepala bagian, saya mengusulkan alternatif lain."', '{"romaji":"Buchou no iken ni taishite, betsu no an o teian shimashita.","tokens":["意見に","別の","せいで、","部長の","が","対して、","提案しました。","案を"],"target_translation":"Terhadap pendapat kepala bagian, saya mengusulkan alternatif lain."}'::jsonb, '["部長の","意見に","対して、","別の","案を","提案しました。"]'::jsonb, NULL, NULL, '意見に対して menandai objek tanggapan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('83f39e23-3e63-4b07-be81-e791707b5079', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 新しい美術館は来年の春に___予定です。', '{"options":["完成し","完成させて","完成される","完成して"],"translation":"Museum seni baru dijadwalkan selesai dibangun musim semi tahun depan.","sentence_template":"新しい美術館は来年の春に[blank]予定です。"}'::jsonb, '{"selected":"完成される"}'::jsonb, NULL, NULL, '完成される menyoroti gedung sebagai subjek berita resmi.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efca5511-a298-4830-baef-25300ad4156f', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 夜中に隣の部屋の人に大声で___、よく眠れませんでした。', '{"options":["騒がせて","騒いで","騒ぎ","騒がれて"],"translation":"Tengah malam terganggu oleh orang kamar sebelah yang ribut, sehingga tidak bisa tidur nyenyak.","sentence_template":"夜中に隣の部屋の人に大声で[blank]、よく眠れませんでした。"}'::jsonb, '{"selected":"騒がれて"}'::jsonb, NULL, NULL, '騒ぐ (kelompok 1) -> bentuk pasif 騒がれる (terganggu oleh keributan orang lain).', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1efa5080-9a73-4d53-b5bc-b9e6ff6654a0', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan berita lokal berikut. Kegiatan apa yang akan diadakan?', '{"options":[{"id":"opt_1","text":"Wilayah ini baru saja mengalami bencana alam"},{"id":"opt_2","text":"Musim gugur tahun ini diputuskan akan diadakan latihan mitigasi bencana skala besar di wilayah ini"},{"id":"opt_3","text":"Latihan mitigasi bencana tahun ini dibatalkan"},{"id":"opt_4","text":"Latihan mitigasi bencana hanya untuk petugas pemadam"}],"audio_text":"今年の秋、この地域で大規模な防災訓練が行われることになりました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '行われる (okonawareru) adalah bentuk pasif dari 行う yang sangat umum dalam berita.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67706743-757f-4be2-be60-fe2aee6b553e', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Dompet saya dicuri oleh pencopet sehingga saya kesulitan."', '{"romaji":"Saifu o suri ni nusumarete komatte imasu.","tokens":["盗まれて","困って","います。","すりに","盗んで","が","財布を"],"target_translation":"Dompet saya dicuri oleh pencopet sehingga saya kesulitan."}'::jsonb, '["財布を","すりに","盗まれて","困って","います。"]'::jsonb, NULL, NULL, '盗む -> 盗まれる (dicuri).', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fb723e7d-a598-40f4-b8f8-4e5871226f6f', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このお城は江戸時代に___ました。', '{"options":["建ち","建てられ","建て","建てさせ"],"translation":"Kastel ini dibangun pada zaman Edo.","sentence_template":"このお城は江戸時代に[blank]ました。"}'::jsonb, '{"selected":"建てられ"}'::jsonb, NULL, NULL, '建てる (kelompok 2) -> 建てられる (dibangun).', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0162afca-0f65-4df8-bb6e-332d63466908', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya dibantu dengan ramah oleh senior dan bahkan mendapat ucapan terima kasih juga."', '{"romaji":"Senpai ni shinsetsu ni tasukete moratte, sara ni kansha saremashita.","display_text":"先輩に親切に助けてもらって、さらに感謝されました。","phonetic_breakdown":["sen-pai-ni","shin-se-tsu-ni","ta-su-ke-te-mo-rat-te","sa-ra-ni","kan-sha-sa-re-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先輩に親切に助けてもらって、さらに感謝されました。"}'::jsonb, NULL, NULL, '感謝する -> 感謝される (diberi terima kasih).', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d33f05c-ac9d-4833-8d8c-7c353b818494', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan cerita wawancara kerja berikut. Bagaimana jalannya wawancara?', '{"options":[{"id":"opt_1","text":"Pewawancara tidak menanyakan alasan melamar"},{"id":"opt_2","text":"Wawancara dibatalkan sebelum dimulai"},{"id":"opt_3","text":"Ditanyai secara rinci tentang alasan melamar oleh pewawancara, namun bisa menjawab dengan tenang"},{"id":"opt_4","text":"Pembicara tidak bisa menjawab pertanyaan pewawancara"}],"audio_text":"面接官に志望動機を詳しく聞かれましたが、落ち着いて答えられました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '聞かれる adalah bentuk pasif dari 聞く (ditanyai).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ead5d485-1a54-41a7-81af-d08a99a0d8ee', '631c5962-c03c-43a0-b85f-7f082e6ce524', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Dokumen penting saya tergigit oleh anjing."', '{"romaji":"Daiji na shorui o inu ni kamarete shimaimashita.","tokens":["書類を","噛んで","大事な","犬に","噛まれて","が","しまいました。"],"target_translation":"Dokumen penting saya tergigit oleh anjing."}'::jsonb, '["大事な","書類を","犬に","噛まれて","しまいました。"]'::jsonb, NULL, NULL, '噛む -> 噛まれる (digigit).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fb5aabfa-c33e-5391-84cd-717131187e67', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat manajemen waktu: 提出の ___ を守って書類を出しましょう。', '{"options":["締め切り","始まり","見送り","割り引き"],"translation":"Mari kumpulkan dokumen dengan mematuhi batas waktu pengumpulan.","sentence_template":"提出の [blank] を守って書類を出しましょう。"}'::jsonb, '{"selected":"締め切り"}'::jsonb, NULL, NULL, '締め切り (shimekiri) berarti tenggat atau batas waktu pengumpulan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a351886-9705-5703-9142-230ca459d8bb', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'reading', 'fill_blank', 'Pilih kata untuk kesempatan: せっかくの ___ ですから、ぜひ参加してください。', '{"options":["機会","機械","器械","境界"],"translation":"Karena ini kesempatan berharga, silakan ikut berpartisipasi.","sentence_template":"せっかくの [blank] ですから、ぜひ参加してください。"}'::jsonb, '{"selected":"機会"}'::jsonb, NULL, NULL, '機会 (kikai) berarti kesempatan/peluang. 機械 berarti mesin.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('80dcfc75-4d91-53a2-9544-16bc15f5cad1', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang cuaca sore: 夕方になると急に空が ___ なります。', '{"options":["暗く","軽く","丸く","細く"],"translation":"Saat menjelang sore, langit tiba-tiba menjadi gelap.","sentence_template":"夕方になると急に空が [blank] なります。"}'::jsonb, '{"selected":"暗く"}'::jsonb, NULL, NULL, '暗くなる (kuraku naru) berarti menjadi gelap.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0e06e6bf-865a-548d-b61e-258b74f85f2d', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk ingatan: 授業の内容は ___ が新しいうちにまとめます。', '{"options":["記憶","記録","記念","気温"],"translation":"Isi pelajaran saya rangkum selagi ingatan masih segar.","sentence_template":"授業の内容は [blank] が新しいうちにまとめます。"}'::jsonb, '{"selected":"記憶"}'::jsonb, NULL, NULL, '記憶が新しい (kioku ga atarashii) berarti ingatan masih segar.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('061fe02c-bc23-51ce-ae58-daff7b9343cf', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'listening', 'listening_choice', 'Kapan pembicara menyarankan untuk pergi ke supermarket?', '{"options":[{"id":"opt_1","text":"Siang hari selagi masih sepi"},{"id":"opt_2","text":"Sore hari saat diskon makanan dimulai"},{"id":"opt_3","text":"Malam hari sebelum toko tutup"},{"id":"opt_4","text":"Pagi-pagi sekali sebelum berangkat kerja"}],"audio_text":"夕方はレジがすごく混むので、空いている昼間のうちに買い物を済ませたほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '空いている昼間のうちに berarti pada siang hari selagi sepi.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('33e23d7c-ede4-52b4-b44e-13936bc52a60', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', NULL, 'listening', 'listening_choice', 'Mengapa pembicara ingin bepergian keliling Jepang tahun ini?', '{"options":[{"id":"opt_1","text":"Karena tiket kereta sedang gratis bulan ini"},{"id":"opt_2","text":"Karena ingin mengunjungi banyak daerah selama masih tinggal di Jepang"},{"id":"opt_3","text":"Karena mendapat tugas dinas ke seluruh prefektur"},{"id":"opt_4","text":"Karena orang tuanya akan datang berkunjung minggu depan"}],"audio_text":"日本に住んでいる間に、できるだけ多くの地方を訪れておきたいと思っています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '日本に住んでいる間に、できるだけ多くの地方を訪れておきたい berarti ingin mengunjungi banyak daerah selama tinggal di Jepang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4207bec-3c86-4069-92e3-64b2061fb541', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 記憶がまだ___うちに、会議の要点をメモしておきましょう。', '{"options":["遠い","新しい","古い","重い"],"translation":"Mumpung ingatan masih segar, mari kita catat poin-poin penting rapat.","sentence_template":"記憶がまだ[blank]うちに、会議の要点をメモしておきましょう。"}'::jsonb, '{"selected":"新しい"}'::jsonb, NULL, NULL, '記憶が新しいうちに berarti ''mumpung ingatan masih segar/baru''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b97d32e-e843-45e0-b9b8-040cb14f004b', '63ae0fc4-822c-5680-b9b6-2019a60e3d3e', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan ucapan pelayan restoran berikut. Apa yang dianjurkan?', '{"options":[{"id":"opt_1","text":"Mengabarkan bahwa sup baru akan dimasak nanti"},{"id":"opt_2","text":"Menyilakan tamu menyantap sup selagi masih hangat"},{"id":"opt_3","text":"Menanyakan apakah tamu ingin mengganti sup dengan teh"},{"id":"opt_4","text":"Meminta tamu menunggu sampai supnya dingin"}],"audio_text":"温かいうちに、どうぞこちらのスープをお召し上がりください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '温かいうちに berarti ''mumpung masih hangat'' sebelum suhunya berubah.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a1aae16-ea68-51f7-bc45-486209f9e37a', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi pengumuman penugasan: 来月、福岡へ出張 ___ ことになりました。', '{"options":["する","した","して","します"],"translation":"Diputuskan bahwa bulan depan saya akan dinas ke Fukuoka.","sentence_template":"来月、福岡へ出張 [blank] ことになりました。"}'::jsonb, '{"selected":"する"}'::jsonb, NULL, NULL, 'Pola ～ことになる memakai bentuk kamus (出張する) atau bentuk-NAI sebelum ことになりました.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0828e622-2708-535d-8958-136dc174c676', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Pilih bentuk aturan kantor: この会議室では飲食 ___ ことになっています。', '{"options":["しない","した","して","せず"],"translation":"Di ruang rapat ini aturannya tidak boleh makan dan minum.","sentence_template":"この会議室では飲食 [blank] ことになっています。"}'::jsonb, '{"selected":"しない"}'::jsonb, NULL, NULL, 'Bentuk-NAI + ことになっている menyatakan aturan atau ketetapan yang melarang sesuatu.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('63d48151-82f3-5e5b-ac5d-dec53187afd5', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi jadwal rutin: 毎週月曜日に進捗報告を ___ ことになっています。', '{"options":["提出する","提出した","提出して","提出します"],"translation":"Setiap hari Senin dijadwalkan untuk menyerahkan laporan progres.","sentence_template":"毎週月曜日に進捗報告を [blank] ことになっています。"}'::jsonb, '{"selected":"提出する"}'::jsonb, NULL, NULL, '～ことになっています menyatakan jadwal atau prosedur tetap organisasi; verba sebelumnya berbentuk kamus.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fecf421e-795b-5ba4-abb6-ba26365a012d', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa rapat besok dilaksanakan secara daring."', '{"romaji":"Ashita no kaigi wa onrain de okonau koto ni narimashita.","tokens":["明日の会議は","しました。","オンラインで","行う","ことに","行った","なりました。"],"target_translation":"Diputuskan bahwa rapat besok dilaksanakan secara daring."}'::jsonb, '["明日の会議は","オンラインで","行う","ことに","なりました。"]'::jsonb, NULL, NULL, '行う (melaksanakan) + ことになりました menandakan keputusan resmi pihak kantor/panitia.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4dd8f2af-e612-557d-87d3-c99f95b37e42', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Aturannya kita wajib memakai kartu pegawai di dalam gedung."', '{"romaji":"Tatemono no naka de wa shainshou o tsukeru koto ni natte imasu.","tokens":["しています。","つけた","ことに","つける","なっています。","建物の中では","社員証を"],"target_translation":"Aturannya kita wajib memakai kartu pegawai di dalam gedung."}'::jsonb, '["建物の中では","社員証を","つける","ことに","なっています。"]'::jsonb, NULL, NULL, '～ことになっています digunakan untuk menjelaskan aturan yang berlaku umum.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b06b1d3-edac-5019-aa62-a75ff72fa0ef', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Keputusan apa yang baru diterima pembicara?', '{"options":[{"id":"opt_1","text":"Ia diminta pindah ke divisi pemasaran"},{"id":"opt_2","text":"Ia dibebaskan dari tugas lembur minggu depan"},{"id":"opt_3","text":"Ia dipercaya menjadi ketua tim baru mulai minggu depan"},{"id":"opt_4","text":"Ia harus mengikuti pelatihan di luar negeri"}],"audio_text":"急な話ですが、来週から新しいチームのリーダーを任されることになりました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '新しいチームのリーダーを任されることになりました berarti diputuskan bahwa ia dipercaya menjadi pemimpin tim baru.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f73133ba-58d6-4f3f-9540-10112f26da8d', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 来週の月曜日に新しいシステムが導入される___。', '{"options":["ことにしました","ことになりました","ようになりました","はずがありません"],"translation":"Diputuskan bahwa sistem baru akan mulai diterapkan hari Senin minggu depan.","sentence_template":"来週の月曜日に新しいシステムが導入される[blank]。"}'::jsonb, '{"selected":"ことになりました"}'::jsonb, NULL, NULL, '～ことになりました menyatakan keputusan yang ditetapkan oleh pihak luar, rapat, atau keadaan (bukan sekadar kemauan pribadi).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9eee6c03-efb9-495a-a6c7-407d3b67fd42', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Di gedung ini aturannya pada malam hari keluar melalui pintu belakang."', '{"romaji":"Kono biru de wa yakan wa uraguchi kara deru koto ni natte imasu.","tokens":["夜間は","ビルでは","出た","裏口から","出る","この","を","なっています。","ことに"],"target_translation":"Di gedung ini aturannya pada malam hari keluar melalui pintu belakang."}'::jsonb, '["この","ビルでは","夜間は","裏口から","出る","ことに","なっています。"]'::jsonb, NULL, NULL, '～ことになっています menyatakan aturan, jadwal tetap, atau ketentuan yang berlaku.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4bfe6964-5f1a-5e23-8ff0-0ee78f3bc72d', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Ubah 選ぶ (memilih) ke bentuk pasif: 彼女がチームの代表に ___ ました。', '{"options":["選ばれ","選び","選ばせ","選んで"],"translation":"Dia terpilih sebagai perwakilan tim.","sentence_template":"彼女がチームの代表に [blank] ました。"}'::jsonb, '{"selected":"選ばれ"}'::jsonb, NULL, NULL, '選ぶ (Golongan I) -> 選ばれる (dipilih/terpilih).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('519dd71b-35be-5fcc-a0b0-91f762040398', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Pilih bentuk pasif yang tepat: 駅で外国人に道を ___ ました。', '{"options":["聞かれ","聞き","聞かせ","聞いて"],"translation":"Di stasiun saya ditanya arah jalan oleh orang asing.","sentence_template":"駅で外国人に道を [blank] ました。"}'::jsonb, '{"selected":"聞かれ"}'::jsonb, NULL, NULL, '聞く (bertanya) -> 聞かれる (ditanya).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20430138-6e2e-54d0-b0a2-4db042a60686', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Apa yang terjadi pada gedung lama di dekat stasiun?', '{"options":[{"id":"opt_1","text":"Akan dijadikan museum sejarah kota"},{"id":"opt_2","text":"Akan dijual kepada perusahaan asing"},{"id":"opt_3","text":"Akan dirobohkan bulan depan dan diganti fasilitas komersial baru"},{"id":"opt_4","text":"Akan ditutup sementara untuk pengecatan ulang"}],"audio_text":"駅前の古いビルは来月取り壊され、新しく商業施設が建てられる予定です。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '取り壊され (dirobohkan) dan 新しく商業施設が建てられる (akan dibangun fasilitas komersial baru).', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('91a2adc8-74f9-560e-b41e-7dd4d920a91e', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Mengapa pembicara kurang tidur semalam?', '{"options":[{"id":"opt_1","text":"Karena ia harus menyelesaikan laporan sampai pagi"},{"id":"opt_2","text":"Karena kucing peliharaannya terus mengeong"},{"id":"opt_3","text":"Karena jendela kamarnya rusak tertiup angin"},{"id":"opt_4","text":"Karena kamar sebelah memutar musik keras di tengah malam"}],"audio_text":"夜中に隣の部屋で大きな音楽をかけられて、ぜんぜん眠れませんでした。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '大きな音楽をかけられて adalah pasif penderitaan: terganggu karena tetangga memutar musik keras.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e893fb12-807a-5203-bcf3-38ed868a5d13', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Usulan saya diterima dengan baik oleh manajer."', '{"romaji":"Watashi no teian wa kachou ni mitomeraremashita.","tokens":["課長に","認められました。","課長を","認めました。","私の提案は"],"target_translation":"Usulan saya diterima dengan baik oleh manajer."}'::jsonb, '["私の提案は","課長に","認められました。"]'::jsonb, NULL, NULL, '認める (mengakui/menerima) -> 認められました (diakui/diterima).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac7d7521-adc3-5a41-af08-c9c4a7b26767', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bahasa Jepang dipelajari oleh banyak orang."', '{"romaji":"Nihongo wa ooku no hito ni manabarete imasu.","display_text":"日本語は多くの人に学ばれています。","phonetic_breakdown":["ni-hon-go wa","oo-ku no hi-to ni","ma-na-ba-re-te","i-ma-su"]}'::jsonb, '{"expected_transcript":"日本語は多くの人に学ばれています。"}'::jsonb, NULL, NULL, '学ぶ (manabu = belajar) berubah menjadi 学ばれる (dipelajari).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f403063-e50f-4e09-b6b8-8365d28ade5a', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この小説は二十以上の言語に___います。', '{"options":["翻訳して","翻訳でき","翻訳されて","翻訳させて"],"translation":"Novel ini telah diterjemahkan ke lebih dari dua puluh bahasa.","sentence_template":"この小説は二十以上の言語に[blank]います。"}'::jsonb, '{"selected":"翻訳されて"}'::jsonb, NULL, NULL, '翻訳する -> bentuk pasif 翻訳される (diterjemahkan).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8c3d5993-e35a-45ee-84b8-161ba9d891b2', '6bac56d7-df94-5c98-a050-d6344df8763a', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya diberi pertanyaan penting di rapat sehingga sedikit gugup."', '{"romaji":"Kaigi de juuyou na shitsumon o sarete, sukoshi kinchou shimashita.","display_text":"会議で重要な質問をされて、少し緊張しました。","phonetic_breakdown":["kai-gi-de","juu-you-na","shi-tsu-mon-o","sa-re-te","su-ko-shi","kin-chou-shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"会議で重要な質問をされて、少し緊張しました。"}'::jsonb, NULL, NULL, '質問をする -> bentuk pasif 質問をされる (ditanyai).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0dc65a1-2857-5504-bd4e-aefe57f8c478', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'listening', 'listening_choice', 'Bagaimana kebijakan baru perusahaan diumumkan?', '{"options":[{"id":"opt_1","text":"Dikirim melalui surat pos ke rumah masing-masing pegawai"},{"id":"opt_2","text":"Ditempel di papan pengumuman kantin saja"},{"id":"opt_3","text":"Akan dibahas ulang pada rapat bulan depan"},{"id":"opt_4","text":"Diumumkan secara resmi pada rapat seluruh perusahaan kemarin"}],"audio_text":"新しい勤務ルールは、昨日の全社ミーティングで正式に発表されました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '昨日の全社ミーティングで正式に発表されました berarti diumumkan resmi di rapat seluruh perusahaan kemarin.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('65aa531c-a78b-5de7-8f02-ad2ad7e55102', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa kesal di bioskop kemarin?', '{"options":[{"id":"opt_1","text":"Kursinya berkali-kali ditendang oleh orang di belakangnya"},{"id":"opt_2","text":"Orang di sampingnya terus berbicara lewat telepon"},{"id":"opt_3","text":"Layar bioskop sempat mati di tengah film"},{"id":"opt_4","text":"Tempat duduknya ditempati oleh penonton lain"}],"audio_text":"映画を見ている間、後ろの人に何度も椅子を蹴られて集中できませんでした。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '後ろの人に何度も椅子を蹴られて berarti kursinya berkali-kali ditendang orang di belakang.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a477fb85-d7c3-58a6-aa22-06942e95240b', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'listening', 'listening_choice', 'Apa yang terjadi pada usulan yang diajukan tim pembicara?', '{"options":[{"id":"opt_1","text":"Ditolak karena melebihi anggaran"},{"id":"opt_2","text":"Disetujui di rapat direksi dan akan dijalankan mulai bulan depan"},{"id":"opt_3","text":"Diminta untuk direvisi kembali selama dua minggu"},{"id":"opt_4","text":"Digabungkan dengan proyek dari cabang lain"}],"audio_text":"先月提出した企画案が役員会議で承認され、来月から実行に移されます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '役員会議で承認され (disetujui di rapat direksi) dan 実行に移されます (dijalankan).', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ecb4b2ff-4046-5d04-afdb-fbe8edcf4ee1', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'reading', 'fill_blank', 'Pilih bentuk pasif dari 使う (memakai): この言葉はビジネスシーンでよく ___ ています。', '{"options":["使われ","使い","使わせ","使って"],"translation":"Kata ini sering digunakan dalam situasi bisnis.","sentence_template":"この言葉はビジネスシーンでよく [blank] ています。"}'::jsonb, '{"selected":"使われ"}'::jsonb, NULL, NULL, 'Verba Golongan I berakhiran う (使う) berubah menjadi わ + れる -> 使われる.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c150ce8f-505e-5eee-b0fc-1f57aa44670f', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'reading', 'fill_blank', 'Pilih partikel pelaku pasif karya: この小説は有名な作家 ___ 書かれました。', '{"options":["によって","について","にとって","に対して"],"translation":"Novel ini ditulis oleh penulis terkenal.","sentence_template":"この小説は有名な作家 [blank] 書かれました。"}'::jsonb, '{"selected":"によって"}'::jsonb, NULL, NULL, 'Untuk pencipta karya/penemuan dalam kalimat pasif, gunakan によって sebagai penanda pelaku.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('497fd7d4-1f86-5095-b506-85381d4240fc', '6bf68045-dff9-56f4-8298-d0dd413b90b6', NULL, 'reading', 'fill_blank', 'Lengkapi pasif penderitaan: 弟に大切なパソコンを ___ てしまいました。', '{"options":["壊され","壊し","壊させ","壊れ"],"translation":"Komputer penting saya dirusak oleh adik laki-laki.","sentence_template":"弟に大切なパソコンを [blank] てしまいました。"}'::jsonb, '{"selected":"壊され"}'::jsonb, NULL, NULL, '壊す (merusak) -> pasif 壊される (dirusak).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31660a5b-bb14-4755-93af-25e7a89f2501', '6bf68045-dff9-56f4-8298-d0dd413b90b6', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan pengalaman berikut. Apa yang menimpa pembicara?', '{"options":[{"id":"opt_1","text":"Hujan turun setelah pembicara tiba di rumah"},{"id":"opt_2","text":"Cuaca sangat cerah sepanjang perjalanan pulang"},{"id":"opt_3","text":"Kehujanan mendadak di jalan pulang dari stasiun sampai pakaian basah kuyup"},{"id":"opt_4","text":"Pembicara membawa jas hujan sehingga tidak basah"}],"audio_text":"駅からの帰り道で急に雨に降られて、服がびしょ濡れになってしまいました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '雨に降られる adalah bentuk pasif penderitaan khas Jepang yang berarti ''kehujanan''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70906ade-c764-4ed2-8d2e-ca787b8e46de', '6bf68045-dff9-56f4-8298-d0dd413b90b6', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 来月、この公園で国際交流イベントが___ます。', '{"options":["開き","開かせ","開かれ","開け"],"translation":"Bulan depan acara pertukaran internasional akan diselenggarakan di taman ini.","sentence_template":"来月、この公園で国際交流イベントが[blank]ます。"}'::jsonb, '{"selected":"開かれ"}'::jsonb, NULL, NULL, '開く (kelompok 1) -> bentuk pasif 開かれる (diselenggarakan).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55b20e1d-d75e-4c82-b869-edd79d37db62', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan curhatan kerja berikut. Apa yang terjadi pada pembicara?', '{"options":[{"id":"opt_1","text":"Rapat dimulai lebih lambat karena menunggu pembicara"},{"id":"opt_2","text":"Atasan yang terlambat masuk rapat hari ini"},{"id":"opt_3","text":"Atasan memuji kedisiplinan pembicara"},{"id":"opt_4","text":"Terlambat masuk rapat dan ditegur keras oleh atasan"}],"audio_text":"会議に遅刻してしまい、上司に厳しく注意されました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '注意される berarti ditegur atau diperingatkan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b05a0ac-eca8-406f-936b-c4a693f2ba6d', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Lagu ini sampai sekarang pun masih dinyanyikan oleh banyak orang."', '{"romaji":"Kono uta wa ima demo ooku no hito ni utawarete imasu.","display_text":"この歌は今でも多くの人に歌われています。","phonetic_breakdown":["ko-no","u-ta-wa","i-ma-de-mo","oo-ku-no","hi-to-ni","u-ta-wa-re-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"この歌は今でも多くの人に歌われています。"}'::jsonb, NULL, NULL, '歌う -> 歌われる (dinyanyikan).', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ad3399f-6f22-4949-bfec-3a479442108d', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Kursi saya ditendang oleh orang di kursi belakang."', '{"romaji":"Ushiro no seki no hito ni isu o keraremashita.","tokens":["後ろの","席の","人に","椅子を","蹴りました。","蹴られました。","が"],"target_translation":"Kursi saya ditendang oleh orang di kursi belakang."}'::jsonb, '["後ろの","席の","人に","椅子を","蹴られました。"]'::jsonb, NULL, NULL, '蹴る (keru, menendang) -> 蹴られる (ditendang).', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82029490-8fdf-4119-a33d-b6dd09568084', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 日本のアニメは世界中で高く___います。', '{"options":["評価して","評価させて","評価されて","評価でき"],"translation":"Anime Jepang dinilai sangat tinggi di seluruh dunia.","sentence_template":"日本のアニメは世界中で高く[blank]います。"}'::jsonb, '{"selected":"評価されて"}'::jsonb, NULL, NULL, '評価する -> 評価されている (dinilai/diapresiasi).', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('16e7decd-04b5-46a0-a1ef-e7435cda900c', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan cerita berikut. Apa yang terjadi di jalan?', '{"options":[{"id":"opt_1","text":"Ditanyai arah dalam bahasa Inggris oleh orang tak dikenal di jalan lalu membantu dengan gestur"},{"id":"opt_2","text":"Pembicara tidak mengerti sama sekali tujuan orang tersebut"},{"id":"opt_3","text":"Orang asing itu menolak bantuan pembicara"},{"id":"opt_4","text":"Pembicara bertanya arah kepada polisi di jalan"}],"audio_text":"道で知らない人に英語で道を聞かれたので、身振り手振りで案内しました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '道を聞かれる berarti ditanyai arah.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d01445df-f2d6-45f5-83cb-180c77451b1e', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di hari penting, janji saya dibatalkan oleh teman sehingga saya kecewa."', '{"romaji":"Daiji na hi ni tomodachi ni yakusoku o kyanseru sarete gakkari shimashita.","display_text":"大事な日に友達に約束をキャンセルされてがっかりしました。","phonetic_breakdown":["dai-ji-na","hi-ni","to-mo-da-chi-ni","ya-ku-so-ku-o","kyan-se-ru-sa-re-te","gak-ka-ri-shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"大事な日に友達に約束をキャンセルされてがっかりしました。"}'::jsonb, NULL, NULL, 'キャンセルされる adalah bentuk pasif yang mengungkapkan kekecewaan.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('04c6bf71-548d-47ea-ae05-3545870d8a54', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Jembatan ini dijaga dengan baik oleh warga setempat."', '{"romaji":"Kono hashi wa chiiki juumin ni taisetsu ni mamorarete imasu.","tokens":["地域住民に","守って","この","守られて","を","います。","橋は","大切に"],"target_translation":"Jembatan ini dijaga dengan baik oleh warga setempat."}'::jsonb, '["この","橋は","地域住民に","大切に","守られて","います。"]'::jsonb, NULL, NULL, '守る -> 守られる (dijaga).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('511db298-685d-49f5-bf6d-b93e4d303254', '717449e7-200e-4dbe-84fb-f246aaca53bf', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 来週の会議では新しい規則について___予定です。', '{"options":["議論でき","議論して","議論させて","議論される"],"translation":"Pada rapat minggu depan dijadwalkan akan dibahas mengenai peraturan baru.","sentence_template":"来週の会議では新しい規則について[blank]予定です。"}'::jsonb, '{"selected":"議論される"}'::jsonb, NULL, NULL, '議論する -> 議論される (didiskusikan/dibahas).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40f871bf-6c9a-590d-b57f-ac60c45c32f4', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'listening', 'listening_choice', 'Mengapa pembicara belum bisa mengemudi dengan lancar?', '{"options":[{"id":"opt_1","text":"Karena mobilnya sedang diperbaiki di bengkel"},{"id":"opt_2","text":"Karena rambu lalu lintas di daerahnya sedang diganti"},{"id":"opt_3","text":"Karena jalan tol sedang ditutup akibat salju"},{"id":"opt_4","text":"Karena ia baru saja mendapatkan SIM bulan lalu"}],"audio_text":"先月運転免許を取ったばかりなので、まだ高速道路を走るのは怖いです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '先月運転免許を取ったばかりなので berarti karena baru saja memperoleh SIM bulan lalu.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9bd4a43b-b917-5b73-a205-4cd383d1f764', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'listening', 'listening_choice', 'Apa yang membuat pembicara merasa kecewa dengan ponselnya?', '{"options":[{"id":"opt_1","text":"Ponsel yang baru dibelinya minggu lalu jatuh dan layarnya retak"},{"id":"opt_2","text":"Baterai ponsel barunya cepat habis dalam dua jam"},{"id":"opt_3","text":"Ponsel barunya tertinggal di kereta pulang"},{"id":"opt_4","text":"Toko salah mengirimkan warna ponsel yang dipesan"}],"audio_text":"先週買ったばかりのスマホを落として、画面にひびが入ってしまいました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '先週買ったばかりのスマホを落として、画面にひびが入ってしまいました berarti menjatuhkan ponsel baru dan layarnya retak.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('60cf7427-3b5d-5033-a0d5-8f52f9f6cc70', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'listening', 'listening_choice', 'Bagaimana kondisi proyek yang sedang ditangani pembicara?', '{"options":[{"id":"opt_1","text":"Proyeknya sudah hampir selesai minggu ini"},{"id":"opt_2","text":"Proyeknya baru saja dimulai, namun suasana timnya sangat baik"},{"id":"opt_3","text":"Proyeknya terpaksa ditunda karena kekurangan anggota"},{"id":"opt_4","text":"Proyeknya baru saja berganti pimpinan tim"}],"audio_text":"このプロジェクトはまだ始まったばかりですが、チームの雰囲気はとてもいいです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'まだ始まったばかりですが berarti ''meskipun baru saja dimulai''.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('938af993-af48-5707-8d98-bb3efa6a7bcd', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼は去年結婚した ___ なのに、もう海外へ転勤になりました。', '{"options":["ばかり","はず","おかげ","せい"],"translation":"Padahal dia baru saja menikah tahun lalu, sudah dipindahtugaskan ke luar negeri.","sentence_template":"彼は去年結婚した [blank] なのに、もう海外へ転勤になりました。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '～たばかり bersifat subjektif: meski sudah setahun lalu, pembicara merasa kejadian itu masih sangat baru.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('046dd89b-98fc-5b1b-b30e-6be32fe321e5', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'reading', 'fill_blank', 'Lengkapi frasa nomina: 焼きたてのパンや、入れた ___ のコーヒーが楽しめます。', '{"options":["ばかり","うち","はず","こと"],"translation":"Anda bisa menikmati roti yang baru dipanggang dan kopi yang baru diseduh.","sentence_template":"焼きたてのパンや、入れた [blank] のコーヒーが楽しめます。"}'::jsonb, '{"selected":"ばかり"}'::jsonb, NULL, NULL, '入れたばかりのコーヒー berarti kopi yang baru saja diseduh.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85b575f7-6cf4-56c9-9086-9861a0282308', '74078ccb-0e75-50ad-b423-ee176374a89f', NULL, 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 部屋を掃除 ___ ばかりなのに、もう散らかっています。', '{"options":["した","する","して","します"],"translation":"Padahal baru saja membersihkan kamar, sudah berantakan lagi.","sentence_template":"部屋を掃除 [blank] ばかりなのに、もう散らかっています。"}'::jsonb, '{"selected":"した"}'::jsonb, NULL, NULL, '掃除した (Bentuk-TA) + ばかりなのに.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('734ddbf2-0b56-454d-81e6-19c17e75f972', '74078ccb-0e75-50ad-b423-ee176374a89f', 'd1000019-0000-0000-0000-000000000016', 'listening', 'listening_choice', 'Dengarkan rekomendasi berikut. Bagaimana status kafe tersebut?', '{"options":[{"id":"opt_1","text":"Kafe ini baru saja buka bulan lalu dan selalu ramai antrean di akhir pekan"},{"id":"opt_2","text":"Kafe ini adalah kafe tua yang sudah berdiri puluhan tahun"},{"id":"opt_3","text":"Kafe ini sangat sepi pengunjung di akhir pekan"},{"id":"opt_4","text":"Kafe ini sudah tutup sejak bulan lalu"}],"audio_text":"ここは先月オープンしたばかりのカフェで、週末はいつも行列ができていますよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'オープンしたばかりのカフェ memakai の untuk menerangkan kata benda di belakangnya.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4c669f2d-8149-4321-bc07-6856f276fa79', '74078ccb-0e75-50ad-b423-ee176374a89f', 'd1000019-0000-0000-0000-000000000016', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 先ほど掃除を___ばかりなので、床がまだ濡れています。', '{"options":["終えた","終えて","終える","終え"],"translation":"Karena baru saja selesai mengepel tadi, lantainya masih basah.","sentence_template":"先ほど掃除を[blank]ばかりなので、床がまだ濡れています。"}'::jsonb, '{"selected":"終えた"}'::jsonb, NULL, NULL, 'Sebelum ばかり, kata kerja harus dalam bentuk lampau た (終えたばかり).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93cec210-4db4-5269-a4c2-dd3111d425b3', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang menjaga kebugaran: 毎日30分 ___ を続けています。', '{"options":["運動","運転","通勤","出張"],"translation":"Saya terus melakukan olahraga selama 30 menit setiap hari.","sentence_template":"毎日30分 [blank] を続けています。"}'::jsonb, '{"selected":"運動"}'::jsonb, NULL, NULL, '運動 (undou) berarti olahraga. 運転 berarti menyetir, 通勤 berarti pergi bekerja, dan 出張 berarti dinas luar kota.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f0411f7-8c13-547c-8d4b-aabb2bfe77af', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk rutinitas makan: 栄養の ___ を考えて食事を作ります。', '{"options":["バランス","スケジュール","キャンセル","アドバイス"],"translation":"Saya memasak makanan dengan memikirkan keseimbangan gizi.","sentence_template":"栄養の [blank] を考えて食事を作ります。"}'::jsonb, '{"selected":"バランス"}'::jsonb, NULL, NULL, '栄養のバランス (eiyou no baransu) adalah kolokasi umum yang berarti keseimbangan gizi.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c47c997b-dcb6-5591-bff8-97975561a0e9', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kebiasaan belajar: 寝る前にその日の授業を ___ します。', '{"options":["復習","欠席","遅刻","提出"],"translation":"Sebelum tidur, saya mengulang pelajaran hari itu.","sentence_template":"寝る前にその日の授業を [blank] します。"}'::jsonb, '{"selected":"復習"}'::jsonb, NULL, NULL, '復習 (fukushuu) berarti mengulang pelajaran. 欠席 (absen), 遅刻 (terlambat), dan 提出 (mengumpulkan tugas) tidak sesuai konteks.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3b9de5aa-dd09-5881-aeff-fe853f1ed2a0', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 毎朝同じ時間に起きる ___ がつきました。', '{"options":["習慣","予定","予約","経験"],"translation":"Saya sudah terbentuk kebiasaan bangun pada jam yang sama setiap pagi.","sentence_template":"毎朝同じ時間に起きる [blank] がつきました。"}'::jsonb, '{"selected":"習慣"}'::jsonb, NULL, NULL, '習慣がつく (shuukan ga tsuku) berarti terbentuk suatu kebiasaan.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73c9efe0-d598-5323-a2aa-55d8bc10a624', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'listening', 'listening_choice', 'Apa target belajar yang sedang dijalani pembicara setiap hari?', '{"options":[{"id":"opt_1","text":"Menghafal sepuluh kanji baru setiap hari"},{"id":"opt_2","text":"Membaca sepuluh halaman novel setiap malam"},{"id":"opt_3","text":"Menulis sepuluh email kerja dalam bahasa Jepang"},{"id":"opt_4","text":"Menghafal sepuluh pola tata bahasa setiap minggu"}],"audio_text":"試験に合格するために、毎日新しい漢字を十個覚える目標を立てました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pembicara mengatakan 毎日新しい漢字を十個覚える目標を立てました (membuat target menghafal 10 kanji baru setiap hari).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e638b6d-018a-555b-a8e0-f0a6cf96e3c9', '740c7717-808f-5cd0-a75f-dfda8ffc150f', NULL, 'listening', 'listening_choice', 'Mengapa pembicara mulai mengurangi minuman manis?', '{"options":[{"id":"opt_1","text":"Karena harga minuman manis di toko naik"},{"id":"opt_2","text":"Karena melihat hasil pemeriksaan kesehatan"},{"id":"opt_3","text":"Karena dokter melarang minum air dingin"},{"id":"opt_4","text":"Karena ingin menghemat biaya makan siang"}],"audio_text":"健康診断の結果を見て、甘い飲み物を控えて水を多く飲むことにしました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '健康診断の結果を見て berarti ''setelah melihat hasil pemeriksaan kesehatan''.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0b6a110-8b0c-40ac-b7af-72da7b30f3e2', '740c7717-808f-5cd0-a75f-dfda8ffc150f', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 健康のために、毎日エレベーターを使わずに階段を___ようにしています。', '{"options":["利用する","延期する","欠席する","卒業する"],"translation":"Demi kesehatan, setiap hari saya membiasakan diri menggunakan tangga tanpa memakai lift.","sentence_template":"健康のために、毎日エレベーターを使わずに階段を[blank]ようにしています。"}'::jsonb, '{"selected":"利用する"}'::jsonb, NULL, NULL, '利用する (riyou suru, menggunakan) + ようにしています menyatakan kebiasaan sadar yang sedang dijalani.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d116d26-7892-4e4a-9497-05bba2e96171', '740c7717-808f-5cd0-a75f-dfda8ffc150f', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan cerita kebiasaan malam berikut. Usaha apa yang sedang dilakukan pembicara?', '{"options":[{"id":"opt_1","text":"Mengurangi waktu tidur demi menyelesaikan membaca buku"},{"id":"opt_2","text":"Membiasakan membaca berita di ponsel selama sejam sebelum tidur"},{"id":"opt_3","text":"Tidak lagi membaca buku sejak membeli ponsel baru"},{"id":"opt_4","text":"Berusaha tidak melihat ponsel sejam sebelum tidur dan membiasakan membaca buku"}],"audio_text":"最近は寝る前の一時間、スマホを見ないようにして、本を読む習慣をつけています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '見ないようにする menyatakan usaha sadar untuk menghindari suatu kebiasaan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('666e967d-3950-5f1f-aa44-7e6bf997db39', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat logistik: ご注文の荷物は本日午後に ___ 予定です。', '{"options":["到着する","出発する","注文する","返品する"],"translation":"Paket pesanan Anda dijadwalkan tiba siang ini.","sentence_template":"ご注文の荷物は本日午後に [blank] 予定です。"}'::jsonb, '{"selected":"到着する"}'::jsonb, NULL, NULL, '到着する (touchaku suru) berarti tiba/sampai.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a2c8494e-6be3-55d7-9dfd-5d279968f33f', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk mengecek stok: 倉庫にまだ十分 ___ が残っています。', '{"options":["在庫","住所","領収書","請求書"],"translation":"Di gudang masih tersisa stok yang cukup.","sentence_template":"倉庫にまだ十分 [blank] が残っています。"}'::jsonb, '{"selected":"在庫"}'::jsonb, NULL, NULL, '在庫 (zaiko) berarti persediaan barang/stok.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a393d80-4334-5273-93b2-fb084bb6b71e', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kantor: 添付ファイルに間違いがないか、もう一度 ___ します。', '{"options":["確認","想像","期待","延期"],"translation":"Saya akan memeriksa sekali lagi apakah ada kesalahan di file lampiran.","sentence_template":"添付ファイルに間違いがないか、もう一度 [blank] します。"}'::jsonb, '{"selected":"確認"}'::jsonb, NULL, NULL, '確認する (kakunin suru) berarti memverifikasi atau memastikan.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a4cd9bf-3131-5644-9e4b-0feded793f0c', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'reading', 'fill_blank', 'Pilih kata untuk jadwal resmi: 電車の ___ によると、次の急行は五分後に来ます。', '{"options":["時刻表","案内図","説明書","履歴書"],"translation":"Menurut jadwal kereta, kereta ekspres berikutnya datang lima menit lagi.","sentence_template":"電車の [blank] によると、次の急行は五分後に来ます。"}'::jsonb, '{"selected":"時刻表"}'::jsonb, NULL, NULL, '時刻表 (jikokuhyou) berarti tabel jadwal keberangkatan transportasi.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a33cfc9e-718b-565f-a941-be9f86ada86d', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'listening', 'listening_choice', 'Bagaimana status pengiriman dokumen kontrak menurut pembicara?', '{"options":[{"id":"opt_1","text":"Kemungkinan sudah sampai di pihak klien pada pagi hari ini"},{"id":"opt_2","text":"Baru akan dikirim sore nanti lewat pos kilat"},{"id":"opt_3","text":"Tertahan di kantor pos karena alamat kurang lengkap"},{"id":"opt_4","text":"Akan diantarkan langsung oleh staf besok pagi"}],"audio_text":"昨日の夕方に速達で送りましたので、今日の午前中には先方に届いていると思います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '今日の午前中には先方に届いていると思います berarti diperkirakan sudah sampai pagi ini.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('777ad999-6b25-5b7e-897f-3f94f565a350', '7c4f7f16-ffd3-5f76-a882-72a61da81352', NULL, 'listening', 'listening_choice', 'Mengapa pembicara yakin ruangan rapat sedang kosong?', '{"options":[{"id":"opt_1","text":"Karena lampu ruang rapat terlihat mati dari luar"},{"id":"opt_2","text":"Karena di kalender reservasi tidak ada yang memakainya jam tiga sampai empat"},{"id":"opt_3","text":"Karena semua pegawai sedang menghadiri seminar luar"},{"id":"opt_4","text":"Karena kuncinya masih tergantung di meja resepsionis"}],"audio_text":"予約カレンダーを確認したところ、三時から四時までは誰も使っていませんでした。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '予約カレンダーを確認したところ...誰も使っていませんでした berarti setelah cek kalender reservasi, tidak ada yang memakainya.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37db019a-628c-46e6-a986-964d415e83ca', '7c4f7f16-ffd3-5f76-a882-72a61da81352', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 荷物は昨日発送したので、今日中には___するはずです。', '{"options":["卒業","欠席","到着","中止"],"translation":"Karena paket sudah dikirim kemarin, seharusnya tiba hari ini juga.","sentence_template":"荷物は昨日発送したので、今日中には[blank]するはずです。"}'::jsonb, '{"selected":"到着"}'::jsonb, NULL, NULL, '到着する (tiba) + はずです menyatakan perkiraan logis berdasarkan bukti pengiriman.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cfbd9ed4-8ba1-402b-a5ec-16f6291fc7f3', '7c4f7f16-ffd3-5f76-a882-72a61da81352', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Seberapa yakin pembicara tentang lokasi kunci?', '{"options":[{"id":"opt_1","text":"Pembicara belum pernah mengecek isi tasnya"},{"id":"opt_2","text":"Kunci ditinggalkan di meja kantor sejak kemarin"},{"id":"opt_3","text":"Kunci sudah pasti hilang di luar rumah"},{"id":"opt_4","text":"Karena baru saja dicek, kuncinya seharusnya pasti ada di dalam tas"}],"audio_text":"さっき確認しましたから、鍵は間違いなくかばんの中にあるはずです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '確認しましたから～あるはずです menunjukkan keyakinan logis berdasar bukti.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('26800879-4037-59f1-8872-76639bceb5b2', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Pilih bentuk paling tepat: エレベーターを使わず、階段で ___ ようにしています。', '{"options":["上がる","上がった","上がって","上がろう"],"translation":"Tanpa memakai lift, saya membiasakan diri naik lewat tangga.","sentence_template":"エレベーターを使わず、階段で [blank] ようにしています。"}'::jsonb, '{"selected":"上がる"}'::jsonb, NULL, NULL, 'Bentuk kamus 上がる digunakan sebelum ようにしています.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fffc0b3f-13a6-5cd5-b52f-26cf1652b115', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi imbauan kantor: 個人情報が外部に ___ ようにしてください。', '{"options":["漏れない","漏れる","漏れた","漏れて"],"translation":"Usahakanlah agar data pribadi tidak bocor ke pihak luar.","sentence_template":"個人情報が外部に [blank] ようにしてください。"}'::jsonb, '{"selected":"漏れない"}'::jsonb, NULL, NULL, '漏れる (moreru = bocor) diubah ke bentuk-NAI 漏れない agar bermakna ''tidak bocor''.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be7b77d0-bdba-5194-8bdb-d180ff157fc0', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Apa yang dilakukan pembicara demi menghemat uang bulanan?', '{"options":[{"id":"opt_1","text":"Berjalan kaki pulang dari kantor setiap sore"},{"id":"opt_2","text":"Berbelanja bahan makanan hanya saat akhir pekan"},{"id":"opt_3","text":"Membuat bekal sendiri pada hari kerja"},{"id":"opt_4","text":"Tidak membeli kopi di kafe dekat stasiun"}],"audio_text":"節約のために、平日は自分で弁当を作って会社へ持っていくようにしています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '平日は自分で弁当を作って会社へ持っていく berarti membuat bekal sendiri dan membawanya ke kantor di hari kerja.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6eb9a252-969e-5dd9-b972-2b4756b4cc32', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Mengapa pembicara datang 10 menit lebih awal sebelum jam kerja?', '{"options":[{"id":"opt_1","text":"Agar bisa sarapan dengan tenang di kantin"},{"id":"opt_2","text":"Agar bisa mengobrol lebih lama dengan rekan kerja"},{"id":"opt_3","text":"Karena bus yang dinaiki selalu tiba terlalu cepat"},{"id":"opt_4","text":"Agar tidak terburu-buru saat jam kerja dimulai"}],"audio_text":"慌てないように、始業時間の十分前には席に着くようにしています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '慌てないように berarti ''agar tidak panik / terburu-buru''.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ab76b573-304b-5e82-86c2-aa05622fdf6a', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha mengecek prakiraan cuaca setiap pagi."', '{"romaji":"Maiasa tenki yohou o kakunin suru you ni shite imasu.","tokens":["毎朝","確認する","天気予報を","確認して","ように","しています。","確認した"],"target_translation":"Saya berusaha mengecek prakiraan cuaca setiap pagi."}'::jsonb, '["毎朝","天気予報を","確認する","ように","しています。"]'::jsonb, NULL, NULL, '天気予報を確認する (mengecek prakiraan cuaca) + ようにしています.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0cbf4f0b-c4d6-58de-bbdb-5d08ac43650d', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya membiasakan diri membalas email di hari yang sama."', '{"romaji":"Meeru wa sono hi no uchi ni henshin suru you ni shite imasu.","display_text":"メールはその日のうちに返信するようにしています。","phonetic_breakdown":["mee-ru wa","so-no hi no u-chi ni","hen-shin su-ru","you ni","shi-te i-ma-su"]}'::jsonb, '{"expected_transcript":"メールはその日のうちに返信するようにしています。"}'::jsonb, NULL, NULL, '返信する (henshin suru) berarti membalas pesan/email. Kalimat ini sangat berguna dalam etika kerja Jepang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8519ee08-8810-4a45-8296-fafd4a62b291', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 会議では相手の話を最後までしっかり___ようにしています。', '{"options":["聞いた","聞く","聞こう","聞いて"],"translation":"Dalam rapat, saya berusaha mendengarkan ucapan lawan bicara sampai selesai dengan saksama.","sentence_template":"会議では相手の話を最後までしっかり[blank]ようにしています。"}'::jsonb, '{"selected":"聞く"}'::jsonb, NULL, NULL, '聞く (bentuk kamus) + ようにしています menyatakan prinsip komunikasi yang dijaga.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d1e946f-774a-4f54-b05b-392849cc499f', '7eda7366-e41d-5329-b4b6-4cc012dd3b55', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kanji yang tidak saya pahami tidak saya biarkan begitu saja, melainkan saya biasakan langsung mencarinya."', '{"romaji":"Wakaranai kanji wa sono mama ni sezu, sugu shiraberu you ni shite imasu.","display_text":"分からない漢字はそのままにせず、すぐ調べるようにしています。","phonetic_breakdown":["wa-ka-ra-nai","kan-ji-wa","so-no-ma-ma-ni-se-zu","su-gu","shi-ra-be-ru","you-ni","shi-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"分からない漢字はそのままにせず、すぐ調べるようにしています。"}'::jsonb, NULL, NULL, '調べるようにしています menggambarkan kebiasaan belajar aktif tingkat N3.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b96faf7e-11e0-4c3b-99b3-0d8bb61eb44c', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 運動不足を解消するため、一駅手前で降りて___ようにしています。', '{"options":["歩く","歩いて","歩けば","歩いた"],"translation":"Untuk mengatasi kurang olahraga, saya membiasakan turun satu stasiun lebih awal lalu berjalan kaki.","sentence_template":"運動不足を解消するため、一駅手前で降りて[blank]ようにしています。"}'::jsonb, '{"selected":"歩く"}'::jsonb, NULL, NULL, '歩く (bentuk kamus) + ようにしています.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('973f1bc6-12aa-4012-a853-dccec9d6e5ce', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: どんなに忙しくても、朝ごはんだけは抜か___ようにしています。', '{"options":["ない","なくて","ず","なかった"],"translation":"Sesibuk apa pun, saya berusaha agar tidak melewatkan sarapan.","sentence_template":"どんなに忙しくても、朝ごはんだけは抜か[blank]ようにしています。"}'::jsonb, '{"selected":"ない"}'::jsonb, NULL, NULL, '抜く -> 抜かない + ようにしています.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8250a359-9e16-466f-8e19-bcd64f8235ba', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan kiat kerja berikut. Apa yang dibiasakan oleh pembicara?', '{"options":[{"id":"opt_1","text":"Menghindari berbicara dengan rekan kerja agar fokus bekerja"},{"id":"opt_2","text":"Mengeluh karena suasana kantor terlalu bising"},{"id":"opt_3","text":"Menunggu rekan kerja menyapa terlebih dahulu setiap pagi"},{"id":"opt_4","text":"Berusaha menyapa lebih dulu dengan ceria demi memperbaiki hubungan kerja di kantor"}],"audio_text":"職場の人間関係を良くするために、自分から明るくあいさつするようにしています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'あいさつするようにしています menunjukkan upaya sadar menjaga suasana kerja.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eabd3538-0c11-44c6-97e6-161e9b049c56', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Untuk mengurangi sampah, saya membiasakan membawa tas belanja sendiri."', '{"romaji":"Gomi o herasu tame ni, maibaggu o mochiaruku you ni shite imasu.","tokens":["持ち歩く","ように","ために、","マイバッグを","減らす","しています。","持ち歩いた","へ","ゴミを"],"target_translation":"Untuk mengurangi sampah, saya membiasakan membawa tas belanja sendiri."}'::jsonb, '["ゴミを","減らす","ために、","マイバッグを","持ち歩く","ように","しています。"]'::jsonb, NULL, NULL, '持ち歩く (membawa ke mana-mana) + ようにしています.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fba58d82-1585-42b9-93c1-afae35ca4bab', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 締め切りに遅れないように、計画的に仕事を___ようにしましょう。', '{"options":["進める","進めて","進めよう","進めた"],"translation":"Agar tidak terlambat tenggat waktu, mari biasakan mengerjakan tugas secara terencana.","sentence_template":"締め切りに遅れないように、計画的に仕事を[blank]ようにしましょう。"}'::jsonb, '{"selected":"進める"}'::jsonb, NULL, NULL, '進める (bentuk kamus) + ようにしましょう.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40081bb2-0355-4614-8825-9992ca9f26d0', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di malam hari saya membiasakan tidur sebelum pukul dua belas."', '{"romaji":"Yoru wa juuniji mae ni neru you ni shite imasu.","display_text":"夜は十二時前に寝るようにしています。","phonetic_breakdown":["yo-ru-wa","juu-ni-ji","ma-e-ni","ne-ru","you-ni","shi-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"夜は十二時前に寝るようにしています。"}'::jsonb, NULL, NULL, '寝るようにしています menyatakan disiplin jam tidur.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aaab03a5-8822-46cb-9612-0ed31b736029', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan arahan senior berikut. Kebiasaan apa yang diminta?', '{"options":[{"id":"opt_1","text":"Diminta membiasakan selalu mengecek alamat tujuan dan lampiran sebelum mengirim email"},{"id":"opt_2","text":"Diminta mengirim email tanpa lampiran agar lebih cepat"},{"id":"opt_3","text":"Diminta mengecek email hanya seminggu sekali"},{"id":"opt_4","text":"Dilarang mengirim email kepada rekan di luar divisi"}],"audio_text":"メールを送る前に、宛先と添付ファイルに間違いがないか必ず確認するようにしてください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '確認するようにしてください meminta lawan bicara menjadikan pengecekan sebagai kebiasaan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('18ca050e-2fed-4fff-8d3e-5bf7fc9bbd55', '846c03a7-ecf0-4536-bee4-dab26f506299', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saat hari libur, saya berusaha sebisa mungkin pergi ke tempat yang banyak alamnya."', '{"romaji":"Kyuujitsu wa dekiru dake shizen no ooi basho e iku you ni shite imasu.","tokens":["自然の","行った","行く","場所へ","休日は","を","多い","しています。","ように","できるだけ"],"target_translation":"Saat hari libur, saya berusaha sebisa mungkin pergi ke tempat yang banyak alamnya."}'::jsonb, '["休日は","できるだけ","自然の","多い","場所へ","行く","ように","しています。"]'::jsonb, NULL, NULL, 'できるだけ memperkuat nuansa usaha dalam 行くようにしています.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('993249b1-5b35-5c50-8c47-134440b292a6', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara kereta terlambat, saya terlambat masuk kerja."', '{"romaji":"Densha ga okureta sei de, chikoku shite shimaimashita.","display_text":"電車が遅れたせいで、遅刻してしまいました。","phonetic_breakdown":["den-sha ga","o-ku-re-ta","se-i de","chi-ko-ku","shi-te","shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"電車が遅れたせいで、遅刻してしまいました。"}'::jsonb, NULL, NULL, 'Catatan etika kantor: saat melapor ke atasan, gunakan 電車が遅れたため agar lebih objektif dan tidak terkesan menyalahkan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('970c21f0-6f58-57b9-85f1-971591069d21', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara kurang olahraga, berat badan saya naik."', '{"romaji":"Undoubusoku no sei de, taijuu ga fuemashita.","display_text":"運動不足のせいで、体重が増えました。","phonetic_breakdown":["un-dou-bu-so-ku no","se-i de","ta-i-juu ga","fu-e-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"運動不足のせいで、体重が増えました。"}'::jsonb, NULL, NULL, '運動不足 (undoubusoku) berarti kurang olahraga; 体重 (taijuu) berarti berat badan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c467d46-9621-508d-a619-c7277a82332f', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mungkin karena lelah, saya langsung tertidur."', '{"romaji":"Tsukarete ita sei ka, sugu nemutte shimaimashita.","display_text":"疲れていたせいか、すぐ眠ってしまいました。","phonetic_breakdown":["tsu-ka-re-te i-ta","se-i ka","su-gu","ne-mut-te","shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"疲れていたせいか、すぐ眠ってしまいました。"}'::jsonb, NULL, NULL, '～せいか memberi nuansa perkiraan penyebab yang lembut.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('866b2b70-b280-591f-a67f-bee2a9bf94e7', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara salah tekan tombol, datanya terhapus."', '{"romaji":"Botan o oshimachigaeta sei de, deeta ga kiemashita.","tokens":["データが","押して","消えました。","ボタンを","おかげで、","押し間違えた","せいで、"],"target_translation":"Gara-gara salah tekan tombol, datanya terhapus."}'::jsonb, '["ボタンを","押し間違えた","せいで、","データが","消えました。"]'::jsonb, NULL, NULL, '押し間違えた (salah tekan) + せいで + データが消えました (data hilang).', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('41ff70a0-76ad-5303-afe2-dbc5a9e83c14', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara suara bising, saya tidak bisa mendengar suaranya."', '{"romaji":"Souon no sei de, koe ga kikoemasen deshita.","tokens":["せいで、","聞こえませんでした。","騒音な","声が","騒音の","おかげで、"],"target_translation":"Gara-gara suara bising, saya tidak bisa mendengar suaranya."}'::jsonb, '["騒音の","せいで、","声が","聞こえませんでした。"]'::jsonb, NULL, NULL, '騒音のせいで (gara-gara kebisingan) diikuti hasil negatif 聞こえませんでした.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eaef1d10-cf71-54bb-af6f-398768f24088', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara lupa membawa payung, baju saya basah."', '{"romaji":"Kasa o wasureta sei de, fuku ga nuremashita.","tokens":["服が","忘れて","おかげで、","忘れた","せいで、","濡れました。","傘を"],"target_translation":"Gara-gara lupa membawa payung, baju saya basah."}'::jsonb, '["傘を","忘れた","せいで、","服が","濡れました。"]'::jsonb, NULL, NULL, '忘れた (bentuk biasa lampau) + せいで.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dcacbbb8-79c7-4c66-a560-ab2f7461eab7', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara angin, cucian tertiup terbang."', '{"romaji":"Kaze no sei de, sentakumono ga tobasarete shimaimashita.","display_text":"風のせいで、洗濯物が飛ばされてしまいました。","phonetic_breakdown":["ka-ze-no","sei-de","sen-ta-ku-mo-no-ga","to-ba-sa-re-te","shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"風のせいで、洗濯物が飛ばされてしまいました。"}'::jsonb, NULL, NULL, '風のせいで menyatakan penyebab alami dari kejadian yang merepotkan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f8e4604-439b-4e0e-be7f-67402b8a1942', '8de66d94-d11d-5330-b89e-991feafa15bd', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kelalaian, saya melakukan kesalahan besar."', '{"romaji":"Fuchuui no sei de, ookina misu o shite shimaimashita.","tokens":["が","おかげで、","ミスを","大きな","せいで、","不注意の","して","しまいました。"],"target_translation":"Karena kelalaian, saya melakukan kesalahan besar."}'::jsonb, '["不注意の","せいで、","大きな","ミスを","して","しまいました。"]'::jsonb, NULL, NULL, '不注意 (kelalaian) + のせいで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('153c2423-bd40-57c6-a7a6-5e7b38edf941', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 先生 ___ おかげで、日本語が上達しました。', '{"options":["の","な","に","を"],"translation":"Berkat guru, bahasa Jepang saya berkembang pesat.","sentence_template":"先生 [blank] おかげで、日本語が上達しました。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Nomina + の + おかげで (先生の + おかげで).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ac15d49-e424-5b25-836c-3ed8e701b598', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 毎日 ___ おかげで、発表がうまくいきました。', '{"options":["練習した","練習して","練習します","練習しよう"],"translation":"Berkat berlatih setiap hari, presentasinya berjalan lancar.","sentence_template":"毎日 [blank] おかげで、発表がうまくいきました。"}'::jsonb, '{"selected":"練習した"}'::jsonb, NULL, NULL, 'Sebelum おかげで digunakan bentuk biasa; untuk kejadian yang sudah dilakukan gunakan bentuk-TA (練習した).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cc0c9d58-dbd0-5896-8085-cb768c8a3071', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Pilih bentuk kata sifat-NA yang tepat: 天気が ___ おかげで、富士山がきれいに見えました。', '{"options":["よかった","いいな","よくて","よかったです"],"translation":"Berkat cuaca yang cerah, Gunung Fuji terlihat dengan jelas.","sentence_template":"天気が [blank] おかげで、富士山がきれいに見えました。"}'::jsonb, '{"selected":"よかった"}'::jsonb, NULL, NULL, 'Bentuk biasa lampau dari いい adalah よかった, sehingga menjadi 天気がよかったおかげで.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4bce04d-cd59-5d89-8a08-fd554b969e03', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat senior, saya cepat terbiasa dengan pekerjaan."', '{"romaji":"Senpai no okage de, shigoto ni hayaku naremashita.","tokens":["慣れます。","せいで、","慣れました。","仕事に","先輩の","おかげで、","早く"],"target_translation":"Berkat senior, saya cepat terbiasa dengan pekerjaan."}'::jsonb, '["先輩の","おかげで、","仕事に","早く","慣れました。"]'::jsonb, NULL, NULL, '先輩のおかげで menyatakan rasa terima kasih atas bantuan senior.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('652ecbd8-1fbc-54f6-8e60-1fc76129b97c', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat obat ini, demam saya sudah turun."', '{"romaji":"Kono kusuri no okage de, netsu ga sagarimashita.","tokens":["上がりました。","この薬の","熱が","下がりました。","おかげで、","な"],"target_translation":"Berkat obat ini, demam saya sudah turun."}'::jsonb, '["この薬の","おかげで、","熱が","下がりました。"]'::jsonb, NULL, NULL, 'Nomina この薬 dihubungkan dengan partikel の sebelum おかげで.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('12f89d11-0b62-50d5-b17b-4cd17373a08a', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Apa alasan keberhasilan acara penyambutan menurut pembicara?', '{"options":[{"id":"opt_1","text":"Karena anggaran acara ditambah oleh perusahaan"},{"id":"opt_2","text":"Karena restorannya sangat dekat dari stasiun"},{"id":"opt_3","text":"Berkat kerja sama semua orang"},{"id":"opt_4","text":"Karena jumlah tamu lebih sedikit dari perkiraan"}],"audio_text":"皆さんのご協力のおかげで、歓迎会を無事に終えることができました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '皆さんのご協力のおかげで berarti ''berkat kerja sama Anda sekalian''.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e32198ae-f327-4fac-9eca-0314df38dfb4', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 毎日練習した___、スピーチコンテストで入賞できました。', '{"options":["せいで","ばかりに","に対して","おかげで"],"translation":"Berkat berlatih setiap hari, saya berhasil meraih juara di lomba pidato.","sentence_template":"毎日練習した[blank]、スピーチコンテストで入賞できました。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, 'Kata kerja bentuk lampau biasa (練習した) + おかげで menyatakan sebab dari hasil positif.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be744859-eabc-42f4-90a4-add10570d022', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat guru, saya berhasil lulus JLPT N3."', '{"romaji":"Sensei no okage de, JLPT N3 ni goukaku dekimashita.","tokens":["せいで、","を","JLPT N3に","おかげで、","できました。","先生の","合格"],"target_translation":"Berkat guru, saya berhasil lulus JLPT N3."}'::jsonb, '["先生の","おかげで、","JLPT N3に","合格","できました。"]'::jsonb, NULL, NULL, 'Kata benda (先生) + のおかげで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('202bfab7-5b8f-5a91-8572-8fd070bca432', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat ajakan makan: スープが ___ うちに召し上がってください。', '{"options":["温かい","温かいな","温かいの","温かくて"],"translation":"Silakan dinikmati selagi supnya masih hangat.","sentence_template":"スープが [blank] うちに召し上がってください。"}'::jsonb, '{"selected":"温かい"}'::jsonb, NULL, NULL, 'Kata sifat-I langsung diikuti うちに (温かいうちに).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c8e8bd86-69f4-56db-a9a3-2023faa54e3b', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Pilih bentuk negatif sebelum berubah kondisi: 雨が ___ うちに家へ帰りましょう。', '{"options":["降らない","降る","降った","降って"],"translation":"Mari pulang ke rumah selagi belum turun hujan.","sentence_template":"雨が [blank] うちに家へ帰りましょう。"}'::jsonb, '{"selected":"降らない"}'::jsonb, NULL, NULL, 'Bentuk-NAI + うちに (降らないうちに) berarti ''selagi belum / sebelum terjadi''.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8305cbde-b954-5bea-a639-d5e9498b1da1', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi penghubung nomina: 独身 ___ うちにいろいろな国を旅したいです。', '{"options":["の","な","に","で"],"translation":"Selagi masih lajang, saya ingin bepergian ke berbagai negara.","sentence_template":"独身 [blank] うちにいろいろな国を旅したいです。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Nomina + の + うちに (独身のうちに).', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ce3578c-cfe8-57ee-aa32-5f0743f0e584', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mari mencatat selagi belum lupa."', '{"romaji":"Wasurenai uchi ni memo o torimashou.","tokens":["忘れない","うちに","メモを","せいで","とりましょう。","忘れる"],"target_translation":"Mari mencatat selagi belum lupa."}'::jsonb, '["忘れない","うちに","メモを","とりましょう。"]'::jsonb, NULL, NULL, '忘れないうちに berarti ''mumpung belum lupa''.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c51115df-2973-5c6e-b30e-4bbbab21995b', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Selagi muda, sebaiknya mencoba banyak hal."', '{"romaji":"Wakai uchi ni iroirona koto ni chousen shita hou ga ii desu.","tokens":["ほうがいいです。","挑戦した","挑戦する","いろいろなことに","若いの","うちに","若い"],"target_translation":"Selagi muda, sebaiknya mencoba banyak hal."}'::jsonb, '["若い","うちに","いろいろなことに","挑戦した","ほうがいいです。"]'::jsonb, NULL, NULL, 'Kata sifat-I 若い + うちに + ～たほうがいいです (sebaiknya).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bcd4bf62-45e4-5f39-84ce-f81a177bfb24', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Perubahan apa yang terjadi tanpa disadari oleh pembicara?', '{"options":[{"id":"opt_1","text":"Ia menjadi sering tidur terlalu malam"},{"id":"opt_2","text":"Ia mulai bosan menonton acara televisi"},{"id":"opt_3","text":"Ia menjadi mengerti ungkapan percakapan alami"},{"id":"opt_4","text":"Ia memutuskan pindah bekerja di stasiun televisi"}],"audio_text":"日本のドラマを毎日見ているうちに、自然な会話表現がわかるようになりました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '～ているうちに menunjukkan perubahan bertahap yang terjadi selama melakukan sesuatu secara terus-menerus.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4655ef1-0e9c-48f7-b1ea-db45f65a2d66', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 暗くならない___、急いで家へ帰りましょう。', '{"options":["に対して","おかげで","せいで","うちに"],"translation":"Mumpung belum gelap, mari segera pulang ke rumah.","sentence_template":"暗くならない[blank]、急いで家へ帰りましょう。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, 'Bentuk ない (暗くならない) + うちに berarti ''selagi belum ... / sebelum berubah menjadi ...''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ebf47edd-0ce7-4897-89a5-7ba22739a8bf', '90ec6cc0-3dff-5412-b034-3b6ec1707057', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mumpung berada di Jepang, setidaknya sekali saya ingin mencoba pergi ke Hokkaido."', '{"romaji":"Nihon ni iru uchi ni, ichido wa Hokkaidou e itte mitai desu.","tokens":["うちに、","一度は","日本に","北海道へ","を","せいで、","いる","行ってみたいです。"],"target_translation":"Mumpung berada di Jepang, setidaknya sekali saya ingin mencoba pergi ke Hokkaido."}'::jsonb, '["日本に","いる","うちに、","一度は","北海道へ","行ってみたいです。"]'::jsonb, NULL, NULL, 'いる (bentuk kamus) + うちに menyatakan kesempatan selagi kondisi masih berlangsung.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95378fa8-00f8-52b0-b8d7-c85c46a0c216', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat keragaman: 国 ___ 挨拶の仕方が違います。', '{"options":["によって","に対して","にとって","について"],"translation":"Tergantung negaranya, cara menyapanya berbeda.","sentence_template":"国 [blank] 挨拶の仕方が違います。"}'::jsonb, '{"selected":"によって"}'::jsonb, NULL, NULL, 'Nomina + によって menyatakan variasi atau perbedaan yang bergantung pada suatu faktor.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ece1aeb-25da-5903-a058-913219536a51', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Pilih bentuk yang menerangkan nomina: 大雨 ___ 被害が広がっています。', '{"options":["による","によって","によった","によります"],"translation":"Kerusakan akibat hujan deras terus meluas.","sentence_template":"大雨 [blank] 被害が広がっています。"}'::jsonb, '{"selected":"による"}'::jsonb, NULL, NULL, 'Ketika menerangkan kata benda (被害 = kerusakan), によって berubah menjadi による.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2c3c1f5-7270-560d-9e53-ef8d90f05a48', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat cara/metode: インターネットの普及 ___ 、働き方が変わりました。', '{"options":["によって","に対して","のおかげで","のうちに"],"translation":"Melalui/karena meluasnya internet, cara bekerja telah berubah.","sentence_template":"インターネットの普及 [blank] 、働き方が変わりました。"}'::jsonb, '{"selected":"によって"}'::jsonb, NULL, NULL, 'Nomina + によって menyatakan sebab objektif atau sarana terjadinya perubahan.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98f34f44-6668-5806-b796-0ce04e130d3d', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung orangnya, pendapatnya berbeda."', '{"romaji":"Hito ni yotte iken ga chigaimasu.","tokens":["対して","意見が","よる","違います。","よって","人に"],"target_translation":"Tergantung orangnya, pendapatnya berbeda."}'::jsonb, '["人に","よって","意見が","違います。"]'::jsonb, NULL, NULL, '人によって berarti ''tergantung orangnya''.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aab60955-99a4-5d94-80dc-5c3ff6c1fdef', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Gedung ini dirancang oleh arsitek terkenal."', '{"romaji":"Kono tatemono wa yuumeina kenchikuka ni yotte sekkei saremashita.","tokens":["よる","設計されました。","有名な建築家に","設計しました。","この建物は","よって"],"target_translation":"Gedung ini dirancang oleh arsitek terkenal."}'::jsonb, '["この建物は","有名な建築家に","よって","設計されました。"]'::jsonb, NULL, NULL, 'Dalam kalimat pasif karya/bangunan, pelaku ditandai dengan によって.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c9e71cca-1d93-52b8-a106-44a1f870104e', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Apa yang memengaruhi tarif kamar hotel tersebut?', '{"options":[{"id":"opt_1","text":"Jumlah barang bawaan yang dibawa tamu"},{"id":"opt_2","text":"Metode pembayaran tunai atau kartu kredit"},{"id":"opt_3","text":"Musim dan hari dalam seminggu"},{"id":"opt_4","text":"Lama waktu tamu menginap di hotel sebelumnya"}],"audio_text":"このホテルの宿泊料金は、季節や曜日によって大きく変わります。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '季節や曜日によって大きく変わります berarti berubah besar tergantung musim dan hari.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('226e8c6c-02cf-46c4-aa59-c77982e87b83', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 同じ言葉でも、使う場面に___意味が変わることがあります。', '{"options":["おいて","ついて","対して","よって"],"translation":"Meskipun kata yang sama, maknanya bisa berubah tergantung pada situasi penggunaannya.","sentence_template":"同じ言葉でも、使う場面に[blank]意味が変わることがあります。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, '～によって menyatakan variasi atau perbedaan yang bergantung pada kondisi.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0c2375e-1410-4ea4-afad-14f2cce22c98', '91662d89-eef5-5734-b1fa-90f73f5178b9', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Survei ini dilaksanakan melalui internet."', '{"romaji":"Kono ankeeto wa intaanetto ni yotte jisshi saremashita.","tokens":["対して","インターネットに","されました。","を","実施","この","アンケートは","よって"],"target_translation":"Survei ini dilaksanakan melalui internet."}'::jsonb, '["この","アンケートは","インターネットに","よって","実施","されました。"]'::jsonb, NULL, NULL, '～によって menyatakan sarana atau cara pelaksanaan secara formal.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('124af529-e683-5626-9ad6-929875865f68', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk yang benar: 新製品 ___ アンケート調査を実施しました。', '{"options":["に対する","に対して","に対した","に対します"],"translation":"Kami telah melaksanakan survei kuesioner terhadap produk baru.","sentence_template":"新製品 [blank] アンケート調査を実施しました。"}'::jsonb, '{"selected":"に対する"}'::jsonb, NULL, NULL, 'アンケート調査 adalah nomina, sehingga bentuk penghubung yang tepat adalah に対する.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bd1632cb-f043-552b-8c81-9868d280930f', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kontras kebiasaan: 姉は朝型なの ___ 、私は夜型です。', '{"options":["に対して","のために","のおかげで","のせいで"],"translation":"Berbeda dengan kakak perempuan yang tipe pagi, saya tipe malam.","sentence_template":"姉は朝型なの [blank] 、私は夜型です。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, 'Nomina 朝型 + なのに対して mengontraskan dua tipe kebiasaan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('400ce88f-bae4-594c-b514-f27d277e02ce', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Bagaimana perbandingan peserta seminar tahun ini dan tahun lalu?', '{"options":[{"id":"opt_1","text":"Tahun ini peserta berkurang separuh"},{"id":"opt_2","text":"Jumlah peserta tahun lalu dan tahun ini sama persis"},{"id":"opt_3","text":"Tahun lalu lima puluh orang, sedangkan tahun ini lebih dari seratus orang"},{"id":"opt_4","text":"Seminar tahun lalu dibatalkan karena kurang peserta"}],"audio_text":"去年の参加者が五十人だったのに対して、今年は百人以上が集まりました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '去年の参加者が五十人だったのに対して、今年は百人以上 berarti 50 orang tahun lalu berbanding lebih dari 100 orang tahun ini.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7434c68-f69b-5cf1-b9c1-1c41f147ef21', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Apa yang ditekankan perusahaan dalam menanggapi masukan karyawan?', '{"options":[{"id":"opt_1","text":"Usulan hanya diterima saat rapat tahunan"},{"id":"opt_2","text":"Karyawan tidak boleh mengirim usulan secara anonim"},{"id":"opt_3","text":"Semua usulan otomatis disetujui oleh manajer"},{"id":"opt_4","text":"Setiap usulan wajib dijawab maksimal dalam satu minggu"}],"audio_text":"社員からの提案に対して、必ず一週間以内に回答するルールになっています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '必ず一週間以内に回答するルール berarti aturan wajib menjawab dalam waktu satu minggu.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f122304-c01e-5ded-a9fe-2b9abf62a6d3', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Saya sangat berterima kasih atas perhatian Anda terhadap keluarga saya."', '{"romaji":"Kazoku ni taisuru gohairyo ni kansha shite imasu.","tokens":["対して","家族に","対する","感謝しています。","せいで","ご配慮に"],"target_translation":"Saya sangat berterima kasih atas perhatian Anda terhadap keluarga saya."}'::jsonb, '["家族に","対する","ご配慮に","感謝しています。"]'::jsonb, NULL, NULL, 'ご配慮 (perhatian/kepedulian) adalah nomina sehingga memakai に対する.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23b2bff4-a1a2-5eb6-ad44-c762700e48d9', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menjawab setiap pertanyaan pelanggan dengan tulus."', '{"romaji":"Okyakusama no goshitsumon ni taishite seijitsu ni okotae shimasu.","display_text":"お客様のご質問に対して誠実にお答えします。","phonetic_breakdown":["o-kya-ku-sa-ma no","go-shi-tsu-mon ni","ta-i-shi-te","se-i-ji-tsu ni","o-ko-ta-e shi-ma-su"]}'::jsonb, '{"expected_transcript":"お客様のご質問に対して誠実にお答えします。"}'::jsonb, NULL, NULL, '誠実に (seijitsu ni) berarti dengan tulus/jujur. Kalimat formal yang kuat untuk layanan pelanggan.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb045f2d-d6d5-45b3-b7fc-8243a716c464', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この問題に___、専門家たちの間でも意見が分かれています。', '{"options":["おいて","よって","とって","対して"],"translation":"Terhadap masalah ini, pendapat di kalangan para ahli pun terbelah.","sentence_template":"この問題に[blank]、専門家たちの間でも意見が分かれています。"}'::jsonb, '{"selected":"対して"}'::jsonb, NULL, NULL, '問題に対して berarti ''terhadap masalah ini''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9559702a-3068-4ec5-bc7e-900a51c20863', '916df766-6712-52e0-a1ac-72f2a24b3dee', 'd1000019-0000-0000-0000-000000000012', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berbeda dengan kakak perempuan yang suka makanan manis, saya suka makanan pedas."', '{"romaji":"Ane wa amai mono ga suki na no ni taishite, watashi wa karai mono ga suki desu.","display_text":"姉は甘いものが好きなのに対して、私は辛いものが好きです。","phonetic_breakdown":["a-ne-wa","a-mai-mo-no-ga","su-ki-na-no-ni","tai-shi-te","wa-ta-shi-wa","ka-rai-mo-no-ga","su-ki-de-su"]}'::jsonb, '{"expected_transcript":"姉は甘いものが好きなのに対して、私は辛いものが好きです。"}'::jsonb, NULL, NULL, 'Kata sifat な (好き) menjadi 好きなのに対して saat membandingkan dua hal.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bac80ed-27e0-490e-854d-1eb4d15aada8', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan kabar gembira berikut. Apa yang akan terjadi mulai musim gugur?', '{"options":[{"id":"opt_1","text":"Baru saja pulang setelah setahun belajar di Jepang"},{"id":"opt_2","text":"Memutuskan menunda keberangkatan ke Jepang hingga tahun depan"},{"id":"opt_3","text":"Gagal dalam seleksi pertukaran pelajar ke Jepang"},{"id":"opt_4","text":"Lulus program pertukaran pelajar sehingga diputuskan berangkat ke Jepang setahun mulai musim gugur"}],"audio_text":"大学の交換留学プログラムに合格して、秋から一年間日本へ行くことになりました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '行くことになりました menyampaikan hasil kelulusan program secara natural.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9ba6a265-3049-4c07-b415-0c2600a7ddf9', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di dalam fasilitas ini ketentuannya dilarang mengambil foto."', '{"romaji":"Kono shisetsunai de wa shashin satsuei wa kinshi suru koto ni natte imasu.","display_text":"この施設内では写真撮影は禁止することになっています。","phonetic_breakdown":["ko-no","shi-se-tsu-nai-de-wa","sha-shin-sa-tsu-ei-wa","kin-shi-su-ru","ko-to-ni","nat-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"この施設内では写真撮影は禁止することになっています。"}'::jsonb, NULL, NULL, '禁止することになっています menjelaskan aturan fasilitas umum.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55c10e20-1bc6-4ad1-a487-07e77d9d4d77', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Waktu rapat diputuskan diubah menjadi mulai pukul tiga."', '{"romaji":"Kaigi no jikan ga sanji kara ni henkou sareru koto ni narimashita.","tokens":["なりました。","会議の","時間が","変更した","三時からに","ことに","変更される","を"],"target_translation":"Waktu rapat diputuskan diubah menjadi mulai pukul tiga."}'::jsonb, '["会議の","時間が","三時からに","変更される","ことに","なりました。"]'::jsonb, NULL, NULL, '変更される (pasif) + ことになりました.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0e8f3ea0-d06b-485f-b595-3da47bb91bc0', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 審査の結果、当社の提案が採用される___。', '{"options":["ことにしました","ことになりました","せいです","ようになりました"],"translation":"Berdasarkan hasil seleksi, proposal perusahaan kami diputuskan untuk diterima.","sentence_template":"審査の結果、当社の提案が採用される[blank]。"}'::jsonb, '{"selected":"ことになりました"}'::jsonb, NULL, NULL, '採用されることになりました menyampaikan keputusan pihak klien/juri.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4887b98c-a1a6-4cd4-a535-0a81d9c845ce', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan pengumuman internal berikut. Apa perubahan pada kantin karyawan?', '{"options":[{"id":"opt_1","text":"Jam operasional kantin karyawan mulai minggu depan diputuskan sampai pukul 2 siang"},{"id":"opt_2","text":"Kantin karyawan buka sampai pukul 8 malam mulai minggu depan"},{"id":"opt_3","text":"Harga makanan di kantin karyawan akan naik minggu depan"},{"id":"opt_4","text":"Kantin karyawan akan tutup permanen minggu depan"}],"audio_text":"社員食堂の営業時間は、来週から午後二時までになることになりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'なることになりました menyampaikan perubahan aturan operasional.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1fa2c9f4-25bb-4c37-aaf3-801724c7cac8', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika berhalangan hadir, aturannya menghubungi lewat email paling lambat sehari sebelumnya."', '{"romaji":"Kesseki suru baai wa, zenjitsu made ni meeru de renraku suru koto ni natte imasu.","display_text":"欠席する場合は、前日までにメールで連絡することになっています。","phonetic_breakdown":["kes-se-ki-su-ru","ba-a-i-wa","zen-ji-tsu-ma-de-ni","mee-ru-de","ren-ra-ku-su-ru","ko-to-ni","nat-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"欠席する場合は、前日までにメールで連絡することになっています。"}'::jsonb, NULL, NULL, '連絡することになっています menyatakan prosedur izin resmi.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efc1b064-b1b0-4dc8-89cd-1019f2be15d2', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Pada pameran mendatang, diputuskan bahwa saya yang bertugas sebagai penerjemah lisan."', '{"romaji":"Kondo no tenjikai de wa watashi ga tsuuyaku o tsutomeru koto ni narimashita.","tokens":["私が","務めた","通訳を","ことに","展示会では","へ","務める","今度の","なりました。"],"target_translation":"Pada pameran mendatang, diputuskan bahwa saya yang bertugas sebagai penerjemah lisan."}'::jsonb, '["今度の","展示会では","私が","通訳を","務める","ことに","なりました。"]'::jsonb, NULL, NULL, '務める (tsutomeru, mengemban peran) + ことになりました.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3d404dd-6821-4626-ae0f-542344b04ba5', '941ed406-8042-4f58-a757-cdae8376701a', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: このマンションでは、ペットを飼ってはいけない___。', '{"options":["ことにしています","ことになっています","ばかりです","ようにしています"],"translation":"Di apartemen ini aturannya tidak boleh memelihara hewan peliharaan.","sentence_template":"このマンションでは、ペットを飼ってはいけない[blank]。"}'::jsonb, '{"selected":"ことになっています"}'::jsonb, NULL, NULL, '飼ってはいけないことになっています menjelaskan peraturan gedung.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3e6ec8d-4efd-5d30-92fa-52ba9808b029', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kereta berikutnya seharusnya tiba lima menit lagi."', '{"romaji":"Tsugi no densha wa gofungo ni tsuku hazu desu.","display_text":"次の電車は五分後に着くはずです。","phonetic_breakdown":["tsu-gi no","den-sha wa","go-fun-go ni","tsu-ku","ha-zu de-su"]}'::jsonb, '{"expected_transcript":"次の電車は五分後に着くはずです。"}'::jsonb, NULL, NULL, 'Ucapkan 五分後 (gofungo) dan 着くはずです dengan intonasi tegas namun sopan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f31ce1a0-11b4-5b54-a62f-e826a0b0f100', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak mungkin ada kesalahan pada data ini."', '{"romaji":"Kono deeta ni machigai ga aru hazu ga arimasen.","display_text":"このデータに間違いがあるはずがありません。","phonetic_breakdown":["ko-no dee-ta ni","ma-chi-ga-i ga","a-ru","ha-zu ga","a-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"このデータに間違いがあるはずがありません。"}'::jsonb, NULL, NULL, '～はずがありません menunjukkan keyakinan kuat bahwa sesuatu mustahil terjadi.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a8637362-127a-5267-a1d9-e7533168c674', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Padahal saya yakin sudah menyimpannya, tetapi filenya hilang."', '{"romaji":"Hozon shita hazu na noni, fairu ga kiete imasu.","display_text":"保存したはずなのに、ファイルが消えています。","phonetic_breakdown":["ho-zon shi-ta","ha-zu na no-ni","fa-i-ru ga","ki-e-te i-ma-su"]}'::jsonb, '{"expected_transcript":"保存したはずなのに、ファイルが消えています。"}'::jsonb, NULL, NULL, '保存する (hozon suru) berarti menyimpan data/file.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('77078e02-d53f-59ab-b540-437e8ce790c4', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Dokumen itu seharusnya ada di atas meja."', '{"romaji":"Sono shorui wa tsukue no ue ni aru hazu desu.","tokens":["あって","机の上に","ある","はずがありません。","その書類は","はずです。"],"target_translation":"Dokumen itu seharusnya ada di atas meja."}'::jsonb, '["その書類は","机の上に","ある","はずです。"]'::jsonb, NULL, NULL, 'ある + はずです menyatakan perkiraan lokasi berdasarkan ingatan/fakta.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31dda654-a390-5e90-a990-fe46ecdc0b05', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah berlatih keras, ujiannya seharusnya lulus."', '{"romaji":"Isshoukenmei renshuu shita node, goukaku dekiru hazu desu.","tokens":["合格できて","はずです。","合格できる","一生懸命","せいです。","練習したので、"],"target_translation":"Karena sudah berlatih keras, ujiannya seharusnya lulus."}'::jsonb, '["一生懸命","練習したので、","合格できる","はずです。"]'::jsonb, NULL, NULL, '合格できる (bisa lulus) + はずです.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fac4ebec-6104-5bb7-80dd-e04ac28eb2da', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Anak kecil tidak mungkin mengerti kanji sesulit ini."', '{"romaji":"Konna muzukashii kanji ga kodomo ni wakaru hazu ga arimasen.","tokens":["わかって","ありません。","はずが","こんな難しい漢字が","子どもに","わかる","はずです。"],"target_translation":"Anak kecil tidak mungkin mengerti kanji sesulit ini."}'::jsonb, '["こんな難しい漢字が","子どもに","わかる","はずが","ありません。"]'::jsonb, NULL, NULL, 'わかる + はずがありません menegaskan ketidakmungkinan logis.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('357249db-f9e1-46f5-bfe9-1afa80e21aa2', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau lewat jalan ini, seharusnya sampai di stasiun dalam sepuluh menit."', '{"romaji":"Kono michi o ikeba, juppun de eki ni tsuku hazu desu.","display_text":"この道を行けば、十分で駅に着くはずです。","phonetic_breakdown":["ko-no","mi-chi-o","i-ke-ba","jup-pun-de","e-ki-ni","tsu-ku","ha-zu-de-su"]}'::jsonb, '{"expected_transcript":"この道を行けば、十分で駅に着くはずです。"}'::jsonb, NULL, NULL, '着くはずです memberikan estimasi waktu yang logis.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eac7f768-e68d-4199-87db-7c918e177dd7', '9665eb31-9ed9-5bad-9c99-ba98331aef40', 'd1000019-0000-0000-0000-000000000014', 'writing', 'sentence_builder', 'Susun kalimat: "Soal sesulit itu tidak mungkin bisa dipecahkan oleh anak-anak."', '{"romaji":"Sonna muzukashii mondai ga, kodomo ni tokeru hazu ga nai.","tokens":["難しい","はずが","子供に","問題が、","を","そんな","ない。","解けた","解ける"],"target_translation":"Soal sesulit itu tidak mungkin bisa dipecahkan oleh anak-anak."}'::jsonb, '["そんな","難しい","問題が、","子供に","解ける","はずが","ない。"]'::jsonb, NULL, NULL, '解けるはずがない menyatakan ketidakmungkinan berdasarkan logika.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('592abe7e-238f-4db6-b9ce-0a5dbf2c747d', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan percakapan santai berikut. Apa kebiasaan baru pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara berhenti minum air putih karena sering lelah"},{"id":"opt_2","text":"Karena belakangan mudah lelah, pembicara berusaha minum dua liter air sehari"},{"id":"opt_3","text":"Pembicara hanya minum kopi saat merasa lelah"},{"id":"opt_4","text":"Dokter melarang pembicara minum terlalu banyak air"}],"audio_text":"最近疲れやすいので、一日に二リットルは水を飲むようにしているんです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '飲むようにしているんです menjelaskan upaya kesehatan dalam percakapan natural.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e03ad552-3bbc-4801-9c85-9066099e8eed', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya berusaha untuk tidak membicarakan keburukan orang lain."', '{"romaji":"Hito no waruguchi wa iwanai you ni shite imasu.","display_text":"人の悪口は言わないようにしています。","phonetic_breakdown":["hi-to-no","wa-ru-gu-chi-wa","i-wa-nai","you-ni","shi-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"人の悪口は言わないようにしています。"}'::jsonb, NULL, NULL, '言わないようにしています menyatakan prinsip perilaku yang dijaga.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('63cabc06-6c8c-4b71-ac0c-1d24f2122b67', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap hari Minggu saya membiasakan diri membersihkan kamar."', '{"romaji":"Maishuu nichiyoubi ni heya no souji o suru you ni shite imasu.","tokens":["する","が","毎週","した","日曜日に","部屋の","ように","しています。","掃除を"],"target_translation":"Setiap hari Minggu saya membiasakan diri membersihkan kamar."}'::jsonb, '["毎週","日曜日に","部屋の","掃除を","する","ように","しています。"]'::jsonb, NULL, NULL, '掃除をする + ようにしています.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a48a839-91e6-4fff-b20f-acaa9b537637', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 風邪をひかないように、冬は加湿器を___ようにしています。', '{"options":["つけた","つけよう","つけて","つける"],"translation":"Agar tidak terkena flu, saat musim dingin saya membiasakan menyalakan pelembap udara.","sentence_template":"風邪をひかないように、冬は加湿器を[blank]ようにしています。"}'::jsonb, '{"selected":"つける"}'::jsonb, NULL, NULL, 'つける (bentuk kamus) + ようにしています.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('60b7186b-825a-4155-a6d1-2e7a9b9a17c1', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Dengarkan kebiasaan kerja berikut. Mengapa pembicara selalu mencatat?', '{"options":[{"id":"opt_1","text":"Hanya mencatat hasil rapat jika diminta atasan"},{"id":"opt_2","text":"Merekam semua rapat tanpa mendengarkan pembicara"},{"id":"opt_3","text":"Selalu membiasakan mencatat di buku selama rapat agar tidak lupa"},{"id":"opt_4","text":"Tidak pernah membawa buku catatan saat rapat"}],"audio_text":"メモを取らずに聞くとすぐ忘れるので、打ち合わせ中は必ずノートに書くようにしています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '書くようにしています menyatakan tindakan rutin untuk mencegah lupa.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d54fdb7-1a8a-42c3-ada4-6e7593dc3332', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setiap bulan saya membiasakan menabung dalam jumlah yang tetap."', '{"romaji":"Maitsuki kimatta gaku o chokin suru you ni shite imasu.","display_text":"毎月決まった額を貯金するようにしています。","phonetic_breakdown":["mai-tsu-ki","ki-mat-ta","ga-ku-o","cho-kin-su-ru","you-ni","shi-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"毎月決まった額を貯金するようにしています。"}'::jsonb, NULL, NULL, '貯金するようにしています menyatakan kebiasaan finansial yang teratur.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('032ba851-fbf1-404f-8a07-e7d8841d2f18', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Tolong usahakan agar tidak menghilangkan dokumen penting."', '{"romaji":"Daiji na shorui o nakusanai you ni shite kudasai.","tokens":["大事な","なくした","ように","ください。","書類を","が","なくさない","して"],"target_translation":"Tolong usahakan agar tidak menghilangkan dokumen penting."}'::jsonb, '["大事な","書類を","なくさない","ように","して","ください。"]'::jsonb, NULL, NULL, 'なくさない (bentuk ない) + ようにしてください.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61dea9d2-eec6-47f4-a2af-405fe793ceec', '969da854-c6f4-4d72-8d62-592076573745', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 日本語の会話力を伸ばすため、間違いを恐れず___ようにしています。', '{"options":["話した","話せば","話す","話して"],"translation":"Untuk meningkatkan kemampuan berbicara bahasa Jepang, saya berusaha berbicara tanpa takut salah.","sentence_template":"日本語の会話力を伸ばすため、間違いを恐れず[blank]ようにしています。"}'::jsonb, '{"selected":"話す"}'::jsonb, NULL, NULL, '話す (bentuk kamus) + ようにしています.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a657d071-c59a-5004-b2d5-1fc18bbeca23', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Ubah ほめる (memuji) ke bentuk pasif: 発表がうまくいって、先生に ___ 。', '{"options":["ほめられました","ほめました","ほめさせました","ほめられましたか"],"translation":"Presentasinya berjalan lancar, sehingga saya dipuji oleh guru.","sentence_template":"発表がうまくいって、先生に [blank] 。"}'::jsonb, '{"selected":"ほめられました"}'::jsonb, NULL, NULL, 'Verba Golongan II ほめる -> buang る + られる -> ほめられました (dipuji).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5ca91520-a353-5fd3-9d63-48ce06b47600', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Ubah たのむ (meminta) ke bentuk pasif: 部長に急な仕事を ___ ました。', '{"options":["頼まれ","頼み","頼ませ","頼んで"],"translation":"Saya dimintai pekerjaan mendadak oleh kepala bagian.","sentence_template":"部長に急な仕事を [blank] ました。"}'::jsonb, '{"selected":"頼まれ"}'::jsonb, NULL, NULL, 'Verba Golongan I 頼む (tanomu) -> ubah vokal u ke a + れる -> 頼まれる (diminta).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a7134c2a-e509-5cb2-9d43-70dbbc0de0bb', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Pilih bentuk pasif dari くる (datang): 忙しいときに友達に ___ て困りました。', '{"options":["来られ","来させ","来","来て"],"translation":"Saat sedang sibuk, saya kedatangan teman dan merasa kerepotan.","sentence_template":"忙しいときに友達に [blank] て困りました。"}'::jsonb, '{"selected":"来られ"}'::jsonb, NULL, NULL, 'Bentuk pasif tidak beraturan dari 来る (kuru) adalah 来られる (korareru).', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9f625830-4ccf-5dad-9318-9796a5de0cb9', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Buku ini dibaca di seluruh dunia."', '{"romaji":"Kono hon wa sekaijuu de yomarete imasu.","tokens":["この本は","読んで","います。","読まれて","読ませて","世界中で"],"target_translation":"Buku ini dibaca di seluruh dunia."}'::jsonb, '["この本は","世界中で","読まれて","います。"]'::jsonb, NULL, NULL, '読む -> 読まれる (dibaca). 読まれています menunjukkan keadaan yang berlangsung luas.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('368a3906-e805-56be-a27d-0fecf12c45c5', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Saya dipuji oleh atasan."', '{"romaji":"Watashi wa joushi ni homeraremashita.","tokens":["私は","ほめられました。","ほめました。","上司に","上司を"],"target_translation":"Saya dipuji oleh atasan."}'::jsonb, '["私は","上司に","ほめられました。"]'::jsonb, NULL, NULL, 'Pelaku dalam kalimat pasif ditandai dengan partikel に (上司に).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d75fa00a-5574-5a8c-8250-61c86ab089e9', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Apa yang terjadi pada sepeda milik pembicara?', '{"options":[{"id":"opt_1","text":"Dipindahkan petugas ke tempat parkir lain"},{"id":"opt_2","text":"Bannya bocor saat diparkir di depan stasiun"},{"id":"opt_3","text":"Dicuri oleh seseorang saat diparkir di depan stasiun"},{"id":"opt_4","text":"Dipinjam oleh adiknya tanpa izin"}],"audio_text":"駅の前に止めておいた自転車が誰かに盗まれてしまいました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '誰かに盗まれてしまいました berarti telah dicuri oleh seseorang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a76b0b8b-f6cf-4e76-a54d-84d0edd53bf8', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 昨日、部長に企画書を___、とてもうれしかったです。', '{"options":["褒めさせて","褒めあって","褒めて","褒められて"],"translation":"Kemarin proposal saya dipuji oleh kepala bagian, saya senang sekali.","sentence_template":"昨日、部長に企画書を[blank]、とてもうれしかったです。"}'::jsonb, '{"selected":"褒められて"}'::jsonb, NULL, NULL, '褒める (kelompok 2) -> bentuk pasif 褒められる (dipuji).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('01275dd7-d1ae-40d2-a965-ee4c2a485ad6', '9732e753-78c3-50a3-b666-22a5adc66314', 'd1000019-0000-0000-0000-000000000015', 'writing', 'sentence_builder', 'Susun kalimat: "Produk ini digemari oleh orang-orang di seluruh dunia."', '{"romaji":"Kono seihin wa sekaijuu no hitobito ni aiyou sarete imasu.","tokens":["製品は","この","人々に","愛用して","愛用","います。","世界中の","されて","を"],"target_translation":"Produk ini digemari oleh orang-orang di seluruh dunia."}'::jsonb, '["この","製品は","世界中の","人々に","愛用","されて","います。"]'::jsonb, NULL, NULL, '愛用する -> 愛用されている (bentuk pasif berkelanjutan).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('415cbf6e-e5f7-41e1-a5ae-e016b5807570', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 田中さんが駅まで車で送ってくれた___、雨に濡れずに済みました。', '{"options":["せいで","によって","ばかりで","おかげで"],"translation":"Berkat Tanaka-san mengantar ke stasiun dengan mobil, saya tidak kehujanan.","sentence_template":"田中さんが駅まで車で送ってくれた[blank]、雨に濡れずに済みました。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, '送ってくれた + おかげで untuk hasil yang melegakan.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a779f9f-532a-41cc-a1c2-8e27535c12d3', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 天気が___おかげで、山の頂上から素晴らしい景色が見られました。', '{"options":["よかった","よかったな","いいの","いいな"],"translation":"Berkat cuaca yang bagus, saya bisa melihat pemandangan luar biasa dari puncak gunung.","sentence_template":"天気が[blank]おかげで、山の頂上から素晴らしい景色が見られました。"}'::jsonb, '{"selected":"よかった"}'::jsonb, NULL, NULL, 'Kata sifat い bentuk lampau (よかった) langsung diikuti おかげで.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('77d1b1e7-34e4-4a2a-a617-a3e0ab26e878', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan laporan efisiensi berikut. Apa dampak sistem baru tersebut?', '{"options":[{"id":"opt_1","text":"Sistem baru membuat pekerjaan input data lebih lama"},{"id":"opt_2","text":"Waktu input data tidak berubah setelah sistem baru dipasang"},{"id":"opt_3","text":"Perusahaan membatalkan penggunaan sistem baru"},{"id":"opt_4","text":"Berkat penerapan sistem baru, waktu input data berkurang menjadi kurang dari separuh"}],"audio_text":"新しいシステムを導入したおかげで、データ入力の時間が半分以下になりました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '導入したおかげで menekankan hasil positif dari inovasi.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1dd425e6-0d3e-42df-a3c7-53897e6e639e', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat berkonsultasi dengan senior, solusi yang baik berhasil ditemukan."', '{"romaji":"Senpai ni soudan shita okage de, yoi kaiketsusaku ga mitsukarimashita.","tokens":["先輩に","良い","相談した","せいで、","おかげで、","解決策が","を","見つかりました。"],"target_translation":"Berkat berkonsultasi dengan senior, solusi yang baik berhasil ditemukan."}'::jsonb, '["先輩に","相談した","おかげで、","良い","解決策が","見つかりました。"]'::jsonb, NULL, NULL, '相談した + おかげで.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37192821-56b9-4cdc-a275-13ea46ef13eb', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 毎日ストレッチを続けた___、肩こりがかなり軽くなりました。', '{"options":["おかげで","うちに","に対して","せいで"],"translation":"Berkat rutin melakukan peregangan setiap hari, pegal di bahu berkurang cukup banyak.","sentence_template":"毎日ストレッチを続けた[blank]、肩こりがかなり軽くなりました。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, '続けたおかげで menghubungkan usaha rutin dengan perbaikan kesehatan.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40b4adeb-0d26-48a9-89b2-000723bf3ff8', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat dukungan hangat dari Anda semua, saya bisa membuka toko baru."', '{"romaji":"Minasan no atatakai go-shien no okage de, atarashii mise o akemashita.","display_text":"皆さんの温かいご支援のおかげで、新しい店を開けました。","phonetic_breakdown":["mi-na-san-no","a-ta-ta-kai","go-shi-en-no","o-ka-ge-de","a-ta-ra-shii","mi-se-o","a-ke-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"皆さんの温かいご支援のおかげで、新しい店を開けました。"}'::jsonb, NULL, NULL, 'ご支援のおかげで sangat cocok untuk sambutan pembukaan usaha.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bfd12c6e-63a1-4225-8430-c735ae4ea4f7', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan refleksi pembicara berikut. Mengapa ia bisa presentasi dengan tenang?', '{"options":[{"id":"opt_1","text":"Berkat sudah melakukan gladi resik sebelumnya, bisa presentasi dengan tenang saat hari H"},{"id":"opt_2","text":"Merasa gugup saat presentasi karena lupa gladi resik"},{"id":"opt_3","text":"Presentasi hari H ditunda ke minggu depan"},{"id":"opt_4","text":"Gladi resik dibatalkan karena kekurangan waktu"}],"audio_text":"事前にリハーサルをしておいたおかげで、本番では落ち着いて発表できました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'しておいたおかげで memadukan persiapan dan hasil positif.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0cf42087-2a8e-47f7-81a0-251fe16de76a', '9d0c3218-19e8-4bd6-ac68-168e4350e79a', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat obat ini, batuk saya berhenti total."', '{"romaji":"Kono kusuri no okage de, seki ga sukkari tomarimashita.","tokens":["せいで、","この","咳が","おかげで、","を","止まりました。","薬の","すっかり"],"target_translation":"Berkat obat ini, batuk saya berhenti total."}'::jsonb, '["この","薬の","おかげで、","咳が","すっかり","止まりました。"]'::jsonb, NULL, NULL, 'Kata benda (この薬) + のおかげで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('54c6df2c-57a8-5221-9754-204d67125c2a', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk konteks budaya: 文化の違い ___ 、同じ言葉でも受け取り方が変わります。', '{"options":["によって","による","に対して","のおかげで"],"translation":"Tergantung perbedaan budaya, cara menangkap kata yang sama pun bisa berubah.","sentence_template":"文化の違い [blank] 、同じ言葉でも受け取り方が変わります。"}'::jsonb, '{"selected":"によって"}'::jsonb, NULL, NULL, '文化の違いによって berarti bergantung pada perbedaan budaya.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa72b794-f6a9-57ef-9993-9a4bf6a3a82a', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Uji ketelitian bentuk modifikasi nomina: 専門家 ___ 詳しい解説を聞きました。', '{"options":["による","によって","に対する","における"],"translation":"Saya mendengarkan penjelasan rinci oleh seorang ahli.","sentence_template":"専門家 [blank] 詳しい解説を聞きました。"}'::jsonb, '{"selected":"による"}'::jsonb, NULL, NULL, '詳しい解説 adalah frasa nomina sehingga memakai による.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85e7d1b2-119b-5ed9-9230-c001c1569d6e', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Pesan utama apa yang disampaikan pembicara kepada peserta menjelang ujian N3?', '{"options":[{"id":"opt_1","text":"Peserta sebaiknya berhenti belajar dua minggu sebelum ujian"},{"id":"opt_2","text":"Soal ujian tahun ini jauh lebih sulit daripada tahun lalu"},{"id":"opt_3","text":"Kemampuan pasti terbentuk lewat latihan rutin harian, jadi tetap percaya diri"},{"id":"opt_4","text":"Hasil ujian hanya bergantung pada hafalan kanji semata"}],"audio_text":"毎日の積み重ねによって実力は確実につきますから、本番まで自信を持って頑張ってください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '毎日の積み重ねによって実力は確実につきます berarti kemampuan pasti terbangun melalui akumulasi usaha setiap hari.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b3cc3a3-2480-5121-b7e6-3bc589bb883d', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Apa yang berubah pada jadwal kereta menurut pengumuman resmi ini?', '{"options":[{"id":"opt_1","text":"Kereta ekspres diganti menjadi kereta lokal gratis"},{"id":"opt_2","text":"Pintu masuk selatan stasiun ditutup sementara"},{"id":"opt_3","text":"Tiket kereta jarak jauh mengalami penyesuaian harga"},{"id":"opt_4","text":"Operasi kereta di sebagian jalur dihentikan sementara untuk pemeriksaan keselamatan akibat angin kencang"}],"audio_text":"強風による安全確認のため、一部区間で運転を見合わせています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '強風による安全確認のため、一部区間で運転を見合わせています adalah pengumuman resmi khas kereta Jepang.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('64630df8-0e30-574e-8cf6-cf2143120325', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Tergantung perusahaan, aturan pakaian kerjanya berbeda."', '{"romaji":"Kaisha ni yotte fukusou no ruuru ga chigaimasu.","tokens":["対して","よる","会社に","よって","服装のルールが","違います。"],"target_translation":"Tergantung perusahaan, aturan pakaian kerjanya berbeda."}'::jsonb, '["会社に","よって","服装のルールが","違います。"]'::jsonb, NULL, NULL, '会社によって + 違います menunjukkan perbedaan aturan antarperusahaan.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0cc0381c-4e3f-5742-9106-15d8fb308a62', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat usaha terus-menerus, saya siap menghadapi JLPT N3."', '{"romaji":"Hibi no doryoku ni yotte, enu san no shiken ni nozomu junbi ga dekimashita.","display_text":"日々の努力によって、N3の試験に臨む準備ができました。","phonetic_breakdown":["hi-bi no","do-ryo-ku ni","yot-te","e-nu san no","shi-ken ni no-zo-mu","jun-bi ga","de-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"日々の努力によって、N3の試験に臨む準備ができました。"}'::jsonb, NULL, NULL, '臨む (nozomu) berarti menghadapi (ujian/tantangan). Kalimat penutup yang mantap untuk menyelesaikan seluruh kurikulum N3!', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4cec3c1-4a2a-41b1-99ce-0d35b52d36f8', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 地域に___方言や習慣が違うのが、日本の面白さの一つです。', '{"options":["おける","よっての","よる","対する"],"translation":"Perbedaan dialek dan kebiasaan menurut daerah adalah salah satu hal menarik di Jepang.","sentence_template":"地域に[blank]方言や習慣が違うのが、日本の面白さの一つです。"}'::jsonb, '{"selected":"よる"}'::jsonb, NULL, NULL, 'Saat menerangkan kata benda di belakangnya, によって berubah menjadi による.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6669b1ac-1259-4fe7-bd6f-5a8cc648df6c', 'a367fad4-a7fd-51eb-a82f-007525796e71', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami berhasil menyelesaikan masalah melalui diskusi."', '{"romaji":"Hanashiai ni yotte mondai o kaiketsu suru koto ga dekimashita.","display_text":"話し合いによって問題を解決することができました。","phonetic_breakdown":["ha-na-shi-a-i-ni","yot-te","mon-dai-o","kai-ke-tsu-su-ru","ko-to-ga","de-ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"話し合いによって問題を解決することができました。"}'::jsonb, NULL, NULL, '話し合いによって menyatakan metode penyelesaian masalah.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc0dce68-56b1-575a-85f4-953d478d5612', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi kerja: 丁寧な仕事ぶりが上司に高く ___ しました。', '{"options":["評価","誤解","批判","延期"],"translation":"Cara kerja yang teliti mendapat penilaian tinggi dari atasan (aktif: atasan menilai tinggi).","sentence_template":"丁寧な仕事ぶりが上司に高く [blank] しました。"}'::jsonb, '{"selected":"評価"}'::jsonb, NULL, NULL, '評価 (hyouka) berarti penilaian/apresiasi. Bentuk pasifnya adalah 評価されました.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d837898b-abb0-5dcb-83dd-e30c245ae032', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'reading', 'fill_blank', 'Pilih kata untuk acara resmi: 来月、国際会議が東京で ___ されます。', '{"options":["開催","破壊","解決","発見"],"translation":"Bulan depan, konferensi internasional akan diselenggarakan di Tokyo.","sentence_template":"来月、国際会議が東京で [blank] されます。"}'::jsonb, '{"selected":"開催"}'::jsonb, NULL, NULL, '開催される (kaisai sareru) berarti diselenggarakan (untuk acara/konferensi).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c82bdea5-57f6-5baf-b3ae-05706a4e50f8', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita produk: この自動車は日本の工場で ___ されています。', '{"options":["製造","想像","放送","清掃"],"translation":"Mobil ini diproduksi di pabrik Jepang.","sentence_template":"この自動車は日本の工場で [blank] されています。"}'::jsonb, '{"selected":"製造"}'::jsonb, NULL, NULL, '製造される (seizou sareru) berarti diproduksi/dibuat di pabrik.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('af2ce788-fa88-5328-9be1-499539374f61', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'reading', 'fill_blank', 'Pilih kata untuk insiden harian: 満員電車の中で足を ___ しまいました。', '{"options":["踏まれて","押して","投げて","洗って"],"translation":"Di dalam kereta yang penuh sesak, kaki saya terinjak.","sentence_template":"満員電車の中で足を [blank] しまいました。"}'::jsonb, '{"selected":"踏まれて"}'::jsonb, NULL, NULL, '踏む (menginjak) -> bentuk pasif 踏まれる (diinjak).', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11aea64e-8acc-5c18-877a-6501850e0dec', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'listening', 'listening_choice', 'Berita apa yang disampaikan tentang bangunan bersejarah tersebut?', '{"options":[{"id":"opt_1","text":"Kastel itu dibangun sekitar 400 tahun lalu dan masih digemari wisatawan"},{"id":"opt_2","text":"Kastel itu akan direnovasi total mulai tahun depan"},{"id":"opt_3","text":"Kastel itu baru dibuka untuk umum bulan lalu"},{"id":"opt_4","text":"Kastel itu tutup sementara karena badai"}],"audio_text":"このお城はおよそ四百年前に建てられ、今でも多くの観光客に親しまれています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '四百年前に建てられ (dibangun 400 tahun lalu) dan 親しまれています (digemari/dicintai).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb4fef26-eac3-5230-86c7-937bdf14c445', 'a37e6061-234d-5f7e-88ef-5d252e066442', NULL, 'listening', 'listening_choice', 'Pengalaman kurang menyenangkan apa yang dialami pembicara kemarin?', '{"options":[{"id":"opt_1","text":"Ia kehilangan payung di dalam bus"},{"id":"opt_2","text":"Ia kehujanan tiba-tiba di jalan pulang sehingga sepatu barunya basah kuyup"},{"id":"opt_3","text":"Ia terpeleset di tangga stasiun karena lantai licin"},{"id":"opt_4","text":"Sepatu barunya tertukar di ruang pertemuan"}],"audio_text":"帰り道で急に雨に降られて、新しい靴がびしょ濡れになってしまいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '雨に降られて (kehujanan, bentuk pasif penderitaan) membuat sepatu barunya basah kuyup.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('05ca8c93-a8f2-4b04-9fe6-07c1b0560047', 'a37e6061-234d-5f7e-88ef-5d252e066442', 'd1000019-0000-0000-0000-000000000015', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この歴史的な建物は、百年前に有名な建築家によって___されました。', '{"options":["設計","散歩","欠席","予約"],"translation":"Bangunan bersejarah ini dirancang oleh arsitek terkenal seratus tahun lalu.","sentence_template":"この歴史的な建物は、百年前に有名な建築家によって[blank]されました。"}'::jsonb, '{"selected":"設計"}'::jsonb, NULL, NULL, '設計する -> bentuk pasif 設計される (dirancang); oleh pelaku penciptaan ditandai によって.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51165c0c-2972-43a4-8e20-cac1133d7a04', 'a37e6061-234d-5f7e-88ef-5d252e066442', 'd1000019-0000-0000-0000-000000000015', 'listening', 'listening_choice', 'Dengarkan keluhan berikut. Apa yang dialami pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara tidak sengaja menginjak kaki penumpang lain"},{"id":"opt_2","text":"Kaki pembicara terinjak di dalam kereta yang penuh sesak sehingga sangat sakit"},{"id":"opt_3","text":"Pembicara terjatuh di tangga stasiun"},{"id":"opt_4","text":"Kereta hari ini sangat lengang sehingga bisa duduk nyaman"}],"audio_text":"満員電車の中で足を踏まれて、本当に痛かったです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '足を踏まれて adalah bentuk pasif penderitaan (meiwaku no ukemi) yang menekankan ketidaknyamanan korban.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('41fc2c54-4933-5df5-9ce2-afd268b04016', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat layanan: お客様からの問い合わせに迅速に ___ します。', '{"options":["対応","注文","配達","見学"],"translation":"Saya menanggapi pertanyaan dari pelanggan dengan cepat.","sentence_template":"お客様からの問い合わせに迅速に [blank] します。"}'::jsonb, '{"selected":"対応"}'::jsonb, NULL, NULL, '対応する (taiou suru) berarti menangani atau merespons pertanyaan/keluhan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('936bf770-5f52-5ea1-b1a7-cb35dea6057b', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk sikap kerja: 誰にでも丁寧な ___ で接することが大切です。', '{"options":["態度","温度","速度","角度"],"translation":"Penting untuk berinteraksi dengan sikap yang sopan kepada siapa pun.","sentence_template":"誰にでも丁寧な [blank] で接することが大切です。"}'::jsonb, '{"selected":"態度"}'::jsonb, NULL, NULL, '態度 (taido) berarti sikap atau perilaku.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6d74919-6d9d-548d-a782-7feedacc515f', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat rapat: 新しい企画について、社員から多くの ___ が寄せられました。', '{"options":["意見","天気","住所","費用"],"translation":"Terkait rencana baru, banyak pendapat masuk dari para karyawan.","sentence_template":"新しい企画について、社員から多くの [blank] が寄せられました。"}'::jsonb, '{"selected":"意見"}'::jsonb, NULL, NULL, '意見 (iken) berarti pendapat atau masukan.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e93fb1d0-f790-55fd-be36-763cb0a90f7e', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'reading', 'fill_blank', 'Pilih kata untuk perbandingan data: 去年と今年の売上を ___ してみましょう。', '{"options":["比較","説明","招待","翻訳"],"translation":"Mari kita coba membandingkan penjualan tahun lalu dan tahun ini.","sentence_template":"去年と今年の売上を [blank] してみましょう。"}'::jsonb, '{"selected":"比較"}'::jsonb, NULL, NULL, '比較する (hikaku suru) berarti membandingkan.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55d930ae-33ca-503e-964c-0e5804eae617', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'listening', 'listening_choice', 'Apa yang sangat ditekankan oleh manajer toko dalam audio ini?', '{"options":[{"id":"opt_1","text":"Memberi panduan dengan jelas dan tersenyum kepada pelanggan baru"},{"id":"opt_2","text":"Menawarkan kartu keanggotaan kepada setiap pengunjung"},{"id":"opt_3","text":"Memastikan kasir tidak pernah antre lebih dari tiga menit"},{"id":"opt_4","text":"Menjaga kebersihan area parkir sebelum toko buka"}],"audio_text":"初めて来店されたお客様にも、わかりやすく笑顔でご案内するよう心がけてください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'わかりやすく笑顔でご案内する berarti memandu dengan jelas dan senyuman.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('01e5bf4e-2299-56ff-8f50-82ed2ab635ee', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', NULL, 'listening', 'listening_choice', 'Bagaimana hasil survei kepuasan pelanggan bulan ini?', '{"options":[{"id":"opt_1","text":"Pelanggan mengeluhkan harga produk yang terlalu tinggi"},{"id":"opt_2","text":"Kualitas produk memuaskan, tetapi kecepatan pengiriman diminta diperbaiki"},{"id":"opt_3","text":"Sebagian besar pelanggan puas dengan kecepatan pengiriman"},{"id":"opt_4","text":"Survei bulan ini belum selesai direkapitulasi"}],"audio_text":"商品の品質には満足という声が多い一方で、配送のスピードについては改善を求める意見がありました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '品質には満足 (puas dengan kualitas) dan 配送のスピードについては改善を求める (meminta perbaikan kecepatan pengiriman).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d2682620-7854-44a6-9643-f2a6f62cb95c', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: お客様からの___に対して、誠実かつ迅速に対応します。', '{"options":["卒業","休暇","散歩","苦情"],"translation":"Terhadap keluhan dari pelanggan, kami menanggapi dengan tulus dan cepat.","sentence_template":"お客様からの[blank]に対して、誠実かつ迅速に対応します。"}'::jsonb, '{"selected":"苦情"}'::jsonb, NULL, NULL, '苦情 (kujou) berarti keluhan atau komplain pelanggan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42eb547b-eb59-432a-82b9-cfe02b5c2fc4', 'acc54292-6ef6-588a-9e13-4074cfb3d5fa', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Dengarkan perbandingan berikut. Bagaimana perbedaan sifat kakak dan adik?', '{"options":[{"id":"opt_1","text":"Adik jauh lebih suka berpesta dibanding kakak"},{"id":"opt_2","text":"Kakak sangat pendiam dan tidak suka bertemu orang"},{"id":"opt_3","text":"Kakak dan adik memiliki sifat yang persis sama"},{"id":"opt_4","text":"Berbeda dengan kakak laki-laki yang mudah bergaul, adik sangat tenang dan suka membaca"}],"audio_text":"兄が社交的なのに対して、弟はとても静かで読書が好きな性格です。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '～のに対して digunakan untuk membandingkan dua hal yang kontras.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('33c44ec0-cb0f-41d3-9422-56d5b9096997', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan pengakuan berikut. Mengapa berat badan pembicara naik?', '{"options":[{"id":"opt_1","text":"Pembicara sama sekali tidak menyukai makanan manis"},{"id":"opt_2","text":"Makanan manis membuat tubuh pembicara lebih bugar"},{"id":"opt_3","text":"Berat badan turun drastis karena tidak makan makanan manis"},{"id":"opt_4","text":"Berat badan agak naik belakangan ini gara-gara terlalu banyak makan makanan manis"}],"audio_text":"甘いものを食べすぎたせいで、最近少し体重が増えてしまいました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '食べすぎたせいで menyatakan penyesalan atas sebab yang dibuat sendiri.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7867c2ac-a99e-4b2e-94fa-8c337d0683d0', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara salah posisi tidur, leher saya sakit dan tidak bisa menoleh."', '{"romaji":"Nechigaeta sei de, kubi ga itakute mawarimasen.","display_text":"寝違えたせいで、首が痛くて回りません。","phonetic_breakdown":["ne-chi-ga-e-ta","sei-de","ku-bi-ga","i-ta-ku-te","ma-wa-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"寝違えたせいで、首が痛くて回りません。"}'::jsonb, NULL, NULL, '寝違えたせいで sangat alami dalam percakapan sehari-hari.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78367706-2bc1-4a84-b250-59069c47e07f', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara baterai ponsel habis, saya tidak bisa menghubungi."', '{"romaji":"Keitai no juuden ga kireta sei de, renraku ga dekimasen deshita.","tokens":["せいで、","を","充電が","切れた","携帯の","おかげで、","連絡が","できませんでした。"],"target_translation":"Gara-gara baterai ponsel habis, saya tidak bisa menghubungi."}'::jsonb, '["携帯の","充電が","切れた","せいで、","連絡が","できませんでした。"]'::jsonb, NULL, NULL, '切れた (bentuk lampau biasa) + せいで.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f300a00-98e7-4d9d-8def-930caa7a2383', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 説明が___せいで、参加者の間に誤解が生じてしまいました。', '{"options":["不十分","不十分だ","不十分な","不十分の"],"translation":"Gara-gara penjelasan yang kurang memadai, timbul kesalahpahaman di antara peserta.","sentence_template":"説明が[blank]せいで、参加者の間に誤解が生じてしまいました。"}'::jsonb, '{"selected":"不十分な"}'::jsonb, NULL, NULL, '不十分 adalah kata sifat な, sehingga menjadi 不十分なせいで.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9aacde4f-51dc-4f90-bf9e-56c0ef2a78ef', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan keluhan di kantor berikut. Apa yang diduga menjadi penyebab sakit kepala?', '{"options":[{"id":"opt_1","text":"Mungkin karena AC terlalu dingin, sejak tadi kepalanya agak pusing"},{"id":"opt_2","text":"Ruangan terlalu panas sehingga AC perlu dinyalakan lebih kuat"},{"id":"opt_3","text":"Sakit kepala pembicara sudah sembuh sejak tadi"},{"id":"opt_4","text":"Pembicara merasa sangat nyaman dengan suhu AC sekarang"}],"audio_text":"冷房が強すぎるせいか、さっきから少し頭痛がするんです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '強すぎるせいか menyatakan dugaan penyebab yang tidak nyaman.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d46c95a-5588-44ba-a9bc-1e0a8fe85cec', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Gara-gara menulis terburu-buru, tulisan saya jadi sangat berantakan."', '{"romaji":"Isoide kaita sei de, ji ga totemo kitanaku natte shimaimashita.","display_text":"急いで書いたせいで、字がとても汚くなってしまいました。","phonetic_breakdown":["i-so-i-de","ka-i-ta","sei-de","ji-ga","to-te-mo","ki-ta-na-ku","nat-te-shi-ma-i-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"急いで書いたせいで、字がとても汚くなってしまいました。"}'::jsonb, NULL, NULL, '書いたせいで menunjukkan sebab hasil tulisan yang kurang rapi.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74dcb4c9-fda9-4fda-a9ab-ccddb0675316', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'writing', 'sentence_builder', 'Susun kalimat: "Gara-gara hujan, festival kembang api yang dinanti-nantikan dibatalkan."', '{"romaji":"Ame no sei de, tanoshimi ni shite ita hanabi taikai ga chuushi ni narimashita.","tokens":["なりました。","を","雨の","せいで、","楽しみにしていた","中止に","花火大会が","おかげで、"],"target_translation":"Gara-gara hujan, festival kembang api yang dinanti-nantikan dibatalkan."}'::jsonb, '["雨の","せいで、","楽しみにしていた","花火大会が","中止に","なりました。"]'::jsonb, NULL, NULL, '雨のせいで mengekspresikan kekecewaan akibat hujan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6bbb84b8-9437-404c-9080-c5d0a4e99185', 'b365f7af-efc1-4d00-8e32-718699de562c', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 確認を怠った___、お客様にご迷惑をかけてしまいました。', '{"options":["せいで","おかげで","によって","うちに"],"translation":"Karena lalai melakukan pengecekan, saya telah merepotkan pelanggan.","sentence_template":"確認を怠った[blank]、お客様にご迷惑をかけてしまいました。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, '怠った (okotatta, lalai) + せいで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b67f29f8-0df0-5a73-bf40-81b769b764a5', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'listening', 'listening_choice', 'Apa yang membuat pembicara heran tentang kuncinya?', '{"options":[{"id":"opt_1","text":"Ia lupa membawa tasnya dari kantor"},{"id":"opt_2","text":"Saku tasnya robek di jalan pulang"},{"id":"opt_3","text":"Ia yakin sudah menaruhnya di saku tas, tetapi tidak ketemu di mana pun"},{"id":"opt_4","text":"Ia salah membawa kunci milik rekan kerjanya"}],"audio_text":"確かにかばんのポケットに入れたはずなのに、どこを探しても見つかりません。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '～たはずなのに mengekspresikan keheranan karena kenyataan berbeda dari keyakinan.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('99f71e44-5d4f-54b2-8c1a-6dbf4219ea63', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'listening', 'listening_choice', 'Mengapa pembicara yakin acara hari ini akan ramai?', '{"options":[{"id":"opt_1","text":"Karena tiketnya dibagikan gratis di stasiun"},{"id":"opt_2","text":"Karena pembicara utamanya adalah aktor terkenal"},{"id":"opt_3","text":"Karena ruang acaranya berukuran sangat kecil"},{"id":"opt_4","text":"Karena pendaftar awal sudah melebihi dua ratus orang"}],"audio_text":"事前申し込みが二百人を超えていたので、会場は満席になるはずです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '事前申し込みが二百人を超えていたので berarti karena pendaftaran awal melebihi 200 orang.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d192b05-b2d0-5460-99de-fce0ce1f919c', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'listening', 'listening_choice', 'Mengapa pembicara meragukan kabar bahwa restoran itu tutup?', '{"options":[{"id":"opt_1","text":"Karena hari libur tetapnya hari Selasa, jadi tidak mungkin tutup hari Rabu"},{"id":"opt_2","text":"Karena ia baru saja makan di sana satu jam lalu"},{"id":"opt_3","text":"Karena restoran itu buka dua puluh empat jam setiap hari"},{"id":"opt_4","text":"Karena pemiliknya tidak pernah mengambil hari libur"}],"audio_text":"火曜日が定休日だから、今日の水曜日に閉まっているはずがありませんよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '火曜日が定休日だから、今日の水曜日に閉まっているはずがありません berarti liburnya Selasa, tidak mungkin tutup hari Rabu.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('facf6665-61dc-5352-b0bd-9ee793553b58', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'reading', 'fill_blank', 'Pilih pola ekspektasi tak terpenuhi: 三時に着く ___ なのに、まだ到着しません。', '{"options":["はず","おかげ","せい","うち"],"translation":"Padahal seharusnya tiba pukul tiga, tetapi belum juga datang.","sentence_template":"三時に着く [blank] なのに、まだ到着しません。"}'::jsonb, '{"selected":"はず"}'::jsonb, NULL, NULL, '～はずなのに berarti ''padahal seharusnya...''.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0379e01d-4f10-5a60-89da-7b733034b4cc', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'reading', 'fill_blank', 'Lengkapi bentuk lampau dugaan: 彼は今日休むと聞いていたので、来ない ___ でした。', '{"options":["はず","こと","よう","ため"],"translation":"Karena saya dengar dia libur hari ini, seharusnya dia tidak datang.","sentence_template":"彼は今日休むと聞いていたので、来ない [blank] でした。"}'::jsonb, '{"selected":"はず"}'::jsonb, NULL, NULL, '～はずでした menyatakan ekspektasi sebelumnya yang ternyata berbeda.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d446e75-1f7d-56b1-97c6-c229a3a4f003', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', NULL, 'reading', 'fill_blank', 'Pilih bentuk verba yang benar: 説明書をよく読めば、誰でも使える ___ です。', '{"options":["はず","せい","ばかり","うち"],"translation":"Jika membaca buku panduan dengan baik, siapa pun seharusnya bisa memakainya.","sentence_template":"説明書をよく読めば、誰でも使える [blank] です。"}'::jsonb, '{"selected":"はず"}'::jsonb, NULL, NULL, '使える (bisa memakai) + はずです menyatakan kesimpulan logis.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f57f591e-80f4-4e93-a5a4-1b372a82ebb3', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', 'd1000019-0000-0000-0000-000000000014', 'listening', 'listening_choice', 'Dengarkan komentar di kantor berikut. Mengapa pembicara merasa heran?', '{"options":[{"id":"opt_1","text":"Merasa heran karena merasa seharusnya sudah mengirim email kemarin, tetapi belum ada balasan"},{"id":"opt_2","text":"Sudah menerima balasan email sejak kemarin"},{"id":"opt_3","text":"Sengaja tidak mengirim email kepada lawan bicara"},{"id":"opt_4","text":"Baru akan mengirim email besok pagi"}],"audio_text":"おかしいですね。昨日メールを送ったはずなのに、まだ返事が来ません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '送ったはずなのに menyatakan ketidaksesuaian antara perkiraan/ingatan dengan kenyataan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4026517f-6742-4382-b6f6-dec6ea2df9de', 'b4ece5a6-ac40-5598-9558-bdb3e313d439', 'd1000019-0000-0000-0000-000000000014', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 今日は祝日なので、銀行は___はずです。', '{"options":["休みな","休みだ","休みの","休み"],"translation":"Karena hari ini hari libur nasional, bank seharusnya tutup.","sentence_template":"今日は祝日なので、銀行は[blank]はずです。"}'::jsonb, '{"selected":"休みの"}'::jsonb, NULL, NULL, 'Kata benda (休み) memerlukan の sebelum はず -> 休みのはずです.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ff561ba-b11a-5d27-8320-184d9dd69b09', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kereta: 人身事故があり、電車が30分 ___ しています。', '{"options":["遅延","到着","出発","予約"],"translation":"Terjadi kecelakaan di jalur rel, sehingga kereta mengalami keterlambatan 30 menit.","sentence_template":"人身事故があり、電車が30分 [blank] しています。"}'::jsonb, '{"selected":"遅延"}'::jsonb, NULL, NULL, '遅延 (chien) berarti keterlambatan jadwal transportasi umum.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('34ce8489-ac7c-5384-b254-b3cb00a31a56', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk penerbangan: 大雪で飛行機が ___ になりました。', '{"options":["欠航","満席","搭乗","通過"],"translation":"Karena salju lebat, penerbangan dibatalkan.","sentence_template":"大雪で飛行機が [blank] になりました。"}'::jsonb, '{"selected":"欠航"}'::jsonb, NULL, NULL, '欠航 (kekkou) berarti pembatalan penerbangan atau pelayaran kapal.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57818ce5-008c-58b5-b6a9-bcff3641c4a5', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang kondisi tubuh: 昨日は二時間しか寝られず、ひどい ___ です。', '{"options":["寝不足","満腹","健康","余裕"],"translation":"Kemarin saya hanya bisa tidur dua jam, jadi sangat kurang tidur.","sentence_template":"昨日は二時間しか寝られず、ひどい [blank] です。"}'::jsonb, '{"selected":"寝不足"}'::jsonb, NULL, NULL, '寝不足 (nebusoku) berarti kurang tidur.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('199453d9-6587-5454-bace-67d532485afb', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk lalu lintas: 連休の初日なので、高速道路がひどく ___ しています。', '{"options":["渋滞","整理","工事","案内"],"translation":"Karena hari pertama libur panjang, jalan tol sangat macet.","sentence_template":"連休の初日なので、高速道路がひどく [blank] しています。"}'::jsonb, '{"selected":"渋滞"}'::jsonb, NULL, NULL, '渋滞 (juutai) berarti kemacetan lalu lintas.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('099e1744-7144-58b5-bf65-ea715f83f8d9', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'listening', 'listening_choice', 'Masalah teknis apa yang sedang terjadi di kantor?', '{"options":[{"id":"opt_1","text":"Gangguan jaringan internal sehingga tidak bisa mengirim email"},{"id":"opt_2","text":"Listrik di seluruh gedung padam sejak pagi"},{"id":"opt_3","text":"Mesin fotokopi rusak karena kertas tersangkut"},{"id":"opt_4","text":"Pendingin ruangan di ruang rapat tidak berfungsi"}],"audio_text":"朝から社内のネットワークに障害が発生し、メールが送れない状態が続いています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ネットワークに障害が発生し、メールが送れない berarti terjadi gangguan jaringan sehingga tidak dapat mengirim email.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d8e10ba1-9dac-50ef-816e-1a1e37309146', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', NULL, 'listening', 'listening_choice', 'Mengapa pembicara tidak bisa tidur nyenyak semalam?', '{"options":[{"id":"opt_1","text":"Karena kamar apartemennya terlalu panas"},{"id":"opt_2","text":"Karena suara bising pekerjaan konstruksi di luar pada tengah malam"},{"id":"opt_3","text":"Karena ia minum terlalu banyak kopi sebelum tidur"},{"id":"opt_4","text":"Karena telepon genggamnya berbunyi terus-menerus"}],"audio_text":"夜中に外で工事の騒音がひどくて、何度も目が覚めてしまいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '工事の騒音がひどくて berarti suara bising konstruksi sangat parah.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3298e204-88eb-4127-b337-9ad164469797', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 高速道路の___のせいで、バスが一時間も遅れました。', '{"options":["感謝","合格","応援","渋滞"],"translation":"Gara-gara kemacetan di jalan tol, bus terlambat sampai satu jam.","sentence_template":"高速道路の[blank]のせいで、バスが一時間も遅れました。"}'::jsonb, '{"selected":"渋滞"}'::jsonb, NULL, NULL, '渋滞 (juutai) berarti kemacetan lalu lintas, sesuai dengan dampak negatif せいで.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23245e90-7f1c-44b7-9306-0d44ae5a6820', 'b71e2a85-c9f0-5242-b443-d72a6a75acdb', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan berita cuaca berikut. Mengapa sebagian kereta berhenti beroperasi?', '{"options":[{"id":"opt_1","text":"Hujan lebat semalam membantu membersihkan sungai"},{"id":"opt_2","text":"Akibat hujan lebat semalam, sebagian kereta berhenti beroperasi karena air sungai naik"},{"id":"opt_3","text":"Kereta berhenti beroperasi karena jadwal perawatan rutin"},{"id":"opt_4","text":"Semua kereta beroperasi normal meski hujan lebat semalam"}],"audio_text":"昨夜の大雨のせいで、川の水位が上がって一部の電車が運休しています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '大雨のせいで menyatakan penyebab negatif gangguan transportasi.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3bb04865-74d2-55a1-926f-5d503a0cc2ad', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya membiasakan diri minum dua liter air setiap hari."', '{"romaji":"Mainichi mizu o ni rittoru nomu you ni shite imasu.","display_text":"毎日水を二リットル飲むようにしています。","phonetic_breakdown":["mai-ni-chi","mi-zu o","ni rit-to-ru","no-mu","you ni","shi-te i-ma-su"]}'::jsonb, '{"expected_transcript":"毎日水を二リットル飲むようにしています。"}'::jsonb, NULL, NULL, 'Perhatikan pelafalan vokal panjang pada ように (you ni) dan konsonan ganda pada リットル (rittoru).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d156af82-91b7-5667-82a6-794b3059d0e3', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Usahakanlah untuk tidak melupakan kartu identitas."', '{"romaji":"Shainshou o wasurenai you ni shite kudasai.","display_text":"社員証を忘れないようにしてください。","phonetic_breakdown":["sha-in-shou o","wa-su-re-na-i","you ni","shi-te","ku-da-sa-i"]}'::jsonb, '{"expected_transcript":"社員証を忘れないようにしてください。"}'::jsonb, NULL, NULL, '社員証 (shainshou) berarti kartu tanda pegawai. Pola ～ないようにしてください digunakan untuk imbauan sopan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2947e56e-4de7-5028-a667-3ed7562d68ad', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai bulan ini saya berusaha memakai bahasa Jepang di kantor."', '{"romaji":"Kongetsu kara shokuba de nihongo o tsukau you ni shite imasu.","display_text":"今月から職場で日本語を使うようにしています。","phonetic_breakdown":["kon-ge-tsu ka-ra","sho-ku-ba de","ni-hon-go o","tsu-ka-u","you ni","shi-te i-ma-su"]}'::jsonb, '{"expected_transcript":"今月から職場で日本語を使うようにしています。"}'::jsonb, NULL, NULL, '職場 (shokuba) berarti tempat kerja. Ucapkan 使うように secara mengalir.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d5f6d06f-e849-50f4-ac0b-56a560b581a6', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha tidur sebelum jam sebelas malam."', '{"romaji":"Yoru juuichiji mae ni neru you ni shite imasu.","tokens":["しています。","寝る","ように","夜十一時前に","寝て","寝た"],"target_translation":"Saya berusaha tidur sebelum jam sebelas malam."}'::jsonb, '["夜十一時前に","寝る","ように","しています。"]'::jsonb, NULL, NULL, 'Gunakan bentuk kamus 寝る sebelum ようにしています.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4342fbc-14c9-5cf2-8658-f288b01e5ff6', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Usahakan untuk mencatat hal penting saat rapat."', '{"romaji":"Kaigi no toki wa daijina koto o memo suru you ni shite kudasai.","tokens":["してください。","メモした","メモする","大事なことを","なります。","ように","会議のときは"],"target_translation":"Usahakan untuk mencatat hal penting saat rapat."}'::jsonb, '["会議のときは","大事なことを","メモする","ように","してください。"]'::jsonb, NULL, NULL, 'メモする (mencatat) dalam bentuk kamus diikuti ようにしてください membentuk instruksi sopan.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('676641d9-7742-5f08-8b3f-8ccb0c98cb83', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha tidak menggunakan ponsel sebelum tidur."', '{"romaji":"Neru mae ni sumaho o minai you ni shite imasu.","tokens":["見る","見ます","ように","寝る前に","しています。","スマホを","見ない"],"target_translation":"Saya berusaha tidak menggunakan ponsel sebelum tidur."}'::jsonb, '["寝る前に","スマホを","見ない","ように","しています。"]'::jsonb, NULL, NULL, 'Bentuk-NAI 見ない + ようにしています menyatakan usaha konsisten menghindari layar ponsel sebelum tidur.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b8065153-b494-4eee-8e99-07b68e46b0a7', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya membiasakan diri makan banyak sayuran."', '{"romaji":"Yasai o takusan taberu you ni shite imasu.","display_text":"野菜をたくさん食べるようにしています。","phonetic_breakdown":["ya-sa-i-o","ta-ku-san","ta-be-ru","you-ni","shi-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"野菜をたくさん食べるようにしています。"}'::jsonb, NULL, NULL, '食べるようにしています menandakan kebiasaan pola makan sehat yang konsisten.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('622c401c-4787-42f4-a82f-53ad85af1c89', 'b9417a14-d041-510d-9efe-e8e043b82fcb', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha agar tidak terlalu banyak minum minuman manis."', '{"romaji":"Amai nomimono o nomisuginai you ni shite imasu.","tokens":["飲み物を","ように","飲みすぎた","飲みすぎない","して","甘い","います。","へ"],"target_translation":"Saya berusaha agar tidak terlalu banyak minum minuman manis."}'::jsonb, '["甘い","飲み物を","飲みすぎない","ように","して","います。"]'::jsonb, NULL, NULL, '飲みすぎない (bentuk ない) + ようにしています.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5151b84f-bfcb-52bc-8b61-6e7283864500', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan menikah bulan depan."', '{"romaji":"Raigetsu kekkon suru koto ni narimashita.","display_text":"来月結婚することになりました。","phonetic_breakdown":["ra-i-ge-tsu","kek-kon su-ru","ko-to ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"来月結婚することになりました。"}'::jsonb, NULL, NULL, 'Dalam bahasa Jepang, ～ことになりました sering dipakai untuk mengumumkan pernikahan secara rendah hati seolah hasil kesepakatan bersama.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb98a2fe-4f37-5864-8683-e85625508c93', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapat dijadwalkan dimulai pada pukul dua."', '{"romaji":"Kaigi wa niji kara hajimaru koto ni natte imasu.","display_text":"会議は二時から始まることになっています。","phonetic_breakdown":["ka-i-gi wa","ni-ji ka-ra","ha-ji-ma-ru","ko-to ni","nat-te i-ma-su"]}'::jsonb, '{"expected_transcript":"会議は二時から始まることになっています。"}'::jsonb, NULL, NULL, '～ことになっています menunjukkan jadwal yang sudah ditetapkan sebelumnya.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9221ac87-fad8-5322-9788-2190f5c0e192', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa saya akan menjadi penanggung jawab klien ini."', '{"romaji":"Watashi ga kochira no okyakusama o tantou suru koto ni narimashita.","display_text":"私がこちらのお客様を担当することになりました。","phonetic_breakdown":["wa-ta-shi ga","ko-chi-ra no","o-kya-ku-sa-ma o","tan-tou su-ru","ko-to ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"私がこちらのお客様を担当することになりました。"}'::jsonb, NULL, NULL, 'Ungkapan sopan yang sangat lazim saat memperkenalkan diri sebagai PIC baru kepada klien.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('672ba820-331b-5113-96ed-4e75b0c1bb55', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa mulai bulan depan saya bekerja di Tokyo."', '{"romaji":"Raigetsu kara Toukyou de hataraku koto ni narimashita.","tokens":["ことに","なりました。","働いて","来月から","東京で","働く","しました。"],"target_translation":"Diputuskan bahwa mulai bulan depan saya bekerja di Tokyo."}'::jsonb, '["来月から","東京で","働く","ことに","なりました。"]'::jsonb, NULL, NULL, '働く (bentuk kamus) + ことになりました menyatakan penempatan kerja yang diputuskan kantor.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37bb58ca-7213-57fc-83a5-7773c534a654', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Di perpustakaan ini aturannya dilarang menelepon."', '{"romaji":"Kono toshokan de wa denwa o shinai koto ni natte imasu.","tokens":["なっています。","する","ことに","ように","この図書館では","電話を","しない"],"target_translation":"Di perpustakaan ini aturannya dilarang menelepon."}'::jsonb, '["この図書館では","電話を","しない","ことに","なっています。"]'::jsonb, NULL, NULL, '電話をしない + ことになっています menyatakan aturan larangan yang berlaku.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6577185-d597-5a1e-bda9-fca17391f3e7', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Diputuskan bahwa acara hari Minggu dibatalkan."', '{"romaji":"Nichiyoubi no ibento wa chuushi ni naru koto ni narimashita.","tokens":["なる","ことに","なった","中止に","なりました。","日曜日のイベントは","します。"],"target_translation":"Diputuskan bahwa acara hari Minggu dibatalkan."}'::jsonb, '["日曜日のイベントは","中止に","なる","ことに","なりました。"]'::jsonb, NULL, NULL, '中止になる (menjadi batal) + ことになりました.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9eeaa34-3b79-4f89-9632-7eb99d212eb1', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Diputuskan bahwa mulai tahun depan saya akan bekerja di kantor pusat Tokyo."', '{"romaji":"Rainen kara Toukyou no honsha de hataraku koto ni narimashita.","display_text":"来年から東京の本社で働くことになりました。","phonetic_breakdown":["rai-nen-ka-ra","tou-kyou-no","hon-sha-de","ha-ta-ra-ku","ko-to-ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"来年から東京の本社で働くことになりました。"}'::jsonb, NULL, NULL, '働くことになりました sangat lazim dipakai saat mengabarkan penugasan baru dengan nada rendah hati.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b8e98ce4-3e51-4286-afbc-66351e3cd48b', 'ba66eaca-627c-54c6-8869-e45b8070cb2e', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Karena topan, acara besok diputuskan untuk ditunda."', '{"romaji":"Taifuu no tame, ashita no ibento wa enki suru koto ni narimashita.","tokens":["明日の","延期します","ことに","延期する","イベントは","なりました。","が","台風のため、"],"target_translation":"Karena topan, acara besok diputuskan untuk ditunda."}'::jsonb, '["台風のため、","明日の","イベントは","延期する","ことに","なりました。"]'::jsonb, NULL, NULL, '延期することになりました menyampaikan keputusan panitia akibat cuaca.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a72065b5-b4eb-59d6-bb44-8318251a6dd2', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena baru pindah, saya belum mengenal lingkungan sekitar."', '{"romaji":"Hikkoshita bakari na node, kinjo no koto ga wakarimasen.","display_text":"引っ越したばかりなので、近所のことがわかりません。","phonetic_breakdown":["hik-ko-shi-ta","ba-ka-ri na no-de","kin-jo no ko-to ga","wa-ka-ri-ma-sen"]}'::jsonb, '{"expected_transcript":"引っ越したばかりなので、近所のことがわかりません。"}'::jsonb, NULL, NULL, '近所 (kinjo) berarti lingkungan tetangga sekitar rumah.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('064b92e0-0461-5ecc-bfba-6b24ecc8b359', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rapatnya baru saja selesai."', '{"romaji":"Kaigi wa tatta ima owatta bakari desu.","display_text":"会議はたった今終わったばかりです。","phonetic_breakdown":["ka-i-gi wa","tat-ta i-ma","o-wat-ta","ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript":"会議はたった今終わったばかりです。"}'::jsonb, NULL, NULL, 'たった今 (tatta ima = baru saja detik ini) memperkuat nuansa ～たばかり.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('468641f7-356d-57b5-9286-47c2d16f8649', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru mulai belajar bahasa Jepang tahun lalu."', '{"romaji":"Kyonen nihongo no benkyou o hajimeta bakari desu.","display_text":"去年日本語の勉強を始めたばかりです。","phonetic_breakdown":["kyo-nen","ni-hon-go no","ben-kyou o","ha-ji-me-ta","ba-ka-ri de-su"]}'::jsonb, '{"expected_transcript":"去年日本語の勉強を始めたばかりです。"}'::jsonb, NULL, NULL, 'Ungkapan rendah hati yang bagus saat memperkenalkan diri kepada penutur asli.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbc2612a-d65c-54a1-9a92-cca914f8d158', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Keretanya baru saja berangkat."', '{"romaji":"Densha wa ima deta bakari desu.","tokens":["ばかりです。","今","出る","出て","電車は","出た"],"target_translation":"Keretanya baru saja berangkat."}'::jsonb, '["電車は","今","出た","ばかりです。"]'::jsonb, NULL, NULL, '出た (Bentuk-TA dari 出る) + ばかりです.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93888133-0bc0-5fb6-b567-8710424286e1', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Ini adalah sepatu yang baru saja saya beli."', '{"romaji":"Kore wa katta bakari no kutsu desu.","tokens":["これは","靴です。","ばかりの","買って","ばかりな","買った"],"target_translation":"Ini adalah sepatu yang baru saja saya beli."}'::jsonb, '["これは","買った","ばかりの","靴です。"]'::jsonb, NULL, NULL, '買ったばかりの靴 (sepatu yang baru dibeli).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44064973-f8f0-56b5-bcaa-11f922a4fd55', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Karena baru bangun tidur, saya masih mengantuk."', '{"romaji":"Okita bakari na node, mada nemui desu.","tokens":["ばかりなので、","起きた","はずなので、","まだ","起きて","眠いです。"],"target_translation":"Karena baru bangun tidur, saya masih mengantuk."}'::jsonb, '["起きた","ばかりなので、","まだ","眠いです。"]'::jsonb, NULL, NULL, '起きたばかりなので berarti ''karena baru saja bangun''.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d5e0c66-a92b-4a7d-b8d9-3658a8d6841c', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya baru saja masuk perusahaan ini pada bulan April."', '{"romaji":"Shigatsu ni kono kaisha ni nyuusha shita bakari desu.","display_text":"四月にこの会社に入社したばかりです。","phonetic_breakdown":["shi-ga-tsu-ni","ko-no","kai-sha-ni","nyuu-sha-shi-ta","ba-ka-ri-de-su"]}'::jsonb, '{"expected_transcript":"四月にこの会社に入社したばかりです。"}'::jsonb, NULL, NULL, '入社したばかり sangat sering dipakai karyawan baru saat memperkenalkan diri.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbb8d6fd-532e-4b51-b28a-7ca264c62949', 'bb7fc2ef-f289-5b8c-adcb-4b174ed43181', 'd1000019-0000-0000-0000-000000000016', 'writing', 'sentence_builder', 'Susun kalimat: "Saya baru saja sampai di stasiun tadi."', '{"romaji":"Sakki eki ni tsuita bakari desu.","tokens":["を","着いた","駅に","ばかり","着く","です。","さっき"],"target_translation":"Saya baru saja sampai di stasiun tadi."}'::jsonb, '["さっき","駅に","着いた","ばかり","です。"]'::jsonb, NULL, NULL, '着いた (bentuk た) + ばかりです.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7a0735c-8ef3-5280-bcde-0c694df6207c', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'listening', 'listening_choice', 'Bagaimana cara menentukan pemenang lomba desain tersebut?', '{"options":[{"id":"opt_1","text":"Ditentukan sepenuhnya melalui undian acak"},{"id":"opt_2","text":"Dipilih hanya oleh ketua panitia lomba"},{"id":"opt_3","text":"Ditentukan berdasarkan kecepatan waktu pengumpulan"},{"id":"opt_4","text":"Ditentukan oleh penilaian juri dan pemungutan suara masyarakat umum"}],"audio_text":"最優秀作品は、審査員の評価と一般の方々による投票で決定されます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '審査員の評価と一般の方々による投票 berarti penilaian juri dan voting oleh masyarakat umum.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55502efc-0fed-5593-b158-29460c7bc811', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'listening', 'listening_choice', 'Mengapa aturan pembuangan sampah perlu dicek setiap kali pindah kota?', '{"options":[{"id":"opt_1","text":"Karena aturan pemilahan sampah berbeda tergantung pemerintah daerah"},{"id":"opt_2","text":"Karena jadwal truk sampah berubah setiap minggu"},{"id":"opt_3","text":"Karena kantong sampah hanya dijual di balai kota"},{"id":"opt_4","text":"Karena warga baru mendapat pengecualian selama sebulan"}],"audio_text":"日本では自治体によってゴミの分別ルールが異なるため、引っ越したら必ず確認が必要です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '自治体によってゴミの分別ルールが異なる berarti aturan pemilahan sampah berbeda tergantung pemerintah kota/daerah.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e35720d1-f97f-585e-b300-936d23cc2ac2', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'listening', 'listening_choice', 'Apa dampak positif dari penerapan sistem kerja baru menurut audio?', '{"options":[{"id":"opt_1","text":"Perusahaan berhasil mengurangi jumlah rapat mingguan menjadi nol"},{"id":"opt_2","text":"Waktu perjalanan pegawai berkurang dan produktivitas meningkat"},{"id":"opt_3","text":"Seluruh kantor cabang di luar Tokyo ditutup permanen"},{"id":"opt_4","text":"Biaya listrik kantor meningkat dua kali lipat"}],"audio_text":"テレワークの導入によって、社員の通勤時間が減り、生産性が向上しました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'テレワークの導入によって...通勤時間が減り、生産性が向上しました.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8707bebc-b37a-5415-afb6-bfba31252f3e', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 状況 ___ 、柔軟に対応することが求められます。', '{"options":["によって","による","に対して","にとって"],"translation":"Tergantung situasinya, kita dituntut merespons secara fleksibel.","sentence_template":"状況 [blank] 、柔軟に対応することが求められます。"}'::jsonb, '{"selected":"によって"}'::jsonb, NULL, NULL, '状況によって berarti tergantung pada situasi/keadaan.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('36181fdc-f4b5-5256-96f0-2534be8077e9', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'reading', 'fill_blank', 'Lengkapi frasa berita resmi: 地震 ___ 交通機関の乱れはすべて解消しました。', '{"options":["による","によって","に対する","における"],"translation":"Gangguan transportasi akibat gempa bumi telah teratasi seluruhnya.","sentence_template":"地震 [blank] 交通機関の乱れはすべて解消しました。"}'::jsonb, '{"selected":"による"}'::jsonb, NULL, NULL, '交通機関の乱れ (gangguan transportasi) adalah nomina, sehingga memakai による.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf238178-0b6a-5862-b1b5-17a19fa93124', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', NULL, 'reading', 'fill_blank', 'Pilih ungkapan variasi: 場合 ___ 、オンライン面談に変更することも可能です。', '{"options":["によっては","によるは","に対しては","にとっては"],"translation":"Tergantung keadaannya, memungkinkan juga diubah menjadi pertemuan daring.","sentence_template":"場合 [blank] 、オンライン面談に変更することも可能です。"}'::jsonb, '{"selected":"によっては"}'::jsonb, NULL, NULL, '場合によっては berarti ''tergantung kasusnya / dalam kondisi tertentu''.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aab23dbd-3b94-443c-8523-2cfb33b99d78', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan ulasan restoran berikut. Apa daya tarik utamanya?', '{"options":[{"id":"opt_1","text":"Menu di restoran ini tidak pernah berubah sepanjang tahun"},{"id":"opt_2","text":"Pelanggan harus memesan menu yang sama setiap datang"},{"id":"opt_3","text":"Karena menunya berubah tergantung musim, kapan pun berkunjung bisa menikmati rasa baru"},{"id":"opt_4","text":"Restoran ini hanya buka pada musim semi saja"}],"audio_text":"季節によってメニューが変わるので、いつ訪れても新しい味が楽しめますよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '季節によって berarti ''tergantung pada musimnya''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d2d5d56c-8d21-4a1f-ba25-20506302fdb0', 'c1af3612-ff0a-5c82-93e7-3a8ebcd861cf', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: その名画は江戸時代の有名な画家に___描かれました。', '{"options":["よって","対して","とって","ついて"],"translation":"Lukisan terkenal itu dilukis oleh pelukis ternama zaman Edo.","sentence_template":"その名画は江戸時代の有名な画家に[blank]描かれました。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, 'Pada kalimat pasif penciptaan karya/penemuan, pelaku ditandai dengan によって.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3555fe48-6f6a-4d65-9244-9adbb802084d', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan saran karier berikut. Mengapa perlu mengecek aturan pakaian?', '{"options":[{"id":"opt_1","text":"Aturan berpakaian hanya berlaku saat wawancara"},{"id":"opt_2","text":"Semua perusahaan di Jepang memiliki aturan pakaian yang sama"},{"id":"opt_3","text":"Karyawan baru bebas memakai pakaian apa saja tanpa aturan"},{"id":"opt_4","text":"Aturan berpakaian berbeda tergantung perusahaannya, jadi aman jika dicek sebelum masuk kerja"}],"audio_text":"会社によって服装のルールが違うので、入社前に確認しておくと安心ですよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '会社によって違う berarti berbeda-beda menurut perusahaannya.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5ed6bb8b-348f-4656-a861-d3d7f92a9f73', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tergantung jamnya, jalan ini terkadang sangat macet."', '{"romaji":"Jikantai ni yotte wa, kono douro wa totemo komimasu.","display_text":"時間帯によっては、この道路はとても混みます。","phonetic_breakdown":["ji-kan-tai-ni","yot-te-wa","ko-no","dou-ro-wa","to-te-mo","ko-mi-ma-su"]}'::jsonb, '{"expected_transcript":"時間帯によっては、この道路はとても混みます。"}'::jsonb, NULL, NULL, '時間帯によっては menyoroti kondisi tertentu pada jam-jam sibuk.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53a439c3-3074-4384-a8e1-262cede7d05b', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Sedang menyelidiki kondisi kerusakan akibat gempa bumi."', '{"romaji":"Jishin ni yoru higai no joukyou o chousa shite imasu.","tokens":["状況を","調査して","よる","います。","が","よって","地震に","被害の"],"target_translation":"Sedang menyelidiki kondisi kerusakan akibat gempa bumi."}'::jsonb, '["地震に","よる","被害の","状況を","調査して","います。"]'::jsonb, NULL, NULL, '地震による被害 = kerusakan akibat gempa.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f089e6d6-1817-4719-8429-8fef326b2838', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 運動と食事の改善に___、健康を取り戻すことができました。', '{"options":["よって","対して","ついて","おいて"],"translation":"Melalui olahraga dan perbaikan pola makan, saya berhasil memulihkan kesehatan.","sentence_template":"運動と食事の改善に[blank]、健康を取り戻すことができました。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, '改善によって menyatakan metode yang membawa keberhasilan.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6308d659-66bc-44ad-800a-743fc0a04705', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan liputan budaya berikut. Siapa yang mengelola festival tersebut?', '{"options":[{"id":"opt_1","text":"Festival tradisional daerah ini setiap tahun dikelola oleh perkumpulan pemuda setempat"},{"id":"opt_2","text":"Pemuda setempat tidak terlibat dalam festival ini"},{"id":"opt_3","text":"Festival tradisional daerah ini sudah tidak diadakan lagi"},{"id":"opt_4","text":"Festival ini dikelola sepenuhnya oleh wisatawan asing"}],"audio_text":"この地域の伝統的な祭りは、地元の青年会によって毎年運営されています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '青年会によって運営されている menandai pihak penyelenggara resmi.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef05f646-9a35-4793-aa21-c44b82323d64', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Melalui pengalaman, kemampuan mengambil keputusan akan terasah."', '{"romaji":"Keiken ni yotte handanryoku ga migakaremasu.","display_text":"経験によって判断力が磨かれます。","phonetic_breakdown":["kei-ken-ni","yot-te","han-dan-ryo-ku-ga","mi-ga-ka-re-ma-su"]}'::jsonb, '{"expected_transcript":"経験によって判断力が磨かれます。"}'::jsonb, NULL, NULL, '経験によって menyatakan sarana pembentukan kemampuan.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c7660c00-ea3e-4e8e-b092-70d1b88aba1e', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Silakan sesuaikan pakaian tergantung cuaca dan suhu udara."', '{"romaji":"Tenki ya kion ni yotte, fukusou o chousei shite kudasai.","tokens":["が","対して、","気温に","調整して","天気や","服装を","よって、","ください。"],"target_translation":"Silakan sesuaikan pakaian tergantung cuaca dan suhu udara."}'::jsonb, '["天気や","気温に","よって、","服装を","調整して","ください。"]'::jsonb, NULL, NULL, '天気や気温によって = bergantung pada cuaca dan suhu.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70a3d8ad-7d51-411f-af36-621dea91e41f', 'c610288c-83a4-483b-9831-782a9e3a4667', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 国に___お正月の過ごし方は大きく違います。', '{"options":["おいて","対して","よって","とって"],"translation":"Cara menghabiskan tahun baru sangat berbeda tergantung negaranya.","sentence_template":"国に[blank]お正月の過ごし方は大きく違います。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, '国によって menyatakan keragaman budaya antarnegara.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('10d50425-70ca-4729-98d4-63abdf4d26de', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan sapaan berikut. Bagaimana keadaan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara mengeluh pekerjaannya terlalu berat"},{"id":"opt_2","text":"Pembicara menjawab bahwa dirinya sehat dan bekerja dengan baik setiap hari"},{"id":"opt_3","text":"Pembicara sedang sakit dan tidak masuk kerja"},{"id":"opt_4","text":"Pembicara lupa menanyakan kabar lawan bicara"}],"audio_text":"お元気ですか。ええ、おかげさまで毎日元気に仕事していますよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'おかげさまで adalah jawaban sopan standar saat ditanya kabar.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42816d79-9aed-4319-99f1-ce127b12880f', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat saran Bapak/Ibu Guru, saya lulus wawancara."', '{"romaji":"Sensei no adobaisu no okage de, mensetsu ni goukaku shimashita.","display_text":"先生のアドバイスのおかげで、面接に合格しました。","phonetic_breakdown":["sen-sei-no","a-do-bai-su-no","o-ka-ge-de","men-se-tsu-ni","gou-ka-ku-shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"先生のアドバイスのおかげで、面接に合格しました。"}'::jsonb, NULL, NULL, 'アドバイスのおかげで menunjukkan rasa terima kasih atas masukan yang berguna.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c362843e-ca99-4dd1-b7d6-b32495ecbfaf', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat mendapatkan beasiswa, saya bisa fokus belajar dengan tenang."', '{"romaji":"Shougakukin o moraeta okage de, anshin shite benkyou ni shuuchuu dekimasu.","tokens":["集中できます。","勉強に","おかげで、","奨学金を","せいで、","安心して","が","もらえた"],"target_translation":"Berkat mendapatkan beasiswa, saya bisa fokus belajar dengan tenang."}'::jsonb, '["奨学金を","もらえた","おかげで、","安心して","勉強に","集中できます。"]'::jsonb, NULL, NULL, 'もらえた + おかげで.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('de1a6362-fa8c-4cb7-8240-6266af0e23a3', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 家が職場に近い___、通勤のストレスがほとんどありません。', '{"options":["ばかりに","せいで","によって","おかげで"],"translation":"Berkat rumah dekat dengan tempat kerja, hampir tidak ada stres perjalanan kerja.","sentence_template":"家が職場に近い[blank]、通勤のストレスがほとんどありません。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, '近い (kata sifat い) + おかげで.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('365303b0-4287-4d90-93e7-dc1bf70cb12c', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan ucapan teman kelas berikut. Mengapa ia berterima kasih?', '{"options":[{"id":"opt_1","text":"Teman menolak meminjamkan catatan kuliah"},{"id":"opt_2","text":"Pembicara lupa mengembalikan buku catatan teman"},{"id":"opt_3","text":"Pembicara berterima kasih karena bisa memahami materi hari saat absen berkat dipinjami catatan"},{"id":"opt_4","text":"Pembicara tidak memahami isi catatan yang dipinjamkan"}],"audio_text":"ノートを貸してくれたおかげで、休んだ日の授業内容がちゃんと分かりました。ありがとう。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '貸してくれたおかげで menyatakan terima kasih atas pertolongan spesifik.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d703aaa-a68d-4021-8f5c-9eec6f8663a2', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Berkat mendapat teman orang Jepang, kemampuan percakapan saya meningkat."', '{"romaji":"Nihonjin no tomodachi ga dekita okage de, kaiwa ga joutatsu shimashita.","display_text":"日本人の友達ができたおかげで、会話が上達しました。","phonetic_breakdown":["ni-hon-jin-no","to-mo-da-chi-ga","de-ki-ta","o-ka-ge-de","kai-wa-ga","jou-ta-tsu-shi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"日本人の友達ができたおかげで、会話が上達しました。"}'::jsonb, NULL, NULL, 'できたおかげで menghubungkan sebab dan perkembangan positif.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4cccacc8-e2dd-4477-b760-8093bc5b10d6', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'writing', 'sentence_builder', 'Susun kalimat: "Berkat AC yang berfungsi baik, bahkan di puncak musim panas pun tetap nyaman."', '{"romaji":"Eakon ga kiite iru okage de, manatsu demo kaiteki desu.","tokens":["真夏でも","エアコンが","快適です。","おかげで、","せいで、","効いている","を"],"target_translation":"Berkat AC yang berfungsi baik, bahkan di puncak musim panas pun tetap nyaman."}'::jsonb, '["エアコンが","効いている","おかげで、","真夏でも","快適です。"]'::jsonb, NULL, NULL, '効いている + おかげで.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d70c575-3e50-4a31-8cf3-5267f78dafd3', 'd281b279-b383-4223-ae58-dc2b0f9321d4', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: チーム全員の努力の___、目標を達成することができました。', '{"options":["おかげで","うちに","はずで","せいで"],"translation":"Berkat kerja keras seluruh tim, kami berhasil mencapai target.","sentence_template":"チーム全員の努力の[blank]、目標を達成することができました。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, '努力のおかげで (kata benda + のおかげで).', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('71edb411-0bf0-4b17-a3da-8443e63f7d8b', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 忘れない___、今のうちにスケジュール帳に書いておきます。', '{"options":["おかげで","せいで","うちに","によって"],"translation":"Mumpung belum lupa, sekarang juga saya catat di buku jadwal.","sentence_template":"忘れない[blank]、今のうちにスケジュール帳に書いておきます。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '忘れないうちに berarti ''sebelum lupa''.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f0df3df-52e4-460d-8941-ff076e5889cb', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼が説明を聞いている___、だんだん表情が明るくなってきました。', '{"options":["うちに","に対して","はずで","せいで"],"translation":"Selagi dia mendengarkan penjelasan, ekspresi wajahnya perlahan menjadi cerah.","sentence_template":"彼が説明を聞いている[blank]、だんだん表情が明るくなってきました。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '聞いているうちに menggambarkan perubahan bertahap yang terjadi secara alami.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7e7488c6-ea03-402a-98d6-a5d1c8a65c92', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan saran belanja berikut. Mengapa perlu segera memesan?', '{"options":[{"id":"opt_1","text":"Barang diskon tidak bisa dipesan secara daring"},{"id":"opt_2","text":"Karena barang diskon cepat habis, sebaiknya memesan mumpung stok masih ada"},{"id":"opt_3","text":"Sebaiknya menunggu sampai promo diskon berakhir"},{"id":"opt_4","text":"Stok barang diskon sudah habis sejak pagi"}],"audio_text":"セール品はすぐ売り切れますから、在庫があるうちに注文したほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '在庫があるうちに berarti ''mumpung stok masih tersedia''.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('13c1ba57-bc05-4073-8968-e47c4dec1317', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Selagi anak sedang tidur, saya menyelesaikan persiapan makan malam."', '{"romaji":"Kodomo ga nete iru uchi ni, yuuhan no junbi o sumasemasu.","tokens":["準備を","子供が","寝ている","が","うちに、","済ませます。","寝たせいで、","夕飯の"],"target_translation":"Selagi anak sedang tidur, saya menyelesaikan persiapan makan malam."}'::jsonb, '["子供が","寝ている","うちに、","夕飯の","準備を","済ませます。"]'::jsonb, NULL, NULL, '寝ているうちに menandai rentang waktu sebelum keadaan berubah (anak bangun).', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c13a6d10-dbc4-4d5a-a69b-ef2789165394', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 静かな音楽を聴いている___、いつの間にか眠ってしまいました。', '{"options":["うちに","ばかりで","によって","おかげで"],"translation":"Selagi mendengarkan musik yang tenang, tanpa sadar saya tertidur.","sentence_template":"静かな音楽を聴いている[blank]、いつの間にか眠ってしまいました。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, 'いつの間にか sering berpasangan dengan ～ているうちに untuk perubahan tak disadari.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('62c9989b-e169-4b20-8ce8-f0405a1bf7b2', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Silakan minum kopinya mumpung belum dingin."', '{"romaji":"Samenai uchi ni koohii o nonde kudasai.","display_text":"冷めないうちにコーヒーを飲んでください。","phonetic_breakdown":["sa-me-nai","u-chi-ni","koo-hii-o","non-de","ku-da-sai"]}'::jsonb, '{"expected_transcript":"冷めないうちにコーヒーを飲んでください。"}'::jsonb, NULL, NULL, '冷めないうちに adalah ungkapan ramah saat menyuguhkan minuman panas.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f6436abf-23d1-430d-8d34-5e851e111646', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan refleksi kerja berikut. Bagaimana perkembangan pembicara?', '{"options":[{"id":"opt_1","text":"Pekerjaan itu tetap terasa mustahil meski sudah diulang berkali-kali"},{"id":"opt_2","text":"Pembicara memutuskan berhenti dari pekerjaan tersebut"},{"id":"opt_3","text":"Pekerjaan yang awalnya terasa sulit pun lama-kelamaan mulai dikuasai selagi diulang terus"},{"id":"opt_4","text":"Pekerjaan itu sudah sangat mudah sejak hari pertama"}],"audio_text":"最初は難しく感じた仕事も、何度も繰り返しているうちに自然とコツがつかめてきました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '繰り返しているうちに menyatakan kemajuan bertahap seiring pengulangan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f433b94-a80b-44a9-95ff-ec735ac21196', 'd5818bc8-4731-4690-9bc3-452b6595de22', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mumpung sedang senggang, saya akan membalas email yang menumpuk terlebih dahulu."', '{"romaji":"Hima na uchi ni, tamatta meeru ni henshin shite okimasu.","tokens":["暇の","を","暇な","たまった","おきます。","うちに、","返信して","メールに"],"target_translation":"Mumpung sedang senggang, saya akan membalas email yang menumpuk terlebih dahulu."}'::jsonb, '["暇な","うちに、","たまった","メールに","返信して","おきます。"]'::jsonb, NULL, NULL, 'Kata sifat な (暇) -> 暇なうちに.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a96ddeb3-502b-5e6c-bd72-b54ca2f05e28', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: セールが ___ うちに、冬用のコートを買っておきたいです。', '{"options":["終わらない","終わる","終わった","終わって"],"translation":"Selagi diskon belum berakhir, saya ingin membeli mantel musim dingin.","sentence_template":"セールが [blank] うちに、冬用のコートを買っておきたいです。"}'::jsonb, '{"selected":"終わらない"}'::jsonb, NULL, NULL, '終わらないうちに berarti ''selagi belum berakhir / sebelum selesai''.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0d973d4-270a-5408-9fd0-80a5664cccf4', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi perubahan alami: 日本で暮らしている ___ 、日本の四季が大好きになりました。', '{"options":["うちに","せいで","に対して","はずだ"],"translation":"Selama tinggal di Jepang, lama-kelamaan saya menjadi sangat menyukai empat musim Jepang.","sentence_template":"日本で暮らしている [blank] 、日本の四季が大好きになりました。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '暮らしているうちに mengekspresikan perubahan perasaan yang terjadi secara bertahap.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb668f3b-fde0-5823-a57d-c48ae799b5be', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Kapan pembicara berencana mendaftar ujian JLPT?', '{"options":[{"id":"opt_1","text":"Sehari sebelum pendaftaran resmi ditutup"},{"id":"opt_2","text":"Setelah menanyakan lokasi ujian kepada teman"},{"id":"opt_3","text":"Segera pada tahap awal begitu pendaftaran dibuka"},{"id":"opt_4","text":"Pada bulan depan setelah gaji turun"}],"audio_text":"人気のある会場はすぐ満席になるので、受付が始まったら早いうちに申し込むつもりです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '早いうちに申し込むつもりです berarti berencana mendaftar selagi masih awal.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6de2ff59-2246-5075-afb1-62b895809ef7', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Apa yang terjadi saat pembicara mendengarkan musik santai?', '{"options":[{"id":"opt_1","text":"Ia berhasil menyelesaikan seluruh laporan kerjanya"},{"id":"opt_2","text":"Ia menjadi terinspirasi menulis lagu sendiri"},{"id":"opt_3","text":"Ia menyadari baterainya hampir habis"},{"id":"opt_4","text":"Tanpa sadar ia tertidur di sofa"}],"audio_text":"静かな音楽を聴いているうちに、いつの間にかソファで寝てしまいました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'いつの間にかソファで寝てしまいました berarti tanpa sadar tertidur di sofa.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3381c64b-36e9-534e-b830-0264c997a355', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'writing', 'sentence_builder', 'Susun kalimat: "Mari memotret selagi bunga sakura masih mekar."', '{"romaji":"Sakura ga saite iru uchi ni shashin o torimashou.","tokens":["撮りましょう。","咲いた","桜が","うちに","咲いている","写真を","せいで"],"target_translation":"Mari memotret selagi bunga sakura masih mekar."}'::jsonb, '["桜が","咲いている","うちに","写真を","撮りましょう。"]'::jsonb, NULL, NULL, '咲いているうちに berarti selagi masih mekar (sebelum gugur).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6db916c0-ee80-5efd-a915-91e76a8d62ae', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mari kita konfirmasi detailnya selagi ingatan masih segar."', '{"romaji":"Kioku ga atarashii uchi ni shousai o kakunin shimashou.","display_text":"記憶が新しいうちに詳細を確認しましょう。","phonetic_breakdown":["ki-o-ku ga","a-ta-ra-shi-i","u-chi ni","shou-sa-i o","ka-ku-nin","shi-ma-shou"]}'::jsonb, '{"expected_transcript":"記憶が新しいうちに詳細を確認しましょう。"}'::jsonb, NULL, NULL, '詳細 (shousai) berarti rincian/detail. Sangat cocok dipakai tepat seusai rapat.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a9d09555-f9ea-4e4c-ac5e-f139cc05a229', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 毎日日本語を聞いている___、少しずつ聞き取れるようになりました。', '{"options":["に対して","はずで","ばかりに","うちに"],"translation":"Seiring mendengarkan bahasa Jepang setiap hari, perlahan-lahan saya jadi bisa menangkap artinya.","sentence_template":"毎日日本語を聞いている[blank]、少しずつ聞き取れるようになりました。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '聞いているうちに menyatakan perubahan alami selama kegiatan terus dilakukan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('687710e3-6ff1-4add-92f6-94e38fce6574', 'd94d3333-e246-539d-8914-dde6a731d00f', 'd1000019-0000-0000-0000-000000000013', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mumpung masih sehat dan bugar, saya ingin berkeliling dunia."', '{"romaji":"Genki na uchi ni sekaijuu o tabi shitai to omotte imasu.","display_text":"元気なうちに世界中を旅したいと思っています。","phonetic_breakdown":["gen-ki-na","u-chi-ni","se-kai-juu-o","ta-bi-shi-tai-to","o-mot-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"元気なうちに世界中を旅したいと思っています。"}'::jsonb, NULL, NULL, 'Kata sifat な (元気) memerlukan な sebelum うちに -> 元気なうちに.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b9bbd5a3-ea51-49d0-9fc3-1b79967475f3', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 宿泊料金は時期に___異なりますので、サイトでご確認ください。', '{"options":["対して","ついて","よって","かわりに"],"translation":"Tarif menginap berbeda tergantung musimnya, jadi silakan cek di situs web.","sentence_template":"宿泊料金は時期に[blank]異なりますので、サイトでご確認ください。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, '時期によって異なります adalah ungkapan standar layanan pariwisata.', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e70bab5f-bf46-4657-9197-fd92eb9e28b1', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 不注意に___事故を防ぐため、安全マニュアルを徹底しています。', '{"options":["ついての","対する","よる","よって"],"translation":"Untuk mencegah kecelakaan akibat kelalaian, kami menegakkan manual keselamatan.","sentence_template":"不注意に[blank]事故を防ぐため、安全マニュアルを徹底しています。"}'::jsonb, '{"selected":"よる"}'::jsonb, NULL, NULL, 'Sebelum kata benda 事故, gunakan による (akibat ...).', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('448f5897-79e1-433f-9f41-6f1fd4986908', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan berita sains berikut. Bagaimana obat baru ini dihasilkan?', '{"options":[{"id":"opt_1","text":"Obat ini tidak melalui proses penelitian ilmiah"},{"id":"opt_2","text":"Obat baru ini dikembangkan melalui penelitian bertahun-tahun"},{"id":"opt_3","text":"Obat baru ini ditemukan secara kebetulan kemarin"},{"id":"opt_4","text":"Penelitian obat baru ini dihentikan sebelum selesai"}],"audio_text":"この新しい薬は、長年の研究によって開発されました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '研究によって menyatakan metode/proses formal dalam kalimat pasif.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ecea48fa-a659-4bd4-bdd5-2c6cc18a7bdf', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat perubahan iklim, hasil panen pertanian sedang menurun."', '{"romaji":"Kikou no henka ni yotte, nousakubutsu no shuukakuryou ga hette imasu.","tokens":["を","減っています。","変化に","気候の","対して、","収穫量が","農作物の","よって、"],"target_translation":"Akibat perubahan iklim, hasil panen pertanian sedang menurun."}'::jsonb, '["気候の","変化に","よって、","農作物の","収穫量が","減っています。"]'::jsonb, NULL, NULL, '変化によって menyatakan sebab resmi dari fenomena alam/ekonomi.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('663893b6-2412-4b7c-996a-09f9391c20e4', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: テストの点数に___、クラス分けが行われます。', '{"options":["とって","対して","よって","おいて"],"translation":"Pembagian kelas dilakukan berdasarkan skor tes.","sentence_template":"テストの点数に[blank]、クラス分けが行われます。"}'::jsonb, '{"selected":"よって"}'::jsonb, NULL, NULL, '点数によって menyatakan dasar pembedaan/klasifikasi.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2326bce3-edc1-4081-b067-687c4f65312e', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Melalui kemajuan teknologi, kehidupan menjadi semakin praktis."', '{"romaji":"Gijutsu no shinpo ni yotte, seikatsu wa masumasu benri ni narimashita.","display_text":"技術の進歩によって、生活はますます便利になりました。","phonetic_breakdown":["gi-ju-tsu-no","shin-po-ni","yot-te","sei-ka-tsu-wa","ma-su-ma-su","ben-ri-ni","na-ri-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"技術の進歩によって、生活はますます便利になりました。"}'::jsonb, NULL, NULL, '進歩によって menyatakan penyebab positif dalam gaya bahasa formal.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8383e33c-d6b1-4272-9f65-3ec1c46e2750', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'listening', 'listening_choice', 'Dengarkan penjelasan kesehatan berikut. Apa arti frasa 人によっては?', '{"options":[{"id":"opt_1","text":"Semua orang pasti sakit perut jika makan makanan pedas"},{"id":"opt_2","text":"Makanan pedas selalu menyembuhkan sakit perut"},{"id":"opt_3","text":"Tergantung orangnya, ada kalanya makan makanan pedas membuat sakit perut"},{"id":"opt_4","text":"Tidak ada seorang pun yang suka makanan pedas"}],"audio_text":"人によっては、辛い料理を食べるとお腹が痛くなることもあります。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '～によっては berarti ''tergantung pada kasus tertentu / bagi sebagian orang''.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5faa724-9063-4c7f-bb70-e5111fc9d454', 'db8b0045-b561-4a98-b0f1-1fa564a21d98', 'd1000019-0000-0000-0000-000000000017', 'writing', 'sentence_builder', 'Susun kalimat: "Novel ini ditulis oleh seorang penulis terkenal."', '{"romaji":"Kono shousetsu wa yuumei na sakka ni yotte kakaremashita.","tokens":["作家に","有名な","を","小説は","対して","この","よって","書かれました。"],"target_translation":"Novel ini ditulis oleh seorang penulis terkenal."}'::jsonb, '["この","小説は","有名な","作家に","よって","書かれました。"]'::jsonb, NULL, NULL, '作家によって menandai pencipta karya dalam kalimat pasif.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('753e7d1b-d3be-5e7b-ac2f-d4e642eb8883', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'listening', 'listening_choice', 'Mengapa pembicara merasa tenggorokannya sakit?', '{"options":[{"id":"opt_1","text":"Karena terlalu banyak berbicara saat presentasi"},{"id":"opt_2","text":"Karena minum air es setelah berolahraga"},{"id":"opt_3","text":"Karena udara di luar sangat berdebu"},{"id":"opt_4","text":"Karena tertidur dengan AC tetap menyala semalam"}],"audio_text":"昨日エアコンをつけたまま寝てしまったせいで、朝から喉が痛いです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'エアコンをつけたまま寝てしまったせいで berarti gara-gara terlanjur tidur dengan AC menyala.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df71dd2c-f4cd-514a-b7b5-da976c498aeb', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'listening', 'listening_choice', 'Apa dampak kenaikan harga bahan pangan bagi pembicara?', '{"options":[{"id":"opt_1","text":"Biaya makan bulanannya meningkat jauh dibanding sebelumnya"},{"id":"opt_2","text":"Ia harus pindah ke apartemen yang lebih kecil"},{"id":"opt_3","text":"Restoran favoritnya dekat stasiun terpaksa tutup"},{"id":"opt_4","text":"Ia berhenti memasak sendiri di rumah"}],"audio_text":"最近物価が上がったせいで、毎月の食費が以前よりずっと増えました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '毎月の食費が以前よりずっと増えました berarti biaya makan bulanan naik jauh dibanding dulu.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('27d4126a-7c45-5177-baf3-0afc0f1f2a95', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'listening', 'listening_choice', 'Mengapa jadwal wawancara harus dijadwalkan ulang?', '{"options":[{"id":"opt_1","text":"Karena pewawancara sedang cuti sakit"},{"id":"opt_2","text":"Karena gangguan sistem membuat layar wawancara daring tidak bisa dibuka"},{"id":"opt_3","text":"Karena pelamar salah mencatat tanggal wawancara"},{"id":"opt_4","text":"Karena ruang rapat kantor sedang direnovasi"}],"audio_text":"システムの不具合のせいで、オンライン面接の画面が開けなくなってしまいました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'システムの不具合のせいで berarti gara-gara gangguan/kerusakan sistem.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f10ec618-3231-5a7b-885e-daf29704d159', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'reading', 'fill_blank', 'Pilih akhiran yang tepat: 今回のミスは、確認不足の ___ です。', '{"options":["せい","おかげ","こと","よう"],"translation":"Kesalahan kali ini adalah akibat kurangnya pengecekan.","sentence_template":"今回のミスは、確認不足の [blank] です。"}'::jsonb, '{"selected":"せい"}'::jsonb, NULL, NULL, '～のせいです digunakan di akhir kalimat untuk menegaskan sumber kesalahan/akibat buruk.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d65ecf91-bb87-58db-9b3f-ed83b0000db0', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'reading', 'fill_blank', 'Lengkapi dengan kata sifat-I: 説明が ___ せいで、参加者が混乱してしまいました。', '{"options":["わかりにくかった","わかりにくくて","わかりにくいな","わかりにくいです"],"translation":"Gara-gara penjelasannya sulit dipahami, para peserta menjadi bingung.","sentence_template":"説明が [blank] せいで、参加者が混乱してしまいました。"}'::jsonb, '{"selected":"わかりにくかった"}'::jsonb, NULL, NULL, 'Bentuk biasa lampau kata sifat-I (わかりにくかった) langsung disambungkan dengan せいで.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1029d61f-f4db-539c-a5a6-dcb1e8c424a9', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', NULL, 'reading', 'fill_blank', 'Pilih penghubung sebab yang sesuai nuansa kalimat: 大雨の ___ 、運動会が中止になって残念です。', '{"options":["せいで","おかげで","はずで","うちに"],"translation":"Gara-gara hujan deras, festival olahraga dibatalkan dan itu sangat disayangkan.","sentence_template":"大雨の [blank] 、運動会が中止になって残念です。"}'::jsonb, '{"selected":"せいで"}'::jsonb, NULL, NULL, 'Karena akibatnya negatif (dibatalkan dan disayangkan), wajib memakai せいで.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d352c34b-cb33-4c57-b5ab-861af9e3babb', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', 'd1000019-0000-0000-0000-000000000011', 'listening', 'listening_choice', 'Dengarkan keluhan rekan kerja berikut. Apa dugaan penyebabnya?', '{"options":[{"id":"opt_1","text":"Pembicara tidak merasa lelah meski kurang tidur"},{"id":"opt_2","text":"Sangat mudah berkonsentrasi karena tidur cukup setiap malam"},{"id":"opt_3","text":"Mungkin karena kurang tidur belakangan ini, sulit berkonsentrasi saat bekerja"},{"id":"opt_4","text":"Pekerjaan kantor sudah selesai lebih cepat dari jadwal"}],"audio_text":"最近寝不足のせいか、仕事中になかなか集中できないんです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '～せいか berarti ''mungkin gara-gara ...'' untuk dugaan penyebab negatif yang belum pasti.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('002f11f9-a344-474b-bb45-3ac828c926c9', 'e3241af6-4e4c-55e6-a158-8d993c07ff96', 'd1000019-0000-0000-0000-000000000011', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 外が___せいで、先生の声がよく聞こえませんでした。', '{"options":["うるさいの","うるさくて","うるさいな","うるさい"],"translation":"Gara-gara di luar berisik, suara guru tidak terdengar jelas.","sentence_template":"外が[blank]せいで、先生の声がよく聞こえませんでした。"}'::jsonb, '{"selected":"うるさい"}'::jsonb, NULL, NULL, 'Kata sifat い (うるさい) langsung diikuti せいで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37fa9aad-6064-5a7f-89e7-ea81f97b3545', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi pola membiasakan diri: 毎日野菜をたくさん ___ しています。', '{"options":["食べるように","食べたように","食べてように","食べますように"],"translation":"Saya membiasakan diri makan banyak sayur setiap hari.","sentence_template":"毎日野菜をたくさん [blank] しています。"}'::jsonb, '{"selected":"食べるように"}'::jsonb, NULL, NULL, 'Pola ～ようにする memakai bentuk kamus (食べる) atau bentuk-NAI sebelum ようにする.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6f179ffa-8c9d-5069-8360-1cd6f994a984', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Pilih bentuk negatif yang benar: 会議に ___ 気をつけています。', '{"options":["遅れないように","遅れるように","遅れなかったように","遅れませんように"],"translation":"Saya berhati-hati agar tidak terlambat rapat.","sentence_template":"会議に [blank] 気をつけています。"}'::jsonb, '{"selected":"遅れないように"}'::jsonb, NULL, NULL, 'Untuk menyatakan usaha agar tidak melakukan sesuatu, gunakan Bentuk-NAI + ように (遅れないように).', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0e59dfdc-e00e-5e19-9142-41b22ba4146e', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat rutinitas hemat: なるべく外食を ___ ようにしています。', '{"options":["しない","した","して","せず"],"translation":"Saya berusaha sebisa mungkin tidak makan di luar.","sentence_template":"なるべく外食を [blank] ようにしています。"}'::jsonb, '{"selected":"しない"}'::jsonb, NULL, NULL, 'Bentuk-NAI dari する adalah しない, sehingga menjadi なるべく外食をしないようにしています.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('108b43a6-62e2-5f57-8e1d-16637ca262e1', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya membiasakan diri berjalan kaki ke stasiun setiap pagi."', '{"romaji":"Maiasa eki made aruku you ni shite imasu.","tokens":["なりました。","しています。","毎朝","歩いて","歩く","ように","駅まで"],"target_translation":"Saya membiasakan diri berjalan kaki ke stasiun setiap pagi."}'::jsonb, '["毎朝","駅まで","歩く","ように","しています。"]'::jsonb, NULL, NULL, 'Bentuk kamus 歩く digabungkan dengan ようにしています untuk menyatakan kebiasaan yang sedang dijaga.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d10d3923-34b2-5d3f-959f-c0f023c1e3af', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya berusaha untuk tidak begadang."', '{"romaji":"Yofukashi o shinai you ni shite imasu.","tokens":["夜更かしを","した","ように","しています。","する","しない"],"target_translation":"Saya berusaha untuk tidak begadang."}'::jsonb, '["夜更かしを","しない","ように","しています。"]'::jsonb, NULL, NULL, '夜更かしをする (begadang) diubah ke bentuk-NAI menjadi 夜更かしをしない lalu diikuti ようにしています.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('30a3bf8f-affc-588b-b3ae-31760354576e', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'listening', 'listening_choice', 'Apa kebiasaan bahasa Jepang yang dilakukan pembicara di kereta?', '{"options":[{"id":"opt_1","text":"Membaca manga berbahasa Jepang"},{"id":"opt_2","text":"Menulis catatan harian di ponsel"},{"id":"opt_3","text":"Mendengarkan berita Jepang setiap berangkat kerja"},{"id":"opt_4","text":"Berlatih percakapan dengan teman sekantor"}],"audio_text":"通勤の電車の中では、必ず日本のニュースを聞くようにしています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '日本のニュースを聞くようにしています berarti membiasakan diri mendengarkan berita Jepang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8c314f35-9523-4d63-b9e0-dacceb34e467', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 遅刻を___ようにしています。', '{"options":["しなく","しなくて","しない","しなかった"],"translation":"Saya berusaha membiasakan diri agar tidak terlambat.","sentence_template":"遅刻を[blank]ようにしています。"}'::jsonb, '{"selected":"しない"}'::jsonb, NULL, NULL, 'Sebelum ようにする, kata kerja bentuk negatif menggunakan bentuk ない (しないようにする).', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b80d5b6-e02d-4e26-b55d-38f839b77227', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', 'd1000019-0000-0000-0000-000000000008', 'writing', 'sentence_builder', 'Susun kalimat: "Saya membiasakan diri mendengarkan berita bahasa Jepang setidaknya 30 menit setiap hari."', '{"romaji":"Mainichi sanjuppun wa Nihongo no nyuusu o kiku you ni shite imasu.","tokens":["が","聞く","聞きます","しています。","ニュースを","三十分は","毎日","ように","日本語の"],"target_translation":"Saya membiasakan diri mendengarkan berita bahasa Jepang setidaknya 30 menit setiap hari."}'::jsonb, '["毎日","三十分は","日本語の","ニュースを","聞く","ように","しています。"]'::jsonb, NULL, NULL, 'Kata kerja bentuk kamus (聞く) + ようにしています menyatakan rutinitas yang terus diupayakan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7acaf7f4-8499-5f80-9ff0-43bab6e68e7a', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'listening', 'listening_choice', 'Mengapa pembicara langsung mencuci piring setelah makan?', '{"options":[{"id":"opt_1","text":"Karena air panas di dapurnya sering mati malam hari"},{"id":"opt_2","text":"Karena ia ingin segera keluar rumah bertemu teman"},{"id":"opt_3","text":"Karena wastafel dapurnya sangat sempit"},{"id":"opt_4","text":"Karena noda minyak sulit hilang jika dibiarkan lama, jadi dicuci selagi belum dingin"}],"audio_text":"油汚れは時間が経つと落ちにくくなるので、冷めないうちに洗ってしまいます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '冷めないうちに洗ってしまいます berarti langsung mencucinya selagi belum dingin.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aa026d1e-5158-57b8-8bd5-13319c503357', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'listening', 'listening_choice', 'Apa yang terjadi saat pembicara membaca buku di kereta?', '{"options":[{"id":"opt_1","text":"Ia mengantuk dan terlewat stasiun tujuannya"},{"id":"opt_2","text":"Ia berhasil menamatkan seluruh buku sebelum tiba"},{"id":"opt_3","text":"Ia kehilangan pembatas buku di kursi kereta"},{"id":"opt_4","text":"Ia bertemu teman lama dari kampus"}],"audio_text":"電車で本を読んでいるうちに眠くなって、降りる駅を乗り過ごしてしまいました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '降りる駅を乗り過ごしてしまいました berarti terlewat stasiun tempat turun.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6f468123-db58-5f54-903e-41d620899d45', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'listening', 'listening_choice', 'Saran apa yang diberikan pembicara tentang belajar di Jepang?', '{"options":[{"id":"opt_1","text":"Segera membuka rekening bank sebelum pulang"},{"id":"opt_2","text":"Menguasai bahasa hormat dan etika bisnis selagi berada di Jepang"},{"id":"opt_3","text":"Mencari pekerjaan paruh waktu di restoran"},{"id":"opt_4","text":"Membeli banyak buku kamus untuk dibawa pulang"}],"audio_text":"日本にいるうちに、敬語やビジネスマナーをしっかり身につけておきたいですね。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '日本にいるうちに...身につけておきたい berarti ingin menguasainya selagi berada di Jepang.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4cd5debd-abbb-58d8-ba45-9c2eeae09e4d', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'reading', 'fill_blank', 'Lengkapi dengan adjektiva-NA: 仕事が ___ うちに、溜まっていた書類を片づけました。', '{"options":["暇な","暇の","暇だ","暇で"],"translation":"Selagi pekerjaan sedang senggang, saya membereskan dokumen yang menumpuk.","sentence_template":"仕事が [blank] うちに、溜まっていた書類を片づけました。"}'::jsonb, '{"selected":"暇な"}'::jsonb, NULL, NULL, 'Kata sifat-NA 暇 memakai な sebelum うちに (暇なうちに).', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('84e776f1-57e6-5bde-b594-fa9f1af43d16', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'reading', 'fill_blank', 'Pilih bentuk perubahan bertahap: 毎日練習 ___ うちに、だんだん弾けるようになりました。', '{"options":["している","した","して","します"],"translation":"Selagi terus berlatih setiap hari, lama-kelamaan saya menjadi bisa memainkannya.","sentence_template":"毎日練習 [blank] うちに、だんだん弾けるようになりました。"}'::jsonb, '{"selected":"している"}'::jsonb, NULL, NULL, 'Verba ～ている + うちに menyatakan perubahan yang muncul secara alami saat proses berlangsung.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3249366a-8d3d-5392-8eb8-b4d324fe84ee', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', NULL, 'reading', 'fill_blank', 'Lengkapi ungkapan waktu: 明るい ___ 庭の掃除を終わらせましょう。', '{"options":["うちに","せいで","おかげで","はずで"],"translation":"Mari selesaikan bersih-bersih halaman selagi hari masih terang.","sentence_template":"明るい [blank] 庭の掃除を終わらせましょう。"}'::jsonb, '{"selected":"うちに"}'::jsonb, NULL, NULL, '明るいうちに berarti selagi masih terang (sebelum gelap).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a3906311-eafd-4d41-98d0-e488136e64cc', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', 'd1000019-0000-0000-0000-000000000013', 'listening', 'listening_choice', 'Dengarkan pengalaman berikut. Apa yang terjadi saat pembicara membaca?', '{"options":[{"id":"opt_1","text":"Pembicara tidak sempat membaca buku tadi malam"},{"id":"opt_2","text":"Pembicara berhenti membaca buku karena mengantuk"},{"id":"opt_3","text":"Saking asyiknya membaca buku, tanpa sadar waktu berlalu sampai fajar menyingsing"},{"id":"opt_4","text":"Pembicara langsung tertidur begitu membuka buku"}],"audio_text":"本を読んでいたら、夢中になっていつの間にか夜が明けてしまったんです。読んでいるうちに時間を忘れました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '読んでいるうちに menggambarkan perubahan yang terjadi tanpa disadari selama aktivitas berlangsung.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('152d9e6f-3ae9-4f90-a08c-a04cffb445ff', 'eeaab0e0-7888-5746-a517-dea0ee01d15b', 'd1000019-0000-0000-0000-000000000013', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 独身___うちに、海外で働く経験を積んでおきたいです。', '{"options":["を","の","な","だ"],"translation":"Mumpung masih lajang, saya ingin mengumpulkan pengalaman bekerja di luar negeri.","sentence_template":"独身[blank]うちに、海外で働く経験を積んでおきたいです。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Kata benda (独身) memerlukan の sebelum うちに -> 独身のうちに.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e2af5df-b303-5a38-a3db-d2df1b6b0dd0', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'listening', 'listening_choice', 'Mengapa pembicara tidak ketinggalan kereta pagi ini?', '{"options":[{"id":"opt_1","text":"Karena ia naik taksi dari depan rumah"},{"id":"opt_2","text":"Karena jam rapat dimundurkan lima belas menit"},{"id":"opt_3","text":"Karena kereta hari ini berjalan lebih cepat"},{"id":"opt_4","text":"Karena ia berangkat lima belas menit lebih awal dari biasanya"}],"audio_text":"いつもより十五分早く家を出たおかげで、電車の遅延があっても間に合いました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'いつもより十五分早く家を出たおかげで berarti berkat berangkat 15 menit lebih awal dari biasanya.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7707d3c-bd2b-5597-bd9f-e686488dffb5', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'listening', 'listening_choice', 'Apa manfaat yang dirasakan pembicara dari aplikasi kamus baru?', '{"options":[{"id":"opt_1","text":"Waktu membaca artikel panjang berkurang setengahnya"},{"id":"opt_2","text":"Ia bisa menerjemahkan video rapat secara otomatis"},{"id":"opt_3","text":"Ia tidak perlu lagi membeli buku teks N3"},{"id":"opt_4","text":"Nilai ujian mendengar meningkat dua kali lipat"}],"audio_text":"便利な辞書アプリを見つけたおかげで、長い記事を読む時間が半分になりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '長い記事を読む時間が半分になりました berarti waktu membaca artikel panjang menjadi setengahnya.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a57f36f6-ef09-5784-8543-2714ab9582c6', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'listening', 'listening_choice', 'Bagaimana pembicara bisa menemukan dompetnya yang hilang?', '{"options":[{"id":"opt_1","text":"Temannya menemukan dompet itu di kafe"},{"id":"opt_2","text":"Petugas stasiun segera membantu mencarinya"},{"id":"opt_3","text":"Polisi mengantarkan dompetnya ke apartemen"},{"id":"opt_4","text":"Ia mengingat kembali tempat terakhir ia duduk"}],"audio_text":"駅の係員の方がすぐ調べてくださったおかげで、落とした財布が見つかりました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '駅の係員の方がすぐ調べてくださったおかげで berarti berkat petugas stasiun yang segera memeriksakannya.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db8a0ee7-7566-5db3-a0f9-ef21c4aeea54', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'reading', 'fill_blank', 'Pilih akhiran kalimat syukur: 今こうして元気に働けるのは、家族の支えの ___ です。', '{"options":["おかげ","せい","ため","はず"],"translation":"Bisa bekerja dengan sehat seperti sekarang adalah berkat dukungan keluarga.","sentence_template":"今こうして元気に働けるのは、家族の支えの [blank] です。"}'::jsonb, '{"selected":"おかげ"}'::jsonb, NULL, NULL, '～のは～のおかげです digunakan untuk menegaskan bahwa hasil baik terjadi berkat sesuatu/seseorang.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('de7796ab-8a10-54a5-b319-1da19bc849fe', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat dengan adjektiva-NA: 部屋が ___ おかげで、勉強に集中できます。', '{"options":["静かな","静かの","静かだ","静かで"],"translation":"Berkat kamar yang tenang, saya bisa berkonsentrasi belajar.","sentence_template":"部屋が [blank] おかげで、勉強に集中できます。"}'::jsonb, '{"selected":"静かな"}'::jsonb, NULL, NULL, 'Kata sifat-NA memakai な sebelum おかげで (静かなおかげで).', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b40a7fb-48b8-5042-b8c2-bab2461db9f1', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', NULL, 'reading', 'fill_blank', 'Pilih ungkapan respons yang paling alami saat ditanya kabar: ___ 、家族みんな元気です。', '{"options":["おかげさまで","そのせいで","それなのに","それにしては"],"translation":"Berkat doa Anda / Puji syukur, seluruh keluarga sehat.","sentence_template":"[blank] 、家族みんな元気です。"}'::jsonb, '{"selected":"おかげさまで"}'::jsonb, NULL, NULL, 'おかげさまで (okagesama de) adalah ungkapan sopan khas Jepang saat menyampaikan kabar baik dengan rendah hati.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d6e4d1e2-8b44-461a-b644-ad26cb924503', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', 'd1000019-0000-0000-0000-000000000010', 'listening', 'listening_choice', 'Dengarkan cerita pagi ini berikut. Mengapa pembicara tetap tepat waktu?', '{"options":[{"id":"opt_1","text":"Berkat berangkat lebih awal dari rumah, tetap tepat waktu ke rapat meski kereta terlambat"},{"id":"opt_2","text":"Terlambat rapat karena berangkat terlalu mepet"},{"id":"opt_3","text":"Rapat dibatalkan karena banyak peserta terlambat"},{"id":"opt_4","text":"Kereta tidak mengalami keterlambatan hari ini"}],"audio_text":"早めに家を出たおかげで、電車が遅延しても会議に間に合いました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '出たおかげで menyoroti keputusan baik yang menghasilkan dampak positif.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('253af661-d65e-4685-a208-4fd823f1f091', 'f2b79d5b-5679-5cdd-a3b6-b7fbbc242159', 'd1000019-0000-0000-0000-000000000010', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 最新の翻訳アプリがある___、海外出張もずっと楽になりました。', '{"options":["はずで","おかげで","うちに","せいで"],"translation":"Berkat adanya aplikasi terjemahan terbaru, dinas luar negeri pun jadi jauh lebih mudah.","sentence_template":"最新の翻訳アプリがある[blank]、海外出張もずっと楽になりました。"}'::jsonb, '{"selected":"おかげで"}'::jsonb, NULL, NULL, 'ある (bentuk biasa) + おかげで.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea84ed92-3005-5b85-9ab7-c5a15eea5f89', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi sasaran sikap: 目上の人 ___ 敬語を使うのがマナーです。', '{"options":["に対して","について","にとって","によって"],"translation":"Menggunakan bahasa hormat kepada orang yang lebih senior adalah etika.","sentence_template":"目上の人 [blank] 敬語を使うのがマナーです。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, 'Nomina + に対して menunjukkan sasaran sikap atau tindakan (kepada/terhadap).', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0fe354aa-f289-573d-a4c2-1e5c7e6bdd67', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Pilih bentuk yang menerangkan nomina: 環境問題 ___ 関心が年々高まっています。', '{"options":["に対する","に対して","に対した","に対します"],"translation":"Perhatian terhadap masalah lingkungan meningkat dari tahun ke tahun.","sentence_template":"環境問題 [blank] 関心が年々高まっています。"}'::jsonb, '{"selected":"に対する"}'::jsonb, NULL, NULL, 'Jika langsung menerangkan kata benda (関心 = perhatian), に対して berubah menjadi に対する.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a1e5640-872c-5940-88c6-1ac446d0850e', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat perbandingan: 兄が社交的なの ___ 、弟は物静かです。', '{"options":["に対して","のおかげで","のせいで","のはずで"],"translation":"Berbeda dengan kakak yang supel, adik pendiam.","sentence_template":"兄が社交的なの [blank] 、弟は物静かです。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, '[Bentuk Biasa] + のに対して digunakan untuk membandingkan dua hal yang kontras.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b18f5496-93ee-576e-bda2-670bab2e598f', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Saya menggunakan bahasa yang sopan terhadap pelanggan."', '{"romaji":"Okyakusama ni taishite teineina kotoba o tsukaimasu.","tokens":["丁寧な言葉を","お客様に","よって","対して","対する","使います。"],"target_translation":"Saya menggunakan bahasa yang sopan terhadap pelanggan."}'::jsonb, '["お客様に","対して","丁寧な言葉を","使います。"]'::jsonb, NULL, NULL, 'お客様に対して (terhadap pelanggan) + 丁寧な言葉を使います.', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('28d39099-b5fa-539a-80f4-7f8259ab3545', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Saya menjawab pertanyaan terhadap usulan ini."', '{"romaji":"Kono teian ni taisuru shitsumon ni kotaemasu.","tokens":["この提案に","ついて","答えます。","質問に","対して","対する"],"target_translation":"Saya menjawab pertanyaan terhadap usulan ini."}'::jsonb, '["この提案に","対する","質問に","答えます。"]'::jsonb, NULL, NULL, 'Karena langsung menerangkan nomina 質問, gunakan に対する.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('408b46ca-1f43-5566-9e1d-327bd228c752', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'listening', 'listening_choice', 'Apa perbandingan yang dijelaskan pembicara tentang dua wilayah tersebut?', '{"options":[{"id":"opt_1","text":"Pusat kota lebih murah sewanya daripada pinggiran kota"},{"id":"opt_2","text":"Pinggiran kota lebih ramai dan praktis transportasinya"},{"id":"opt_3","text":"Pusat kota praktis transportasinya, sedangkan pinggiran kota murah sewanya dan asri"},{"id":"opt_4","text":"Kedua wilayah memiliki biaya hidup yang hampir sama"}],"audio_text":"都心は交通が便利なに対して、郊外は家賃が安くて自然が豊かです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'Pembicara mengontraskan 都心 (pusat kota: transportasi praktis) dengan 郊外 (pinggiran: sewa murah dan kaya alam).', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('334dd510-43e9-475f-b403-fcf145216ab3', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: この会社は社員の健康管理___、とても積極的です。', '{"options":["のばかりに","のおかげで","のせいで","に対して"],"translation":"Perusahaan ini sangat proaktif terhadap manajemen kesehatan karyawan.","sentence_template":"この会社は社員の健康管理[blank]、とても積極的です。"}'::jsonb, '{"selected":"に対して"}'::jsonb, NULL, NULL, 'Kata benda + に対して menunjukkan sasaran sikap atau tindakan.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf127ed7-5e67-4382-bf81-0400fe9c95d2', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', 'd1000019-0000-0000-0000-000000000012', 'writing', 'sentence_builder', 'Susun kalimat: "Terhadap usulan baru tersebut, muncul banyak pendapat setuju."', '{"romaji":"Atarashii teian ni taishite, ooku no sansei iken ga demashita.","tokens":["対して、","賛成意見が","おかげで、","を","新しい","提案に","多くの","出ました。"],"target_translation":"Terhadap usulan baru tersebut, muncul banyak pendapat setuju."}'::jsonb, '["新しい","提案に","対して、","多くの","賛成意見が","出ました。"]'::jsonb, NULL, NULL, '提案に対して berarti ''terhadap usulan''.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c41e6180-26e3-57e3-8384-cbeb780a5e1f', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'listening', 'listening_choice', 'Bagaimana aturan pengajuan cuti di perusahaan tersebut?', '{"options":[{"id":"opt_1","text":"Cukup mengirim pesan singkat kepada rekan tim"},{"id":"opt_2","text":"Harus meminta izin lisan pada pagi hari cuti"},{"id":"opt_3","text":"Hanya boleh diajukan pada akhir bulan"},{"id":"opt_4","text":"Harus diajukan melalui sistem paling lambat seminggu sebelumnya"}],"audio_text":"有給休暇を取る場合は、一週間前までにシステムから申請することになっています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '一週間前までにシステムから申請することになっています berarti aturannya mengajukan lewat sistem maksimal 1 minggu sebelumnya.', 1, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7e1c4675-ad0d-5d13-8ece-09e27cb36e99', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'listening', 'listening_choice', 'Apa yang terjadi pada jadwal kunjungan klien besok?', '{"options":[{"id":"opt_1","text":"Diubah menjadi hari Rabu minggu depan"},{"id":"opt_2","text":"Dibatalkan sepenuhnya tanpa jadwal pengganti"},{"id":"opt_3","text":"Dimajukan menjadi sore ini"},{"id":"opt_4","text":"Dipindahkan ke ruang rapat lantai lima"}],"audio_text":"先方の都合により、明日の訪問は来週の水曜日に変更することになりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来週の水曜日に変更することになりました berarti diputuskan berubah ke hari Rabu minggu depan.', 2, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('357edba5-cc08-51e1-84dc-bcf86cbea4a8', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'listening', 'listening_choice', 'Apa yang harus dilakukan pengunjung saat masuk ke ruang server?', '{"options":[{"id":"opt_1","text":"Menitipkan tas di loker lantai dasar"},{"id":"opt_2","text":"Menuliskan nama di meja resepsionis saat masuk"},{"id":"opt_3","text":"Menunggu konfirmasi tertulis dari direktur"},{"id":"opt_4","text":"Memakai sepatu khusus laboratorium"}],"audio_text":"セキュリティのため、入室の際は受付で名前を記入することになっています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '受付で名前を記入することになっています berarti aturannya menuliskan nama di resepsionis.', 3, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1659715b-5271-594c-bbf2-5553b733fe78', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'reading', 'fill_blank', 'Pilih akhiran yang tepat untuk keputusan luar: 来年から制服が新しく ___ 。', '{"options":["なることになりました","なることにしました","なったことになりました","なるようになりました"],"translation":"Diputuskan bahwa mulai tahun depan seragamnya akan menjadi baru.","sentence_template":"来年から制服が新しく [blank] 。"}'::jsonb, '{"selected":"なることになりました"}'::jsonb, NULL, NULL, 'Perubahan seragam adalah keputusan organisasi/perusahaan, sehingga tepat memakai ～ことになりました (bukan ～ことにしました yang keputusan pribadi).', 4, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f6ed78d-b792-5fd2-8c97-3afa3728a544', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'reading', 'fill_blank', 'Lengkapi aturan asrama: この寮では夜十時以降、洗濯機を ___ ことになっています。', '{"options":["使わない","使う","使った","使って"],"translation":"Di asrama ini aturannya tidak boleh memakai mesin cuci setelah jam 10 malam.","sentence_template":"この寮では夜十時以降、洗濯機を [blank] ことになっています。"}'::jsonb, '{"selected":"使わない"}'::jsonb, NULL, NULL, 'Aturan larangan memakai Bentuk-NAI (使わない) + ことになっています.', 5, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('997eca14-a4a8-5ba9-9ae3-e67703177fd9', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman proyek: 予算の関係で、今回の計画は見直す ___ なりました。', '{"options":["ことに","ように","ものに","ところに"],"translation":"Karena masalah anggaran, diputuskan bahwa rencana kali ini akan ditinjau ulang.","sentence_template":"予算の関係で、今回の計画は見直す [blank] なりました。"}'::jsonb, '{"selected":"ことに"}'::jsonb, NULL, NULL, '見直すことになりました berarti diputuskan untuk meninjau ulang.', 6, '2026-11-25T18:49:03.231744+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c574697-be0f-470a-b9c0-b95bf0724c38', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan laporan berikut. Apa hasil rapat kemarin?', '{"options":[{"id":"opt_1","text":"Proyek tersebut ditunda hingga tahun depan"},{"id":"opt_2","text":"Pembicara mengundurkan diri dari proyek tersebut"},{"id":"opt_3","text":"Berdasarkan hasil rapat kemarin, pembicara diputuskan menjadi pemimpin proyek"},{"id":"opt_4","text":"Rapat kemarin belum menentukan pemimpin proyek"}],"audio_text":"先日の会議の結果、プロジェクトのリーダーを私が担当することになりました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '担当することになりました menyatakan penunjukan resmi dari rapat.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7c0f63a-484b-4634-a55f-ede5acbc9c89', 'f6f88020-c0f8-5335-84f9-0f74c479fb4b', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: うちの会社では、毎月第一金曜日に全体朝礼を行う___。', '{"options":["ようにしました","ことにします","ばかりです","ことになっています"],"translation":"Di perusahaan kami, sudah menjadi aturan untuk mengadakan apel pagi bersama setiap Jumat pertama tiap bulan.","sentence_template":"うちの会社では、毎月第一金曜日に全体朝礼を行う[blank]。"}'::jsonb, '{"selected":"ことになっています"}'::jsonb, NULL, NULL, '～ことになっています cocok untuk menjelaskan peraturan atau jadwal tetap perusahaan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('58fe9f32-a63e-4b99-a847-3a6da5d43e83', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算の都合により、計画を一部見直す___。', '{"options":["ことにしました","ところです","ことになりました","ようになりました"],"translation":"Karena pertimbangan anggaran, diputuskan untuk meninjau ulang sebagian rencana.","sentence_template":"予算の都合により、計画を一部見直す[blank]。"}'::jsonb, '{"selected":"ことになりました"}'::jsonb, NULL, NULL, '見直すことになりました menandakan keputusan resmi yang dipengaruhi faktor eksternal (anggaran).', 1, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c35e3efb-1eba-4a67-8a15-767a65a77fd1', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 図書館で借りたDVDは、一週間以内に返却する___。', '{"options":["ことになっています","ことにしました","はずです","ようにします"],"translation":"DVD yang dipinjam di perpustakaan aturannya dikembalikan dalam waktu satu minggu.","sentence_template":"図書館で借りたDVDは、一週間以内に返却する[blank]。"}'::jsonb, '{"selected":"ことになっています"}'::jsonb, NULL, NULL, '返却することになっています menjelaskan ketentuan perpustakaan.', 2, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0550d77a-dae4-4e69-b359-bfd9d5d6f070', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan kabar kantor berikut. Kebijakan baru apa yang diputuskan?', '{"options":[{"id":"opt_1","text":"Kerja jarak jauh wajib dilakukan setiap hari tanpa kecuali"},{"id":"opt_2","text":"Kabarnya mulai bulan depan kerja jarak jauh diizinkan hingga dua hari per minggu"},{"id":"opt_3","text":"Mulai bulan depan semua karyawan dilarang kerja jarak jauh"},{"id":"opt_4","text":"Perusahaan membatalkan kebijakan kerja jarak jauh"}],"audio_text":"来月からテレワークが週二日まで認められることになったそうですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '認められることになった menyatakan aturan baru yang resmi disetujui.', 3, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85d5da92-fea5-4764-b663-2ac6303f6bf4', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Pesta akhir tahun ini diputuskan akan diadakan di hotel depan stasiun."', '{"romaji":"Kotoshi no bounenkai wa ekimae no hoteru de hiraku koto ni narimashita.","tokens":["開く","忘年会は","今年の","ホテルで","駅前の","開いた","が","ことに","なりました。"],"target_translation":"Pesta akhir tahun ini diputuskan akan diadakan di hotel depan stasiun."}'::jsonb, '["今年の","忘年会は","駅前の","ホテルで","開く","ことに","なりました。"]'::jsonb, NULL, NULL, '開く (mengadakan) + ことになりました.', 4, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bc625db3-fa08-4b52-94b4-f57ca94a7ec3', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 急な出張が入ったため、日曜日の旅行には行けない___。', '{"options":["ことになりました","ようにしました","ことにしました","おかげです"],"translation":"Karena ada dinas mendadak, jadinya saya tidak bisa ikut wisata hari Minggu.","sentence_template":"急な出張が入ったため、日曜日の旅行には行けない[blank]。"}'::jsonb, '{"selected":"ことになりました"}'::jsonb, NULL, NULL, '行けないことになりました menunjukkan pembatalan akibat keadaan di luar kendali.', 5, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('737d5117-39b9-47d7-a36e-18cca706617b', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di pabrik ini sudah menjadi aturan wajib untuk mengecek keselamatan sebelum bekerja."', '{"romaji":"Kono koujou de wa, sagyou mae ni kanarazu anzen kakunin o suru koto ni natte imasu.","display_text":"この工場では、作業前に必ず安全確認をすることになっています。","phonetic_breakdown":["ko-no","kou-jou-de-wa","sa-gyou-ma-e-ni","ka-na-ra-zu","an-zen-ka-ku-nin-o","su-ru-ko-to-ni","nat-te-i-ma-su"]}'::jsonb, '{"expected_transcript":"この工場では、作業前に必ず安全確認をすることになっています。"}'::jsonb, NULL, NULL, 'することになっています menyatakan standar operasional tetap.', 6, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef66a95b-6aa9-4672-b33a-d7cfbb689c93', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'listening', 'listening_choice', 'Dengarkan panduan kelas berikut. Apa aturan durasi presentasinya?', '{"options":[{"id":"opt_1","text":"Seminar semester ini tidak memiliki sesi presentasi"},{"id":"opt_2","text":"Hanya satu orang yang akan melakukan presentasi"},{"id":"opt_3","text":"Pada seminar semester ini, ketentuannya setiap orang presentasi maksimal 10 menit"},{"id":"opt_4","text":"Setiap peserta wajib presentasi minimal 30 menit"}],"audio_text":"今学期の発表会は、一人十分以内でプレゼンすることになっています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'プレゼンすることになっています menyatakan aturan yang sudah ditetapkan dosen/panitia.', 7, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('760996e3-a34f-45ce-9ff3-fc3e1b35ebc3', 'ff0dfad2-38e6-4b6c-8475-1857360c2506', 'd1000019-0000-0000-0000-000000000009', 'writing', 'sentence_builder', 'Susun kalimat: "Dijadwalkan minggu depan tiga karyawan baru akan bergabung."', '{"romaji":"Raishuu atarashii shain ga sanmei nyuusha suru koto ni natte imasu.","tokens":["社員が","三名","入社する","新しい","なっています。","を","ことに","入社した","来週"],"target_translation":"Dijadwalkan minggu depan tiga karyawan baru akan bergabung."}'::jsonb, '["来週","新しい","社員が","三名","入社する","ことに","なっています。"]'::jsonb, NULL, NULL, 'ことになっています juga dipakai untuk jadwal resmi yang telah ditetapkan.', 8, '2026-11-26T03:34:06.127162+00:00') ON CONFLICT DO NOTHING;
